.live-score-row::before{ left: 0; background: linear-gradient(180deg, var(--home-primary), var(--home-secondary)); }
.live-score-row::after{ right: 0; background: linear-gradient(180deg, var(--away-primary), var(--away-secondary)); }
.live-club{
