}
.club-context em{ color: var(--muted); font-style: normal; font-size: .65rem; }
.offer-card .team-label{ margin-right: 3px; }
.job-card.team-tone{
  border-color: color-mix(in srgb, var(--team-primary) 36%, var(--line));
