  width: 30px;
  height: 36px;
  max-width: 30px;
  max-height: 36px;
}

.setup-mode-switch{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--panel);
}
.setup-mode-switch button{
  min-height: 44px;
  border: 0;
  border-radius: 11px;
  color: var(--muted);
  background: transparent;
