   V286 — gol rápido, vencedor discreto e estatísticas coerentes
   ========================================================= */
/* O gol do clube controlado informa somente o acontecimento, o clube e o
   placar atual. A entrada e a saída são curtas para não esconder o campo. */
.live-pitch-shell .live-user-goal-overlay, .live-pitch-shell .live-event-overlay.is-user-goal{
  width: min(360px,calc(100% - 18px)) !important;
  max-width: calc(100% - 18px) !important;
  min-height: 62px !important;
  grid-template-columns: 42px minmax(0,1fr) !important;
  gap: 9px !important;
  padding: 8px 11px !important;
  border-width: 1px !important;
  border-radius: 14px !important;
  background: color-mix(in srgb,#07120d 92%,#168555 8%) !important;
  box-shadow: 0 10px 24px rgba(0,0,0,.34),inset 0 -2px 0 #2dbf73 !important;
  opacity: 0;
  transform: translate(-50%,-6px) scale(.98) !important;
  transition: opacity .22s ease,transform .22s ease !important;
  animation: none !important;
}
.live-pitch-shell .live-user-goal-overlay.is-visible, .live-pitch-shell .live-event-overlay.is-user-goal.is-visible{
  opacity: 1;
  transform: translate(-50%,0) scale(1) !important;
  animation: live-user-goal-fade-in .18s ease-out both !important;
}
.live-pitch-shell .live-user-goal-overlay::before, .live-pitch-shell .live-user-goal-overlay::after{ display: none !important; }
.live-pitch-shell .live-user-goal-overlay .live-event-team-crest{
  width: 42px !important;
  height: 46px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
}
.live-pitch-shell .live-user-goal-overlay .live-event-team-crest .crest{
  width: 38px !important;
  height: 42px !important;
}
.live-pitch-shell .live-user-goal-overlay > div{ min-width: 0; display: grid; align-content: center; gap: 3px; }
.live-pitch-shell .live-user-goal-overlay strong, .live-pitch-shell .live-user-goal-overlay.is-goal strong{
  color: #fff !important;
  font-size: 1rem !important;
  line-height: 1 !important;
  letter-spacing: .07em !important;
  white-space: nowrap !important;
}
.live-pitch-shell .live-user-goal-overlay small{
  color: rgba(255,255,255,.9) !important;
  font-size: .64rem !important;
  font-weight: 600 !important;
  line-height: 1.2 !important;
  letter-spacing: 0 !important;
  white-space: normal !important;
}
@keyframes live-user-goal-fade-in {
  from { opacity: 0; transform: translate(-50%,-6px) scale(.98); }
  to { opacity: 1; transform: translate(-50%,0) scale(1); }
}

