}
.landing-v99 .setup-world-country-picker{
  margin-top: 8px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 65%, transparent);
}
.landing-v99 .setup-world-country-picker > summary{
  min-height: 44px;
  padding: 8px 10px;
  display: grid;
  grid-template-columns: 22px minmax(0,1fr);
  align-items: center;
  gap: 8px;
  list-style: none;
  cursor: pointer;
}
.landing-v99 .setup-world-country-picker > summary::-webkit-details-marker{ display: none; }
.landing-v99 .setup-world-country-picker > summary > i{ color: var(--primary); }
.landing-v99 .setup-world-country-picker > summary > span{ min-width: 0; display: grid; gap: 2px; }
.landing-v99 .setup-world-country-picker > summary strong{ font-size: .63rem; color: var(--text); }
.landing-v99 .setup-world-country-picker > summary small{ font-size: .5rem; color: var(--muted); line-height: 1.3; }
.landing-v99 .setup-world-country-tools{
  padding: 0 8px 7px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.landing-v99 .setup-world-country-tools .btn{
  min-width: 0;
  min-height: 34px;
  padding-inline: 7px;
  font-size: .5rem;
}
.landing-v99 .setup-world-country-list{
  max-height: 300px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 8px 8px;
  display: grid;
  gap: 5px;
}
.landing-v99 .setup-world-country{
  min-width: 0;
  padding: 7px 8px;
  display: grid;
  grid-template-columns: 18px minmax(0,1fr);
  grid-template-areas: "check name" "check meta";
  align-items: center;
  column-gap: 7px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel-2) 68%, transparent);
}
.landing-v99 .setup-world-country input{ grid-area: check; width: 16px; height: 16px; margin: 0; accent-color: var(--primary); }
.landing-v99 .setup-world-country > span{ grid-area: name; min-width: 0; color: var(--text); font-size: .6rem; font-weight: 650; }
.landing-v99 .setup-world-country > small{ grid-area: meta; color: var(--muted); font-size: .49rem; }
.landing-v99 .setup-world-country.is-selected{ border-color: color-mix(in srgb, var(--primary) 38%, var(--line)); }
.landing-v99 .setup-world-country.is-mandatory{ background: color-mix(in srgb, var(--primary) 8%, var(--panel)); }
.landing-v99 .setup-world-tiers{
  margin-top: 8px;
  display: grid;
  gap: 4px;
  color: var(--muted);
