}
.landing-v99 .setup-world-tiers > span{ display: flex; align-items: center; gap: 5px; }
.landing-v99 .setup-world-tiers i{ width: 15px; color: var(--primary); text-align: center; }
.landing-v99 .setup-world-tiers b{ color: var(--text); }

/* V326 — Mundo da carreira dentro da central de competições. O bloco é somente
   leitura durante a temporada para não criar classificações retroativas ao
   ativar/desativar países no meio do calendário. */
.career-world-strip{
  display: grid;
  gap: 10px;
  margin: 0 0 12px;
  padding: 12px;
  border: 1px solid var(--line, rgba(127, 127, 127, .22));
  border-radius: 16px;
  background: var(--surface, rgba(255, 255, 255, .04));
}
.career-world-strip-title{
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.career-world-strip-title > i{
  width: 30px;
  flex: 0 0 30px;
  text-align: center;
}
.career-world-strip-title span{
  display: grid;
  gap: 1px;
  min-width: 0;
}
.career-world-strip-title small{
  color: var(--muted, #8b929a);
  font-size: .72rem;
}
.career-world-strip-title strong{
  font-size: .92rem;
}
.career-world-strip-countries{
  display: flex;
  gap: 7px;
  overflow-x: auto;
  padding: 1px 1px 4px;
  scrollbar-width: thin;
}
.career-world-country{
  display: grid;
  flex: 0 0 auto;
  gap: 1px;
  min-width: 104px;
  padding: 7px 9px;
  border: 1px solid var(--line, rgba(127, 127, 127, .22));
  border-radius: 12px;
  background: rgba(127, 127, 127, .06);
  white-space: nowrap;
  font-size: .78rem;
}
.career-world-country small{
  color: var(--muted, #8b929a);
  font-size: .66rem;
}
.career-world-country.is-full{
  border-color: color-mix(in srgb, var(--accent, #1f8d55) 62%, transparent);
  background: color-mix(in srgb, var(--accent, #1f8d55) 10%, transparent);
}

/* ===== V328 · planejamento do Mundo da carreira =====
   As mudanças são apenas agendadas durante a temporada. A lista pode conter
   todos os países do catálogo sem alterar o calendário que já está em curso. */
.career-world-plan-status{
  display: grid;
  grid-template-columns: 24px minmax(0,1fr);
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  border: 1px solid var(--line, rgba(127,127,127,.22));
  border-radius: 12px;
  background: rgba(127,127,127,.05);
}
.career-world-plan-status > i{ color: var(--muted); text-align: center; }
.career-world-plan-status > span{ min-width: 0; display: grid; gap: 2px; }
.career-world-plan-status strong{ font-size: .72rem; }
.career-world-plan-status small{ color: var(--muted); font-size: .62rem; line-height: 1.35; }
.career-world-plan-status.is-pending{
  border-color: color-mix(in srgb, var(--accent, #1f8d55) 42%, var(--line));
  background: color-mix(in srgb, var(--accent, #1f8d55) 8%, transparent);
}
.career-world-plan-status.is-pending > i{ color: var(--accent, #1f8d55); }
.career-world-planner{
  overflow: hidden;
  border: 1px solid var(--line, rgba(127,127,127,.22));
  border-radius: 13px;
  background: color-mix(in srgb, var(--panel, #15191f) 86%, transparent);
}
.career-world-planner > summary{
  min-height: 46px;
  padding: 9px 10px;
  display: grid;
  grid-template-columns: 24px minmax(0,1fr);
  align-items: center;
  gap: 8px;
  list-style: none;
  cursor: pointer;
}
.career-world-planner > summary::-webkit-details-marker{ display: none; }
.career-world-planner > summary > i{ color: var(--accent, #1f8d55); text-align: center; }
.career-world-planner > summary > span{ min-width: 0; display: grid; gap: 2px; }
.career-world-planner > summary strong{ font-size: .7rem; }
.career-world-planner > summary small{ color: var(--muted); font-size: .58rem; line-height: 1.35; }
.career-world-planner-tools, .career-world-planner-actions{
  padding: 0 9px 8px;
  display: grid;
  gap: 6px;
}
.career-world-planner-tools{ grid-template-columns: 1fr 1fr; }
.career-world-planner-actions{ grid-template-columns: 1fr; }
.career-world-planner-tools .btn, .career-world-planner-actions .btn{ min-width: 0; }
.career-world-planner-preview{
  margin: 0 9px 8px;
  padding: 7px 9px;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel-2, #20262e) 72%, transparent);
  color: var(--muted);
}
.career-world-planner-preview strong{ color: var(--text); font-size: .64rem; }
.career-world-planner-preview span{ font-size: .56rem; text-align: right; }
.career-world-planner-list{
  max-height: 330px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 9px 9px;
  display: grid;
  gap: 5px;
}
.career-world-planner-country{
  min-width: 0;
  padding: 7px 8px;
  display: grid;
  grid-template-columns: 18px minmax(0,1fr);
  grid-template-areas: "check name" "check meta";
  align-items: center;
  column-gap: 7px;
  border: 1px solid var(--line, rgba(127,127,127,.22));
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel-2, #20262e) 66%, transparent);
}
.career-world-planner-country input{ grid-area: check; width: 16px; height: 16px; margin: 0; accent-color: var(--accent, #1f8d55); }
.career-world-planner-country > span{ grid-area: name; min-width: 0; color: var(--text); font-size: .64rem; font-weight: 650; }
.career-world-planner-country > small{ grid-area: meta; color: var(--muted); font-size: .53rem; }
.career-world-planner-country.is-selected{ border-color: color-mix(in srgb, var(--accent, #1f8d55) 40%, var(--line)); }
.career-world-planner-country.is-mandatory{ background: color-mix(in srgb, var(--accent, #1f8d55) 9%, var(--panel)); }
.career-world-planner-note{
  margin: 0 9px 9px;
  padding: 7px 8px;
  display: flex;
  gap: 6px;
  align-items: flex-start;
  border-radius: 10px;
  background: rgba(127,127,127,.05);
  color: var(--muted);
  font-size: .55rem;
  line-height: 1.4;
}
.career-world-planner-note i{ margin-top: 1px; color: var(--accent, #1f8d55); }


/* =========================================================
   V329 · campo ao vivo opcional de verdade
   ========================================================= */
/* Campo desligado mantém a mesma arquitetura atual do Ao Vivo: cabeçalho,
   placar/comandos e painel de informações. A regra antiga ainda reservava
   cinco linhas de versões anteriores e comprimía o workspace das abas a
   poucos pixels (40px eram consumidos só pela barra de abas). */
.match-screen.is-live-pitch-disabled{
  grid-template-rows: 38px auto minmax(0,1fr) !important;
}
.match-screen.is-live-pitch-disabled > .pitch-score{
  height: auto !important;
  min-height: 86px !important;
  grid-template-rows: 54px 28px 46px !important;
  padding: 5px !important;
}
.match-screen.is-live-pitch-disabled .pitch-score > .fixture-card{
  height: 54px !important;
  min-height: 54px !important;
  padding-inline: 4px !important;
}
.match-screen.is-live-pitch-disabled .pitch-score .vs{ font-size: .56rem !important; }
.match-screen.is-live-pitch-disabled .pitch-score .fixture-team .crest{ width: 27px !important; height: 33px !important; }
.match-screen.is-live-pitch-disabled .pitch-score .fixture-team strong{ max-width: 100px !important; font-size: .68rem !important; }
.live-pitch-shell.is-pitch-disabled{
  height: 28px !important;
  min-height: 28px !important;
  grid-template-rows: 28px !important;
  background: #090d12 !important;
  border: 1px solid rgba(255,255,255,.08);
}
.live-pitch-shell.is-pitch-disabled .live-pitch-caption{
  height: 28px !important;
  min-height: 28px !important;
  background: #050709 !important;
}
.live-pitch-shell.is-pitch-disabled :is(.live-pitch-canvas,.live-event-overlay){ display: none !important; }
.observer-screen.observer-live-mode.is-live-pitch-disabled, .observer-screen.observer-live-mode.is-observer-finished.is-live-pitch-disabled{
  grid-template-rows: 38px auto minmax(0,1fr) !important;
}
.observer-screen.observer-live-mode.is-live-pitch-disabled > .observer-pitch-score, .observer-screen.observer-live-mode.is-observer-finished.is-live-pitch-disabled > .observer-pitch-score{
  height: auto !important;
  min-height: 126px !important;
  grid-template-rows: 54px 28px 44px !important;
}
.observer-screen.is-live-pitch-disabled .observer-pitch-panel{ height: 28px !important; min-height: 28px !important; }

/* =========================================================
   V329 · mercado mundial de técnicos
   ========================================================= */
.manager-market-layout{ display: grid; gap: 10px; padding-bottom: 14px; }
.manager-market-hero{ display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.manager-market-hero h3{ margin: 2px 0 5px; }
.manager-market-hero p{ margin: 0; color: var(--muted); line-height: 1.45; }
.manager-market-hero-icon{ display: grid; place-items: center; width: 48px; height: 48px; flex: 0 0 48px; border-radius: 50%; background: color-mix(in srgb,var(--primary) 16%,var(--panel)); color: var(--primary); font-size: 1.2rem; }
.manager-market-scorecards{ display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; }
.manager-market-scorecards article{ min-width: 0; padding: 10px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel); }
.manager-market-scorecards small, .manager-market-scorecards span{ display: block; color: var(--muted); font-size: .67rem; }
.manager-market-scorecards strong{ display: block; margin: 2px 0; font-size: 1.32rem; color: var(--text); }
.manager-market-vacancies, .manager-market-feed, .manager-market-ranking{ display: grid; gap: 6px; }
.manager-market-vacancy{ width: 100%; display: grid; grid-template-columns: 34px minmax(0,1fr) auto; align-items: center; gap: 8px; padding: 8px; text-align: left; border: 1px solid var(--line); border-radius: 9px; background: color-mix(in srgb,var(--panel) 94%,var(--primary) 6%); color: var(--text); }
.manager-market-vacancy .crest{ width: 28px; height: 32px; }
.manager-market-vacancy strong, .manager-market-vacancy small{ display: block; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.manager-market-vacancy small{ color: var(--muted); font-size: .66rem; }
.manager-market-event{ display: grid; grid-template-columns: 30px minmax(0,1fr) auto; gap: 7px; align-items: center; padding: 8px; border: 1px solid var(--line); border-radius: 9px; }
.manager-market-event > span{ display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: color-mix(in srgb,var(--primary) 12%,var(--panel)); color: var(--primary); }
.manager-market-event.is-international > span{ background: color-mix(in srgb,#4f87ff 16%,var(--panel)); color: #6aa0ff; }
.manager-market-event strong, .manager-market-event small{ display: block; }
.manager-market-event small{ color: var(--muted); font-size: .66rem; line-height: 1.35; }
.manager-market-event em{ color: var(--muted); font-size: .6rem; font-style: normal; white-space: nowrap; }
.manager-market-ranking article{ display: grid; grid-template-columns: 26px minmax(0,1fr) 34px; gap: 8px; align-items: center; padding: 7px 8px; border-bottom: 1px solid var(--line); }
.manager-market-ranking article > b{ color: var(--muted); }
.manager-market-ranking article > span{ text-align: right; font-weight: 700; color: var(--primary); }
.manager-market-ranking strong, .manager-market-ranking small{ display:block; }
.manager-market-ranking small{ color: var(--muted); font-size: .65rem; }


/* V330 — reputação doméstica, continental e mundial do técnico. */
.manager-reputation-reach{ overflow: hidden; }
.manager-reputation-scope-grid{ display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 8px; margin-top: 12px; }
.manager-reputation-scope-grid article{ display: grid; grid-template-columns: auto minmax(0,1fr); align-items: center; gap: 9px; min-width: 0; padding: 11px 9px; border: 1px solid var(--line); border-radius: 14px; background: var(--panel-2); }
.manager-reputation-scope-grid article > span{ display: grid; place-items: center; width: 31px; height: 31px; border-radius: 10px; color: var(--primary); background: color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.manager-reputation-scope-grid small, .manager-reputation-scope-grid strong, .manager-reputation-scope-grid em{ display: block; min-width: 0; }
.manager-reputation-scope-grid small{ color: var(--muted); font-size: .55rem; }
.manager-reputation-scope-grid strong{ margin-top: 1px; font-size: 1.08rem; line-height: 1; }
.manager-reputation-scope-grid em{ margin-top: 3px; overflow: hidden; color: var(--muted); font-size: .53rem; font-style: normal; text-overflow: ellipsis; white-space: nowrap; }
.manager-reputation-markets{ display: grid; gap: 7px; margin-top: 10px; }
.manager-reputation-markets > small{ color: var(--muted); font-size: .61rem; }
.manager-reputation-markets > div{ display: flex; flex-wrap: wrap; gap: 6px; }
.manager-reputation-markets span{ display: inline-flex; align-items: center; gap: 6px; max-width: 100%; padding: 5px 8px; border: 1px solid var(--line); border-radius: 999px; background: var(--panel-2); font-size: .59rem; }
.manager-reputation-markets span b{ overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.manager-reputation-markets span em{ color: var(--primary); font-style: normal; font-weight: 700; }
.manager-reputation-history{ margin-top: 10px; border-top: 1px solid var(--line); padding-top: 9px; }
.manager-reputation-history summary{ cursor: pointer; color: var(--muted); font-size: .62rem; }
.manager-reputation-history > div{ display: grid; gap: 6px; margin-top: 8px; }
.manager-reputation-history > div > span{ display: grid; grid-template-columns: auto minmax(0,1fr) auto; align-items: center; gap: 7px; padding: 7px 8px; border-radius: 9px; background: var(--panel-2); font-size: .58rem; }
.manager-reputation-history b{ min-width: 28px; }
.manager-reputation-history em{ overflow: hidden; font-style: normal; text-overflow: ellipsis; white-space: nowrap; }
.manager-reputation-history small{ color: var(--muted); font-size: .52rem; white-space: nowrap; }
.manager-reputation-history .is-positive{ color: var(--success,#32a866); }
.manager-reputation-history .is-negative{ color: var(--danger,#d9534f); }

/* V332 — Giro pelo Mundo: feed compacto, legível e coerente com a UI mobile. */
.world-digest-layout{ display:grid; gap:10px; padding-bottom:14px; }
.world-digest-hero{ display:flex; align-items:center; justify-content:space-between; gap:12px; }
.world-digest-hero h3{ margin:2px 0 5px; }
.world-digest-hero p{ margin:0; color:var(--muted); line-height:1.45; }
.world-digest-hero-icon{ display:grid; place-items:center; width:48px; height:48px; flex:0 0 48px; border-radius:50%; background:color-mix(in srgb,var(--primary) 16%,var(--panel)); color:var(--primary); font-size:1.2rem; }
.world-digest-scorecards{ display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
.world-digest-scorecards article:last-child{ grid-column:1 / -1; }
.world-digest-scorecards article{ min-width:0; padding:10px; border:1px solid var(--line); border-radius:10px; background:var(--panel); }
.world-digest-scorecards small, .world-digest-scorecards span{ display:block; color:var(--muted); font-size:.64rem; line-height:1.25; }
.world-digest-scorecards strong{ display:block; margin:2px 0; font-size:1.25rem; color:var(--text); }
.world-digest-editions{ display:grid; gap:9px; }
.world-digest-issue{ padding:10px; }
.world-digest-issue.is-latest{ border-color:color-mix(in srgb,var(--primary) 42%,var(--line)); }
.world-digest-issue > header{ display:flex; align-items:flex-start; justify-content:space-between; gap:8px; margin-bottom:8px; }
.world-digest-issue h3{ margin:2px 0 0; font-size:.94rem; }
.world-digest-country-strip{ flex:0 0 auto; white-space:nowrap; letter-spacing:1px; font-size:.9rem; }
.world-digest-feed{ display:grid; gap:6px; }
.world-digest-item{ width:100%; min-width:0; display:grid; grid-template-columns:30px minmax(0,1fr) auto; align-items:center; gap:8px; padding:8px; text-align:left; border:1px solid var(--line); border-radius:9px; background:color-mix(in srgb,var(--panel) 95%,var(--primary) 5%); color:var(--text); }
button.world-digest-item{ cursor:pointer; }
.world-digest-kind{ display:grid; place-items:center; width:28px; height:28px; border-radius:50%; background:color-mix(in srgb,var(--primary) 12%,var(--panel)); color:var(--primary); }
.world-digest-item small, .world-digest-item strong, .world-digest-item p{ display:block; min-width:0; }
.world-digest-item small{ color:var(--muted); font-size:.62rem; }
.world-digest-item strong{ margin-top:1px; font-size:.78rem; }
.world-digest-item p{ margin:2px 0 0; color:var(--muted); font-size:.67rem; line-height:1.3; }
.world-digest-empty{ padding:22px 14px; text-align:center; }
.world-digest-empty > span{ display:grid; place-items:center; width:44px; height:44px; margin:0 auto 8px; border-radius:50%; background:color-mix(in srgb,var(--primary) 12%,var(--panel)); color:var(--primary); }
.world-digest-empty h3{ margin:0 0 5px; }
.world-digest-empty p{ margin:0 auto; max-width:44rem; color:var(--muted); line-height:1.45; }


/* ===== V333 · Passaporte do técnico ===== */
.manager-passport-panel{ overflow: hidden; }
.manager-passport-route{
  display: flex;
  align-items: center;
  gap: 7px;
  overflow-x: auto;
  padding: 4px 1px 12px;
  scrollbar-width: thin;
}
.manager-passport-route > span{
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  gap: 3px;
  min-width: 54px;
  padding: 8px 7px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel-2);
  font-size: 1.25rem;
}
.manager-passport-route > span small{
  max-width: 74px;
  overflow: hidden;
  color: var(--muted);
  font-size: .52rem;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.manager-passport-route > i{ flex: 0 0 auto; color: var(--muted); font-size: .62rem; }
.manager-passport-summary{
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  gap: 6px;
  margin: 2px 0 12px;
}
.manager-passport-summary article{
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 9px 5px;
  text-align: center;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--panel-2);
}
.manager-passport-summary small{ color: var(--muted); font-size: .5rem; overflow: hidden; text-overflow: ellipsis; }
.manager-passport-summary strong{ font-size: .92rem; }
.manager-passport-stints{ display: grid; gap: 9px; }
.manager-passport-stint{
  display: grid;
  gap: 9px;
  padding: 11px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--panel-2);
}
.manager-passport-stint.is-active{ border-color: color-mix(in srgb,var(--accent) 48%,var(--border)); }
.manager-passport-stint-head{ display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 9px; align-items: center; }
.manager-passport-stint-head > div{ display: grid; min-width: 0; gap: 2px; }
.manager-passport-stint-head small, .manager-passport-stint-head em{ color: var(--muted); font-size: .56rem; font-style: normal; }
.manager-passport-stint-head strong{ overflow: hidden; font-size: .8rem; text-overflow: ellipsis; white-space: nowrap; }
.manager-passport-country-mark{ display: grid; place-items: center; width: 35px; height: 35px; border-radius: 0; background: transparent; font-size: 1.25rem; }
.manager-passport-active{ align-self: start; padding: 4px 6px; border-radius: 999px; color: var(--accent); background: color-mix(in srgb,var(--accent) 12%,transparent); font-size: .52rem; font-weight: 700; }
.manager-passport-stats{ display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 5px; }
.manager-passport-stats span{ display: grid; gap: 2px; padding: 6px 2px; text-align: center; border-radius: 9px; background: var(--panel); }
.manager-passport-stats small{ color: var(--muted); font-size: .48rem; }
.manager-passport-stats b{ font-size: .72rem; }
.manager-passport-goals{ display: flex; flex-wrap: wrap; gap: 5px 10px; color: var(--muted); font-size: .58rem; }
.manager-passport-titles{ display: flex; flex-wrap: wrap; gap: 6px; }
.manager-passport-titles > span{ display: inline-flex; align-items: center; gap: 4px; padding: 5px 7px; border-radius: 9px; background: color-mix(in srgb,#d6a32b 12%,var(--panel)); font-size: .56rem; }
.manager-passport-titles > span small{ color: var(--muted); }
.manager-passport-no-title{ color: var(--muted); font-size: .56rem; }

/* V334 — Coeficientes continentais e força dinâmica entre países. A composição
   nasce para telas pequenas: ranking compacto, sem tabela horizontal obrigatória. */
.country-coefficient-layout{ display:grid; gap:10px; padding-bottom:14px; }
.country-coefficient-hero{ display:flex; align-items:center; justify-content:space-between; gap:12px; }
.country-coefficient-hero h3{ margin:2px 0 5px; }
.country-coefficient-hero p{ margin:0; color:var(--muted); line-height:1.45; }
.country-coefficient-hero-icon{ display:grid; place-items:center; width:48px; height:48px; flex:0 0 48px; border-radius:50%; background:color-mix(in srgb,var(--primary) 16%,var(--panel)); color:var(--primary); font-size:1.15rem; }
.country-coefficient-scorecards{ display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
.country-coefficient-scorecards article:last-child{ grid-column:1 / -1; }
.country-coefficient-scorecards article{ min-width:0; padding:10px; border:1px solid var(--line); border-radius:10px; background:var(--panel); }
.country-coefficient-scorecards small, .country-coefficient-scorecards span{ display:block; color:var(--muted); font-size:.64rem; line-height:1.25; }
.country-coefficient-scorecards strong{ display:block; margin:2px 0; color:var(--text); font-size:1.12rem; }
.country-coefficient-explain{ display:grid; grid-template-columns:28px minmax(0,1fr); gap:8px; align-items:start; padding:10px; }
.country-coefficient-explain > span{ display:grid; place-items:center; width:28px; height:28px; border-radius:50%; background:color-mix(in srgb,var(--primary) 12%,var(--panel)); color:var(--primary); }
.country-coefficient-explain p{ margin:0; color:var(--muted); font-size:.69rem; line-height:1.42; }
.country-coefficient-group{ padding:10px; }
.country-coefficient-group > header{ display:flex; align-items:flex-start; justify-content:space-between; gap:8px; margin-bottom:7px; }
.country-coefficient-group h3{ margin:2px 0 0; font-size:.94rem; }
.country-coefficient-list{ display:grid; gap:6px; }
.country-coefficient-row{ min-width:0; display:grid; grid-template-columns:28px minmax(0,1fr) 50px 43px; grid-template-rows:auto auto auto; align-items:center; column-gap:7px; row-gap:5px; padding:8px; border:1px solid var(--line); border-radius:9px; background:color-mix(in srgb,var(--panel) 96%,var(--primary) 4%); }
.country-coefficient-rank{ grid-row:1 / 4; align-self:stretch; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; border-right:1px solid var(--line); padding-right:6px; }
.country-coefficient-rank > strong{ font-size:.92rem; }
.country-coefficient-rank-move{ font-size:.53rem; line-height:1; }
.country-coefficient-rank-move.is-up, .country-coefficient-slot.is-up strong{ color:var(--success,#238a57); }
.country-coefficient-rank-move.is-down, .country-coefficient-slot.is-down strong{ color:var(--danger,#c43c45); }
.country-coefficient-country{ min-width:0; }
.country-coefficient-country strong, .country-coefficient-country small{ display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.country-coefficient-country strong{ font-size:.76rem; }
.country-coefficient-country small{ margin-top:1px; color:var(--muted); font-size:.57rem; }
.country-coefficient-number, .country-coefficient-trend{ text-align:right; }
.country-coefficient-number small, .country-coefficient-slot small, .country-coefficient-form small{ display:block; color:var(--muted); font-size:.55rem; }
.country-coefficient-number strong{ display:block; font-size:.8rem; }
.country-coefficient-trend{ display:flex; align-items:center; justify-content:flex-end; gap:3px; font-size:.61rem; }
.country-coefficient-trend > span{ color:var(--muted); }
.country-coefficient-slot{ grid-column:2 / 5; min-width:0; }
.country-coefficient-slot strong{ display:block; font-size:.62rem; white-space:nowrap; }
.country-coefficient-form{ grid-column:2 / 5; grid-row:3; min-width:0; text-align:left; }
.country-coefficient-form strong{ display:block; font-size:.61rem; white-space:nowrap; }

/* ===== V335 · processamento cooperativo global =====
   O overlay aparece somente durante tarefas reais. Ele bloqueia novos comandos
   enquanto o estado está sendo alterado, mas não muda o fluxo/scroll da página,
   evitando saltos quando termina. Não depende de media query: já nasce para a
   menor largura suportada pelo jogo. */
.app-task-overlay{
  position: fixed;
  inset: 0;
  z-index: 12000;
  display: grid;
  place-items: center;
  padding: max(12px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left));
  background: color-mix(in srgb,#06100b 64%,transparent);
  -webkit-backdrop-filter: blur(5px);
  backdrop-filter: blur(5px);
  opacity: 0;
  pointer-events: none;
  overscroll-behavior: contain;
  transition: opacity .16s ease;
}
.app-task-overlay[hidden]{ display: none !important; }
.app-task-overlay.is-visible{ opacity: 1; pointer-events: auto; }
.app-task-card{
  width: min(100%,360px);
  display: grid;
  gap: 11px;
  padding: 15px;
  border: 1px solid color-mix(in srgb,var(--primary) 36%,rgba(255,255,255,.16));
  border-radius: 18px;
  color: #f8fbf9;
  background: linear-gradient(145deg,rgba(15,25,21,.985),rgba(9,16,19,.985));
  box-shadow: 0 20px 54px rgba(0,0,0,.38);
}
.app-task-card > header{
  min-width: 0;
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
}
.app-task-card > header > div{ min-width: 0; display: grid; gap: 2px; }
.app-task-card > header strong{ color: #fff; font-size: .8rem; line-height: 1.2; overflow-wrap: anywhere; }
.app-task-card > header small{ color: rgba(255,255,255,.72); font-size: .62rem; line-height: 1.35; overflow-wrap: anywhere; }
.app-task-card > header b{ color: var(--primary); font-size: .65rem; font-variant-numeric: tabular-nums; white-space: nowrap; }
.app-task-spinner{
  width: 28px;
  height: 28px;
  border: 3px solid rgba(255,255,255,.14);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: app-task-spin .78s linear infinite;
}
@keyframes app-task-spin { to { transform: rotate(360deg); } }
.app-task-progress{
  position: relative;
  display: block;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.1);
}
.app-task-progress > span{
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg,var(--primary),color-mix(in srgb,var(--primary) 58%,#fff));
  transition: width .2s ease,transform .2s ease;
}
.app-task-overlay.is-indeterminate .app-task-progress > span{
  width: 34% !important;
  animation: app-task-progress 1.15s ease-in-out infinite alternate;
}
@keyframes app-task-progress { from { transform: translateX(-18%); } to { transform: translateX(210%); } }

/* V353 · movimento útil em dados que mudam sem recarregar a tela. */
.live-table-row.is-dynamic-updated, .live-knockout-row.is-dynamic-updated, .presence-team.is-dynamic-updated{
  animation: dynamic-row-update .72s ease-out;
}
.live-table-row.is-dynamic-enter, .live-knockout-row.is-dynamic-enter, .presence-team.is-dynamic-enter{
  animation: dynamic-row-enter .38s cubic-bezier(.2,.82,.22,1);
}
.dynamic-surface-item.is-dynamic-updated{
  animation: dynamic-surface-update .68s ease-out;
}
.dynamic-surface-item.is-dynamic-enter{
  animation: dynamic-row-enter .34s cubic-bezier(.2,.82,.22,1);
}
.is-dynamic-value-up, .is-dynamic-value-down, .is-dynamic-value-neutral{
  transform-origin: center;
  animation: dynamic-value-change .42s cubic-bezier(.2,.82,.22,1);
}
.is-dynamic-value-up{ color: var(--success) !important; }
.is-dynamic-value-down{ color: var(--danger) !important; }
.football-stat-row i b{ transition: width .38s cubic-bezier(.2,.82,.22,1); }

@keyframes dynamic-row-update {
  0% { box-shadow: inset 0 0 0 999px color-mix(in srgb,var(--primary) 16%,transparent), 0 0 0 1px color-mix(in srgb,var(--primary) 28%,transparent); }
  100% { box-shadow: inset 0 0 0 999px transparent, 0 0 0 1px transparent; }
}
@keyframes dynamic-row-enter {
  from { opacity: .25; transform: scale(.985); }
  to { opacity: 1; transform: none; }
}
@keyframes dynamic-surface-update {
  0% { box-shadow: 0 0 0 2px color-mix(in srgb,var(--primary) 34%,transparent), inset 0 0 0 999px color-mix(in srgb,var(--primary) 8%,transparent); }
  100% { box-shadow: 0 0 0 0 transparent, inset 0 0 0 999px transparent; }
}
@keyframes dynamic-value-change {
  0% { transform: scale(.88); opacity: .52; }
  58% { transform: scale(1.12); opacity: 1; }
  100% { transform: none; opacity: 1; }
}

.reduced-motion :is(.is-dynamic-updated,.is-dynamic-enter,.is-dynamic-value-up,.is-dynamic-value-down,.is-dynamic-value-neutral){
  animation: none !important;
  transition: none !important;
}
.reduced-motion .football-stat-row i b{ transition: none !important; }
@media (prefers-reduced-motion: reduce) {
  :is(.is-dynamic-updated,.is-dynamic-enter,.is-dynamic-value-up,.is-dynamic-value-down,.is-dynamic-value-neutral){
    animation: none !important;
    transition: none !important;
  }
  .football-stat-row i b{ transition: none !important; }
}
.app-task-tip{
  min-width: 0;
  display: grid;
  grid-template-columns: 28px minmax(0,1fr);
  align-items: start;
  gap: 8px;
  padding: 9px 10px;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 13px;
  background: rgba(255,255,255,.045);
}
.app-task-tip > span{
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #ffd66b;
  background: rgba(255,214,107,.12);
}
.app-task-tip > div{ min-width: 0; display: grid; gap: 2px; }
.app-task-tip strong{ color: #fff; font-size: .66rem; }
.app-task-tip small{ color: rgba(255,255,255,.68); font-size: .58rem; line-height: 1.35; overflow-wrap: anywhere; }
.reduced-motion .app-task-spinner, .reduced-motion .app-task-overlay.is-indeterminate .app-task-progress > span{ animation: none !important; }
html[data-theme="light"] .app-task-overlay{ background: color-mix(in srgb,#eaf2ed 70%,transparent); }
html[data-theme="light"] .app-task-card{
  color: #17221c;
  border-color: color-mix(in srgb,var(--primary) 40%,#9aa9a0);
  background: linear-gradient(145deg,rgba(252,255,253,.99),rgba(238,245,241,.99));
  box-shadow: 0 20px 54px rgba(17,31,23,.2);
}
html[data-theme="light"] .app-task-card > header strong, html[data-theme="light"] .app-task-tip strong{ color: #17221c; }
html[data-theme="light"] .app-task-card > header small, html[data-theme="light"] .app-task-tip small{ color: #506159; }
html[data-theme="light"] .app-task-progress{ background: rgba(23,34,28,.12); }
html[data-theme="light"] .app-task-tip{ border-color: rgba(23,34,28,.1); background: rgba(23,34,28,.035); }

/* V335 · histórico do técnico continua acessível sem depender do ex-clube. */
.manager-history-hero{
  display:flex;
  align-items:flex-start;
  gap:14px;
}
.manager-history-hero>span{
  flex:0 0 44px;
  width:44px;
  height:44px;
  display:grid;
  place-items:center;
  border-radius:14px;
  background:var(--soft-surface,rgba(255,255,255,.06));
  font-size:1.1rem;
}
.manager-history-hero h2{margin:.18rem 0 .35rem}
.manager-history-hero p{margin:0;color:var(--muted)}

/* =========================================================
   V336 · placar interativo, busca visual e loader inteligente
   ========================================================= */
.pitch-score .live-score-menu-trigger{
  appearance: none;
  padding: 2px 0;
  border: 0;
  border-radius: 10px;
  color: inherit;
  background: transparent;
  cursor: pointer;
  font: inherit;
  -webkit-tap-highlight-color: transparent;
}
.pitch-score .live-score-menu-trigger > small{
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: rgba(255,255,255,.62);
  font-size: .34rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: .025em;
  text-transform: uppercase;
  white-space: nowrap;
  display: none;
}
.pitch-score .live-score-menu-trigger:focus-visible{
  outline: 2px solid rgba(255,255,255,.9);
  outline-offset: 2px;
}
.pitch-score .live-score-menu-trigger:active{ transform: scale(.97); }
.live-score-quick-menu{ display: grid; gap: 12px; }
.live-score-quick-status{
  display: grid;
  grid-template-columns: 38px minmax(0,1fr);
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid color-mix(in srgb,var(--primary) 28%,var(--line));
  border-radius: 15px;
  background: color-mix(in srgb,var(--primary) 9%,var(--panel-2));
}
.live-score-quick-status > span{
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 14%,var(--panel));
}
.live-score-quick-status > div{ min-width: 0; display: grid; gap: 2px; }
.live-score-quick-status small{ color: var(--primary); font-size: .52rem; font-weight: 600; letter-spacing: .08em; }
.live-score-quick-status strong{ overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .86rem; }
.live-score-quick-status em{ color: var(--muted); font-size: .59rem; font-style: normal; line-height: 1.3; }
.live-score-menu-section{ display: grid; gap: 8px; }
.live-score-menu-title{ display: grid; grid-template-columns: 30px minmax(0,1fr); align-items: center; gap: 8px; }
.live-score-menu-title > span{ width: 30px; height: 30px; display: grid; place-items: center; border-radius: 10px; color: var(--primary); background: var(--panel-2); }
.live-score-menu-title > div{ min-width: 0; display: grid; gap: 1px; }
.live-score-menu-title strong{ font-size: .72rem; }
.live-score-menu-title small{ color: var(--muted); font-size: .57rem; }
.live-score-speed-grid{ display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 5px; }
.live-score-speed{
  min-width: 0;
  min-height: 48px;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 2px;
  padding: 6px 3px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: inherit;
  background: var(--panel-2);
}
.live-score-speed span{ max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .51rem; }
.live-score-speed b{ color: var(--muted); font-size: .57rem; }
.live-score-speed.is-active{ border-color: var(--primary); color: var(--primary); background: color-mix(in srgb,var(--primary) 12%,var(--panel-2)); box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--primary) 25%,transparent); }
.live-score-speed.is-active b{ color: var(--primary); }
.live-score-toggle-grid{ display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: 7px; }
.live-score-toggle-grid > button{
  min-width: 0;
  display: grid;
  grid-template-columns: 28px minmax(0,1fr);
  align-items: center;
  gap: 7px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: inherit;
  background: var(--panel-2);
  text-align: left;
}
.live-score-toggle-grid > button > svg, .live-score-toggle-grid > button > i{ color: var(--primary); }
.live-score-toggle-grid > button > span{ min-width: 0; display: grid; gap: 1px; }
.live-score-toggle-grid strong{ font-size: .63rem; }
.live-score-toggle-grid small{ color: var(--muted); font-size: .52rem; line-height: 1.25; }
.live-score-toggle-grid > button.is-active{ border-color: color-mix(in srgb,var(--primary) 70%,var(--line)); background: color-mix(in srgb,var(--primary) 10%,var(--panel-2)); }
.live-score-tab-grid{ display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 6px; }
.live-score-tab-grid > button{ min-width: 0; display: grid; place-items: center; gap: 4px; min-height: 48px; padding: 6px 3px; border: 1px solid var(--line); border-radius: 11px; color: inherit; background: var(--panel-2); }
.live-score-tab-grid > button > svg, .live-score-tab-grid > button > i{ color: var(--primary); }
.live-score-tab-grid > button span{ max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .54rem; }
.universal-result-icon.has-crest{ overflow: hidden; contain:paint; min-width:0; min-height:0; padding: 2px; background: color-mix(in srgb,var(--panel-2) 82%,transparent); }
.universal-result-crest{ width: 100%; height: 100%; display: block; object-fit: contain; border-radius: 9px; }
/* V337 · identidade viva do jogador. O painel nasce para a menor tela e não
   depende de breakpoint por largura. */
.player-identity-status{ gap:5px; }
.player-identity-status.is-danger{ border-color:color-mix(in srgb,var(--danger) 42%,var(--line)); color:var(--danger); }
.player-identity-status.is-warning{ border-color:color-mix(in srgb,var(--warning) 42%,var(--line)); }
.player-identity-status.is-success{ border-color:color-mix(in srgb,var(--success) 42%,var(--line)); color:var(--success); }
.player-identity-grid{ display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; margin:12px 0 14px; }
.player-identity-grid article{ min-width:0; padding:11px; border:1px solid var(--line); border-radius:14px; background:var(--panel); }
.player-identity-grid span, .player-identity-grid small{ display:block; color:var(--muted); font-size:.76rem; line-height:1.35; }
.player-identity-grid strong{ display:block; margin:4px 0 3px; font-size:1.08rem; }
.player-memory-log{ margin-top:14px; border-top:1px solid var(--line); padding-top:12px; }
.player-memory-log > summary{ cursor:pointer; font-weight:600; }
.player-memory-log > div{ display:grid; gap:8px; margin-top:10px; }
.player-memory-log article{ padding:10px 11px; border-radius:13px; background:var(--chip); }
.player-memory-log article span{ display:block; color:var(--muted); font-size:.72rem; }
.player-memory-log article strong{ display:block; margin:2px 0; font-size:.9rem; }
.player-memory-log article p{ margin:0; color:var(--muted); font-size:.8rem; line-height:1.4; }
.renewal-human-context{ display:grid; gap:6px; margin:-2px 0 2px; }
.renewal-human-context span{ display:flex; align-items:flex-start; gap:7px; padding:8px 9px; border:1px solid color-mix(in srgb,var(--primary) 22%,var(--line)); border-radius:10px; background:color-mix(in srgb,var(--primary) 6%,var(--panel)); color:var(--muted); font-size:.66rem; line-height:1.4; }
.renewal-human-context .fa-solid{ flex:0 0 auto; margin-top:2px; color:var(--primary); }

/* V338 · conversas rápidas iniciadas pelos jogadores. O componente nasce em uma
   coluna para o layout mobile; não depende de breakpoint por largura. */
.locker-player-requests{ border-color:color-mix(in srgb,#f3ad3d 34%,var(--line)); }
.player-request-list{ display:grid; gap:8px; }
.player-request-row{ width:100%; display:grid; grid-template-columns:auto minmax(0,1fr) auto auto; align-items:center; gap:10px; padding:12px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); color:var(--text); text-align:left; }
.player-request-row > span:first-child{ width:40px; height:40px; display:grid; place-items:center; border-radius:12px; background:color-mix(in srgb,#f3ad3d 14%,var(--panel)); color:#c77a00; }
.player-request-row small, .player-request-row strong, .player-request-row em{ display:block; min-width:0; }
.player-request-row small{ color:var(--muted); font-size:.74rem; }
.player-request-row strong{ margin:2px 0; }
.player-request-row em{ color:var(--muted); font-size:.8rem; font-style:normal; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.player-request-row > b{ font-size:.72rem; color:var(--muted); white-space:nowrap; }
.player-request-profile-card{ display:grid; grid-template-columns:auto minmax(0,1fr); gap:11px; align-items:start; padding:14px; border:1px solid color-mix(in srgb,#f3ad3d 34%,var(--line)); border-radius:16px; background:color-mix(in srgb,#f3ad3d 7%,var(--panel-2)); }
.player-request-profile-card > span{ width:42px; height:42px; display:grid; place-items:center; border-radius:13px; background:color-mix(in srgb,#f3ad3d 16%,var(--panel)); color:#c77a00; }
.player-request-profile-card small, .player-request-profile-card strong{ display:block; }
.player-request-profile-card small{ color:var(--muted); }
.player-request-profile-card p{ margin:5px 0 0; color:var(--muted); line-height:1.42; }
.player-request-profile-card .btn{ grid-column:1 / -1; justify-content:center; }
.quick-player-conversation{ display:grid; gap:14px; }
.quick-player-conversation > header{ display:grid; grid-template-columns:auto minmax(0,1fr); gap:12px; align-items:start; }
.quick-player-conversation-icon{ width:46px; height:46px; display:grid; place-items:center; border-radius:14px; background:color-mix(in srgb,var(--primary) 14%,var(--panel)); color:var(--primary); }
.quick-player-conversation header small{ display:block; color:var(--muted); }
.quick-player-conversation header h3{ margin:3px 0 5px; font-size:1.08rem; }
.quick-player-conversation header p{ margin:0; color:var(--muted); line-height:1.45; }
.quick-player-conversation-state{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:7px; }
.quick-player-conversation-state span{ display:grid; gap:2px; min-width:0; padding:9px; border-radius:12px; background:var(--chip); color:var(--muted); font-size:.72rem; text-align:center; }
.quick-player-conversation-state strong{ color:var(--text); font-size:.94rem; }
.quick-player-conversation-choices{ display:grid; gap:8px; }
.player-conversation-choice{ width:100%; display:grid; grid-template-columns:auto minmax(0,1fr) auto; gap:11px; align-items:center; padding:12px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); color:var(--text); text-align:left; }
.player-conversation-choice > span{ width:38px; height:38px; display:grid; place-items:center; border-radius:11px; background:var(--chip); color:var(--primary); }
.player-conversation-choice strong, .player-conversation-choice small{ display:block; }
.player-conversation-choice small{ margin-top:3px; color:var(--muted); line-height:1.34; }
.player-conversation-choice.is-primary{ border-color:color-mix(in srgb,var(--primary) 45%,var(--line)); background:color-mix(in srgb,var(--primary) 8%,var(--panel)); }
.player-conversation-choice:disabled{ opacity:.58; }
.quick-player-conversation footer{ display:flex; gap:8px; align-items:flex-start; padding-top:2px; color:var(--muted); font-size:.78rem; line-height:1.4; }

/* V338 · o menu do placar espelha Configurações → Partidas sem criar uma
   segunda fonte de preferências. A seção completa fica recolhida por padrão
   para manter velocidade/som/atalhos acessíveis em um toque. */
.live-score-settings-details{
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel);
}
.live-score-settings-details > summary{
  min-height: 52px;
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) 18px;
  align-items: center;
  gap: 8px;
  padding: 10px;
  cursor: pointer;
  list-style: none;
  -webkit-tap-highlight-color: transparent;
}
.live-score-settings-details > summary::-webkit-details-marker{ display: none; }
.live-score-settings-details > summary > span{
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: var(--primary);
  background: var(--panel-2);
}
.live-score-settings-details > summary > div{ min-width: 0; display: grid; gap: 1px; }
.live-score-settings-details > summary strong{ font-size: .7rem; }
.live-score-settings-details > summary small{ color: var(--muted); font-size: .55rem; line-height: 1.25; }
.live-score-settings-details > summary > svg:last-child, .live-score-settings-details > summary > i:last-child{ color: var(--muted); transition: transform .18s ease; }
.live-score-settings-details[open] > summary > svg:last-child, .live-score-settings-details[open] > summary > i:last-child{ transform: rotate(180deg); }
.live-score-settings-body{ display: grid; gap: 14px; padding: 0 10px 11px; border-top: 1px solid var(--line); }
.live-score-settings-body > .live-score-menu-section{ padding-top: 11px; }
.live-score-settings-grid{ display: grid; gap: 8px; }
.live-score-setting-field{ display: grid; gap: 5px; padding: 9px; border: 1px solid var(--line); border-radius: 12px; background: var(--panel-2); }
.live-score-setting-field > span{ font-size: .62rem; font-weight: 600; }
.live-score-setting-field select{ width: 100%; min-width: 0; }
.live-score-setting-field > small{ color: var(--muted); font-size: .52rem; line-height: 1.3; }
.live-score-settings-toggle-list{ display: grid; gap: 6px; }
.live-score-setting-toggle{
  min-width: 0;
  min-height: 48px;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel-2);
}
.live-score-setting-toggle > span{ min-width: 0; display: grid; gap: 2px; }
.live-score-setting-toggle strong{ font-size: .62rem; }
.live-score-setting-toggle small{ color: var(--muted); font-size: .52rem; line-height: 1.28; }
.live-score-setting-toggle em{ width: max-content; padding: 2px 6px; border-radius: 999px; color: var(--primary); background: color-mix(in srgb,var(--primary) 11%,var(--panel)); font-size: .46rem; font-style: normal; font-weight: 600; }
.live-score-setting-toggle input{ margin: 0; }
.live-score-settings-note{ margin: 0; display: grid; grid-template-columns: 16px minmax(0,1fr); gap: 6px; align-items: start; color: var(--muted); font-size: .53rem; line-height: 1.35; }
.live-score-settings-note b{ color: var(--text); font-weight: 600; }

/* V339 · Diretoria, Torcida e Elenco reagem separadamente à carreira. */
.stakeholder-hub{ display:grid; gap:12px; margin-bottom:12px; }
.stakeholder-hub.is-danger{ border-color:color-mix(in srgb,var(--danger) 52%,var(--line)); }
.stakeholder-hub-head{ display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
.stakeholder-hub-head h3{ margin-top:3px; }
.stakeholder-hub-head p{ margin-top:4px; color:var(--muted); font-size:.7rem; line-height:1.45; }
.stakeholder-hub-head > strong{ flex:0 0 auto; display:grid; place-items:center; min-width:50px; min-height:44px; padding:7px; border-radius:13px; border:1px solid var(--line); background:var(--panel-2); font-size:1rem; }
.stakeholder-grid{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:7px; }
.stakeholder-grid article{ min-width:0; display:grid; grid-template-columns:auto minmax(0,1fr); gap:8px; align-items:start; padding:10px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); }
.stakeholder-icon{ display:grid; place-items:center; width:30px; height:30px; border-radius:9px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.stakeholder-grid small, .stakeholder-grid strong, .stakeholder-grid b{ display:block; min-width:0; }
.stakeholder-grid small{ color:var(--muted); font-size:.54rem; text-transform:uppercase; letter-spacing:.04em; }
.stakeholder-grid strong{ margin-top:2px; font-size:.67rem; line-height:1.25; }
.stakeholder-grid b{ margin:4px 0 5px; font-size:.86rem; }
.stakeholder-grid .progress-track{ height:5px; }
.stakeholder-context{ display:grid; gap:6px; }
.stakeholder-context span{ display:flex; align-items:flex-start; gap:7px; color:var(--muted); font-size:.63rem; line-height:1.4; }
.stakeholder-context i{ color:var(--primary); margin-top:2px; }
.stakeholder-reaction-history{ border-top:1px solid var(--line); padding-top:9px; }
.stakeholder-reaction-history summary{ display:flex; align-items:center; gap:7px; color:var(--text); font-size:.68rem; cursor:pointer; }
.stakeholder-reaction-history > div{ display:grid; gap:7px; margin-top:9px; }
.stakeholder-reaction-history article{ display:grid; grid-template-columns:auto minmax(0,1fr); gap:8px; padding:9px; border-radius:12px; background:var(--panel-2); border:1px solid var(--line); }
.stakeholder-reaction-icon{ display:grid; place-items:center; width:30px; height:30px; border-radius:9px; background:var(--panel); color:var(--primary); }
.stakeholder-reaction-history strong{ display:block; font-size:.68rem; }
.stakeholder-reaction-history small{ display:block; margin-top:2px; color:var(--muted); font-size:.58rem; line-height:1.4; }
.stakeholder-reaction-history p{ display:flex; flex-wrap:wrap; gap:5px; margin-top:6px; }
.stakeholder-reaction-history p b{ padding:4px 6px; border-radius:7px; font-size:.54rem; font-weight:600; background:var(--panel); }
.stakeholder-reaction-history .is-positive{ color:var(--success); }
.stakeholder-reaction-history .is-negative{ color:var(--danger); }
.stakeholder-reaction-history .is-neutral{ color:var(--muted); }
.supporter-base-card > .panel-heading-row > strong{ font-size:.78rem; }
.progress-track.squad span, .progress-track.squad i{ background:color-mix(in srgb,var(--success) 74%,var(--primary)); }

/* V340 · metas personalizadas da temporada e objetivos pessoais do técnico. */
.season-objective-list{ display:grid; gap:9px; }
.season-objective-row{ min-width:0; display:grid; grid-template-columns:38px minmax(0,1fr) auto; gap:10px; align-items:start; padding:11px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); }
.season-objective-row.is-complete{ border-color:color-mix(in srgb,var(--success) 45%,var(--line)); background:color-mix(in srgb,var(--success) 7%,var(--panel-2)); }
.season-objective-row.is-risk{ border-color:color-mix(in srgb,var(--danger) 45%,var(--line)); background:color-mix(in srgb,var(--danger) 6%,var(--panel-2)); }
.season-objective-icon{ width:38px; height:38px; display:grid; place-items:center; border-radius:12px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.season-objective-row.is-complete .season-objective-icon{ color:var(--success); background:color-mix(in srgb,var(--success) 13%,var(--panel)); }
.season-objective-row.is-risk .season-objective-icon{ color:var(--danger); background:color-mix(in srgb,var(--danger) 12%,var(--panel)); }
.season-objective-row > div{ min-width:0; display:grid; gap:7px; }
.season-objective-row header{ display:flex; align-items:flex-start; justify-content:space-between; gap:8px; }
.season-objective-row header strong{ min-width:0; font-size:.72rem; line-height:1.3; }
.season-objective-row header em{ flex:0 0 auto; padding:3px 6px; border-radius:999px; color:var(--muted); background:var(--panel); font-size:.49rem; font-style:normal; font-weight:600; text-transform:uppercase; letter-spacing:.03em; }
.season-objective-row > div > small{ color:var(--muted); font-size:.59rem; line-height:1.4; }
.season-objective-row > b{ align-self:center; color:var(--muted); font-size:.57rem; white-space:nowrap; }
.season-objective-row.is-complete > b{ color:var(--success); }
.season-objective-row.is-risk > b{ color:var(--danger); }
.season-objective-row .progress-track{ height:6px; }
.season-objective-summary{ margin:10px 0 0; padding:8px 9px; border-radius:11px; background:var(--chip); color:var(--muted); font-size:.57rem; line-height:1.4; }
.season-objective-history{ margin-top:10px; border-top:1px solid var(--line); padding-top:9px; }
.season-objective-history > summary{ cursor:pointer; color:var(--text); font-size:.64rem; font-weight:600; }
.season-objective-history > div{ display:grid; gap:6px; margin-top:8px; }
.season-objective-history article{ display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:3px 8px; padding:8px 9px; border-radius:10px; background:var(--panel-2); }
.season-objective-history article span{ min-width:0; color:var(--muted); font-size:.56rem; }
.season-objective-history article strong{ font-size:.63rem; }
.season-objective-history article small{ grid-column:1 / -1; color:var(--muted); font-size:.51rem; line-height:1.35; }
.manager-passport-goal-stamps{ display:grid; gap:8px; margin-top:12px; padding-top:11px; border-top:1px solid var(--line); }
.manager-passport-goal-stamps > div{ display:grid; gap:7px; }
.manager-passport-goal-stamps article{ min-width:0; display:grid; grid-template-columns:34px minmax(0,1fr); gap:9px; align-items:center; padding:9px; border:1px solid color-mix(in srgb,var(--primary) 25%,var(--line)); border-radius:12px; background:color-mix(in srgb,var(--primary) 6%,var(--panel-2)); }
.manager-passport-goal-stamps article > span{ width:34px; height:34px; display:grid; place-items:center; border-radius:10px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.manager-passport-goal-stamps article strong{ display:block; font-size:.66rem; }
.manager-passport-goal-stamps article small{ display:block; margin-top:2px; color:var(--muted); font-size:.55rem; line-height:1.3; }

/* V341 · Dia da Base, gerações e revelações preservadas na carreira. */
.academy-generation-spotlight{ display:grid; gap:12px; overflow:hidden; position:relative; border-color:color-mix(in srgb,var(--primary) 35%,var(--line)); background:linear-gradient(145deg,color-mix(in srgb,var(--primary) 8%,var(--panel)),var(--panel)); }
.academy-generation-spotlight.is-new::after{ content:""; position:absolute; inset:0 0 auto; height:3px; background:linear-gradient(90deg,var(--primary),color-mix(in srgb,var(--primary) 25%,transparent)); }
.academy-generation-head{ min-width:0; display:grid; grid-template-columns:42px minmax(0,1fr); gap:10px; align-items:start; }
.academy-generation-head > .badge{ grid-column:1 / -1; justify-self:start; }
.academy-generation-head h3{ margin:2px 0 4px; font-size:.86rem; }
.academy-generation-head p{ margin:0; color:var(--muted); font-size:.62rem; line-height:1.45; }
.academy-generation-icon{ width:42px; height:42px; display:grid; place-items:center; border-radius:13px; color:var(--primary); background:color-mix(in srgb,var(--primary) 14%,var(--panel)); box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--primary) 18%,var(--line)); }
.academy-generation-featured{ display:grid; gap:8px; }
.academy-generation-featured article{ min-width:0; display:grid; grid-template-columns:36px minmax(0,1fr); gap:9px; align-items:center; padding:10px; border:1px solid color-mix(in srgb,var(--primary) 21%,var(--line)); border-radius:13px; background:var(--panel-2); }
.academy-generation-featured article > span{ width:36px; height:36px; display:grid; place-items:center; border-radius:11px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.academy-generation-featured small, .academy-generation-featured strong, .academy-generation-featured em{ display:block; min-width:0; }
.academy-generation-featured small{ color:var(--primary); font-size:.51rem; font-weight:700; text-transform:uppercase; letter-spacing:.04em; }
.academy-generation-featured strong{ margin-top:2px; font-size:.7rem; }
.academy-generation-featured em{ margin-top:2px; color:var(--muted); font-size:.54rem; font-style:normal; }
.academy-generation-badge{ color:var(--primary); border-color:color-mix(in srgb,var(--primary) 28%,var(--line)); background:color-mix(in srgb,var(--primary) 10%,var(--panel)); }
.manager-passport-revelations{ display:grid; gap:8px; margin-top:12px; padding-top:11px; border-top:1px solid var(--line); }
.manager-passport-revelations > div, .academy-graduates-list{ display:grid; gap:7px; }
.manager-passport-revelations article, .academy-graduates-list article{ min-width:0; display:grid; grid-template-columns:34px minmax(0,1fr); gap:9px; align-items:center; padding:9px; border:1px solid color-mix(in srgb,var(--primary) 24%,var(--line)); border-radius:12px; background:color-mix(in srgb,var(--primary) 5%,var(--panel-2)); }
.manager-passport-revelations article > span, .academy-graduates-list article > span{ width:34px; height:34px; display:grid; place-items:center; border-radius:10px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.manager-passport-revelations strong, .academy-graduates-list strong{ display:block; font-size:.66rem; }
.manager-passport-revelations small, .manager-passport-revelations em, .academy-graduates-list small, .academy-graduates-list p{ display:block; margin-top:2px; color:var(--muted); font-size:.54rem; line-height:1.35; font-style:normal; }
.academy-graduates-museum{ display:grid; gap:12px; }

/* V342 · Momentos decisivos com consequência real durante partidas importantes. */
.live-decision-callout{
  display:grid;
  grid-template-columns:38px minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
  margin:8px 10px 10px;
  padding:10px;
  border:1px solid color-mix(in srgb,#f2b84b 52%,var(--line));
  border-radius:14px;
  background:linear-gradient(110deg,color-mix(in srgb,#f2b84b 14%,var(--panel)),color-mix(in srgb,var(--primary) 6%,var(--panel)));
  box-shadow:0 10px 24px color-mix(in srgb,#000 15%,transparent);
}
.live-decision-callout[hidden]{ display:none !important; }
.live-decision-callout-icon{ width:38px; height:38px; display:grid; place-items:center; border-radius:12px; color:#201604; background:#f2b84b; }
.live-decision-callout > div{ min-width:0; }
.live-decision-callout small, .live-decision-callout strong, .live-decision-callout span{ display:block; }
.live-decision-callout small{ color:#f2b84b; font-size:.5rem; font-weight:600; letter-spacing:.08em; text-transform:uppercase; }
.live-decision-callout strong{ margin-top:2px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:.69rem; }
.live-decision-callout > div > span{ margin-top:2px; color:var(--muted); font-size:.54rem; }
.live-decision-callout .btn{ min-height:36px; white-space:nowrap; }

.manager-decision-panel{ display:grid; gap:13px; }
.manager-decision-panel > header{ padding:2px 2px 10px; border-bottom:1px solid var(--line); }
.manager-decision-panel > header h3{ margin:5px 0 4px; font-size:1rem; line-height:1.2; }
.manager-decision-panel > header p{ margin:0; color:var(--text); font-size:.66rem; }
.manager-decision-panel > header p strong{ color:#f2b84b; }
.manager-decision-panel > header > small{ display:block; margin-top:5px; color:var(--muted); font-size:.53rem; text-transform:capitalize; }
.manager-decision-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr)); gap:8px; }
.manager-decision-choice{ min-width:0; min-height:112px; display:grid; grid-template-columns:34px minmax(0,1fr) auto; align-items:start; gap:9px; padding:11px; border:1px solid var(--line); border-radius:14px; color:var(--text); background:var(--panel-2); text-align:left; cursor:pointer; }
.manager-decision-choice > span{ width:34px; height:34px; display:grid; place-items:center; border-radius:10px; color:var(--primary); background:color-mix(in srgb,var(--primary) 12%,var(--panel)); }
.manager-decision-choice > div{ min-width:0; }
.manager-decision-choice strong{ display:block; font-size:.69rem; }
.manager-decision-choice p{ margin:4px 0 0; color:var(--text); font-size:.58rem; line-height:1.35; }
.manager-decision-choice small{ display:block; margin-top:6px; color:var(--muted); font-size:.52rem; line-height:1.35; }
.manager-decision-choice > :last-child{ align-self:center; color:var(--muted); }
.manager-decision-choice.is-attack{ border-color:color-mix(in srgb,#e75c55 34%,var(--line)); }
.manager-decision-choice.is-defend{ border-color:color-mix(in srgb,#4c91dd 38%,var(--line)); }
.manager-decision-choice:is(:hover,:focus-visible){ border-color:color-mix(in srgb,var(--primary) 62%,var(--line)); background:color-mix(in srgb,var(--primary) 8%,var(--panel-2)); outline:none; transform:translateY(-1px); }
.manager-decision-panel > footer{ display:flex; align-items:flex-start; gap:7px; color:var(--muted); font-size:.54rem; line-height:1.4; }
.manager-decision-panel > footer > :first-child{ flex:0 0 auto; margin-top:1px; color:var(--primary); }

.post-manager-decision{ display:grid; gap:9px; }
.post-manager-decision > header{ display:grid; grid-template-columns:34px minmax(0,1fr) auto; align-items:center; gap:9px; }
.post-manager-decision > header > span{ width:34px; height:34px; display:grid; place-items:center; border-radius:10px; color:var(--primary); background:color-mix(in srgb,var(--primary) 11%,var(--panel-2)); }
.post-manager-decision > header > div{ min-width:0; }
.post-manager-decision > header small{ display:block; color:var(--muted); font-size:.51rem; }
.post-manager-decision > header strong{ display:block; margin-top:2px; font-size:.63rem; line-height:1.35; }
.post-manager-decision > header > b{ font-size:.75rem; white-space:nowrap; }
.post-manager-decision > p{ margin:0; padding:9px; border-left:3px solid var(--primary); border-radius:0 9px 9px 0; background:var(--panel-2); font-size:.58rem; line-height:1.45; }
.post-manager-decision > footer{ display:flex; justify-content:space-between; flex-wrap:wrap; gap:6px; color:var(--muted); font-size:.51rem; }
.post-manager-decision > footer span{ display:inline-flex; align-items:center; gap:5px; }
.manager-decision-post-card .badge.is-worked{ color:#54d58a; }
.manager-decision-post-card .badge.is-backfired{ color:#ff7a7a; }
.manager-decision-post-card .badge.is-neutral{ color:var(--muted); }

html[data-theme="light"] .live-decision-callout{ background:linear-gradient(110deg,#fff7e5,#f5fbf8); }
html[data-theme="light"] .manager-decision-choice{ background:#f7f9fb; }

/* V345–V347 · Central de Retorno e notificações locais narrativas. */
.return-center-home-card{
  display:grid;
  grid-template-columns:42px minmax(0,1fr);
  align-items:center;
  gap:12px;
  border-color:color-mix(in srgb,#d6ad55 38%,var(--line));
  background:linear-gradient(135deg,color-mix(in srgb,#d6ad55 9%,var(--panel)),var(--panel));
}
.return-center-home-card.is-read{ opacity:.88; }
