  padding: 6px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--scenario-accent) 10%, transparent);
  color: var(--text);
  font-size: .72rem;
  font-weight: 600;
}
.career-scenario-objective-copy{
  margin: 11px 0 0;
  line-height: 1.45;
}
.career-scenario-progress{
  display: grid;
  gap: 7px;
  margin-top: 12px;
}
.career-scenario-progress > div:first-child{
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: baseline;
}
.career-scenario-progress small{
  min-width: 0;
  color: var(--muted);
  text-align: right;
}
.career-scenario-panel .progress-track span{
  background: var(--scenario-accent);
}
.career-scenario-open{
  width: 100%;
  margin-top: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 38px;
  border: 1px solid color-mix(in srgb, var(--scenario-accent) 28%, var(--line));
  border-radius: 11px;
  background: color-mix(in srgb, var(--scenario-accent) 7%, transparent);
  color: inherit;
  font-weight: 600;
  touch-action: manipulation;
}
.career-scenario-detail-grid{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 12px;
}
.career-scenario-detail-grid article{
  min-width: 0;
  display: grid;
  gap: 2px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-soft, color-mix(in srgb, var(--card) 92%, var(--text) 8%));
}
.career-scenario-detail-grid small{ color: var(--muted); }
.career-scenario-detail-grid strong{
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.career-scenario-result{
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin: 12px 0 0;
  padding: 10px;
  border-radius: 11px;
  font-weight: 600;
}
.career-scenario-result.is-complete{ background: color-mix(in srgb, #c9931d 12%, transparent); }
.career-scenario-result.is-failed{ background: color-mix(in srgb, #a64a4a 12%, transparent); }
.career-scenario-panel.is-compact{
  padding-block: 13px;
}
.career-scenario-panel.is-compact .career-scenario-objective-copy{
  font-size: .86rem;
  color: var(--muted);
}

/* ==========================================================
   V361 · Ritmo visual e conteúdo crítico em telas estreitas
   ==========================================================
   Mantém os cabeçalhos de seção com a mesma lógica responsiva dos painéis
   principais. A intenção é padronizar alinhamento/fluxo, não apagar a
   identidade visual específica de Mercado, Médico ou Configurações. */
:is(.settings-section-heading,.medical-section-heading,.market-section-heading){
  min-width: 0;
  align-items: flex-start;
  flex-wrap: wrap;
  column-gap: 12px;
  row-gap: 7px;
}
:is(.settings-section-heading,.medical-section-heading,.market-section-heading) > :first-child{
  flex: 1 1 180px;
  min-width: 0;
}
:is(.settings-section-heading,.medical-section-heading,.market-section-heading) > :last-child:not(:first-child){
  flex: 0 1 auto;
  max-width: 100%;
  margin-inline-start: auto;
}
:is(.settings-section-heading,.medical-section-heading,.market-section-heading) :is(h2,h3,strong,p,span){
  overflow-wrap: anywhere;
}

/* Cenários carregam prazo/progresso importantes. Reticências escondiam parte
   desses valores em 320–390 px; aqui o texto passa a crescer verticalmente. */
.career-scenario-detail-grid strong{
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.28;
}

/* ===== V364 · pré-jogo progressivo e pós-jogo não bloqueante ===== */
.live-preparation-screen{
  display: grid;
  align-content: start;
  gap: 14px;
  min-height: 100%;
  padding: 16px 12px max(18px,env(safe-area-inset-bottom));
  background: var(--panel);
}
.live-preparation-head{
  display: grid;
  gap: 4px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel-2);
}
.live-preparation-head strong{ font-size: 1.05rem; }
.live-preparation-head small{ color: var(--muted); line-height: 1.35; }
.live-preparation-score{
  display: grid;
  grid-template-columns: minmax(0,1fr) auto minmax(0,1fr);
  align-items: center;
  gap: 8px;
  padding: 16px 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: color-mix(in srgb,var(--panel-2) 86%,var(--panel));
}
.live-preparation-score article{
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 6px;
  text-align: center;
}
.live-preparation-score article strong{
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: .82rem;
}
.live-preparation-score article small{
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: .64rem;
}
.live-preparation-score > div{ display: grid; justify-items: center; gap: 3px; }
.live-preparation-score > div b{ font-size: 1.35rem; font-variant-numeric: tabular-nums; }
.live-preparation-score > div span{ color: var(--muted); font-size: .74rem; }
.live-preparation-progress{
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel-2);
}
.live-preparation-progress header{
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
}
.live-preparation-progress header > div{ min-width: 0; display: grid; gap: 2px; }
.live-preparation-progress header small{ color: var(--muted); font-size: .7rem; }
.live-preparation-progress header b{ font-size: .72rem; font-variant-numeric: tabular-nums; }
.live-preparation-spinner{
  width: 26px;
  height: 26px;
  border: 3px solid color-mix(in srgb,var(--accent) 24%,transparent);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: post-match-save-spin .75s linear infinite;
}
.live-preparation-progress > i{
  display: block;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb,var(--line) 70%,transparent);
}
.live-preparation-progress > i span{
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
  transition: width .16s ease;
}
.live-preparation-progress p{ margin: 0; color: var(--muted); font-size: .7rem; line-height: 1.42; }
.reduced-motion .live-preparation-spinner{ animation: none !important; }

/* V365 · loading flutuante do pós-jogo ocupa o viewport sem dividir a tela. */
html.live-finalization-active, html.live-finalization-active body{ overflow: hidden !important; overscroll-behavior: none !important; }

/* =========================================================
   V366 · placares visíveis durante a finalização do pós-jogo
   ========================================================= */
.match-screen #liveFinishTab.is-finalizing{
  position: relative;
  color: color-mix(in srgb,var(--primary) 82%,var(--text)) !important;
  background: color-mix(in srgb,var(--primary) 10%,var(--panel-2)) !important;
  border-color: color-mix(in srgb,var(--primary) 32%,var(--line)) !important;
  opacity: 1 !important;
  filter: none !important;
}
.match-screen #liveFinishTab.is-finalizing > .fa-spinner{
  animation: live-finalization-spin .82s linear infinite !important;
}
.match-screen #liveFinishTab.is-finalizing::after{
  content: attr(data-finalizing-progress) !important;
  display: block !important;
  position: absolute;
  top: 2px;
  right: 2px;
  min-width: 20px;
  padding: 1px 3px;
  border-radius: 999px;
  background: color-mix(in srgb,var(--primary) 84%,#07110c) !important;
  color: #fff !important;
  font-size: .42rem;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}
html[data-reduced-motion="true"] .match-screen #liveFinishTab.is-finalizing > .fa-spinner{
  animation: none !important;
}

/* O loader de finalização é um cartão flutuante auxiliar, não uma cortina.
   A rodada permanece visível e rolável enquanto o motor cede o thread. */
.live-finalization-overlay.is-docked{
  inset: auto 0 max(10px,env(safe-area-inset-bottom)) 0 !important;
  display: flex !important;
  align-items: flex-end !important;
  justify-content: center !important;
  place-items: initial !important;
  padding: 10px max(10px,env(safe-area-inset-right)) 10px max(10px,env(safe-area-inset-left)) !important;
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  overscroll-behavior: auto !important;
  pointer-events: none !important;
}
.live-finalization-overlay.is-docked .live-finalization-card{
  width: min(calc(100vw - 20px),360px) !important;
  gap: 7px !important;
  padding: 10px 11px !important;
  border-radius: 14px !important;
  box-shadow: 0 10px 28px rgba(0,0,0,.3) !important;
  pointer-events: none !important;
}
.live-finalization-overlay.is-docked .live-finalization-main{
  grid-template-columns: 24px minmax(0,1fr) auto !important;
  gap: 8px !important;
}
.live-finalization-overlay.is-docked .live-finalization-spinner{
  width: 22px !important;
  height: 22px !important;
  border-width: 2px !important;
}
.live-finalization-overlay.is-docked .live-finalization-tip{
  display: none !important;
}
.live-finalization-overlay.is-docked .live-finalization-progress{
  height: 4px !important;
}

/* ========================================================================== */
/* V367 · Cenários ampliados e auditoria de leitura mobile                   */
/* ========================================================================== */
/* Textos de cenário são conteúdo, não rótulos descartáveis: em telas estreitas
   devem quebrar linha em vez de esconder regras ou objetivos com reticências. */
.setup-scenario-card em{
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
  line-height: 1.3;
}
.setup-scenario-card-meta{
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 7px;
}
.setup-scenario-card-meta > small:first-child{ flex: 1 1 auto; }
.setup-scenario-earned{
  display: inline-flex;
  align-items: center;
  gap: 4px;
  width: fit-content;
  max-width: 100%;
  padding: 2px 6px;
  border-radius: 999px;
  background: color-mix(in srgb,#2f9a5d 13%,transparent);
  color: color-mix(in srgb,#2f9a5d 76%,var(--text)) !important;
  font-size: .63rem;
  font-weight: 600;
  line-height: 1.25;
  white-space: normal;
}
.setup-scenario-card.is-achieved{
  border-color: color-mix(in srgb,#2f9a5d 28%,var(--line));
}
.setup-scenario-achievement-summary{
  display: grid;
  grid-template-columns: 30px minmax(0,1fr);
  gap: 9px;
  align-items: center;
  margin-top: 12px;
  padding: 10px;
  border: 1px solid color-mix(in srgb,#2f9a5d 28%,var(--line));
  border-radius: 12px;
  background: color-mix(in srgb,#2f9a5d 8%,var(--card));
}
.setup-scenario-achievement-summary > i{ color: #2f9a5d; justify-self: center; }
.setup-scenario-achievement-summary > span{ min-width: 0; display: grid; gap: 2px; }
.setup-scenario-achievement-summary small{ color: var(--muted); }
.setup-scenario-achievement-summary strong{ overflow-wrap: anywhere; }

/* O selo de progresso não deve espremer o nome ou sair do card. */
.career-scenario-heading{
  align-items: flex-start;
  flex-wrap: wrap;
}
.career-scenario-heading > div{ flex: 1 1 170px; }
.career-scenario-heading > div :is(strong,em){ overflow-wrap: anywhere; }
.career-scenario-status{
  flex: 0 1 auto;
  max-width: 100%;
  white-space: normal;
  text-align: center;
}
.career-scenario-progress > div:first-child{
  align-items: flex-start;
  flex-wrap: wrap;
}
.career-scenario-progress > div:first-child > strong{ flex: 0 0 auto; }
.career-scenario-progress small{
  flex: 1 1 170px;
  text-align: left;
  overflow-wrap: anywhere;
}

/* Placares compactos: o número precisa continuar visualmente separado do nome
   mesmo quando um clube longo ocupa toda a largura disponível. */
.record-match-row > div > strong, .post-round-result > strong, .international-fixture-row > strong, .live-knockout-score > strong{
  flex: 0 0 auto;
  min-width: 46px;
  padding-inline: 5px;
  text-align: center;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.record-match-row > div, .post-round-result, .international-fixture-row, .live-knockout-row{
  column-gap: max(7px, 1.8vw);
}
.record-match-row .score-team, .post-round-team, .international-fixture-row > .team-label, .live-knockout-team{
  min-width: 0;
}
.record-match-row .score-team b, .post-round-team b, .international-fixture-row > .team-label strong, .live-knockout-team :is(b,strong){
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Logs, históricos e linhas de status devem crescer verticalmente em vez de
   juntar trechos ou estourar o card quando recebem nomes maiores. */
:is(.mode-log-list,.observer-event-log,.career-story-grid,.career-opponent-list) article > :is(div,p,strong,small,span){
  min-width: 0;
}
:is(.mode-log-list,.observer-event-log,.career-story-grid,.career-opponent-list) :is(p,strong,small){
  overflow-wrap: anywhere;
}
.mode-log-list article strong, .observer-event-log article p{
  white-space: normal;
  line-height: 1.35;
}

.setup-scenario-heading{
  grid-template-columns: auto minmax(0,1fr);
}
.setup-scenario-achievement-count{
  grid-column: 2;
  width: fit-content;
  max-width: 100%;
  padding: 4px 7px;
  border-radius: 999px;
  background: color-mix(in srgb,#2f9a5d 10%,transparent);
  color: color-mix(in srgb,#2f9a5d 76%,var(--text));
  font-size: .66rem;
  font-weight: 600;
  white-space: normal;
}
.career-scenario-panel.has-target::before{ background: #2f9a5d; }
.career-scenario-panel.has-target .career-scenario-status{
  background: color-mix(in srgb,#2f9a5d 12%,transparent);
  color: color-mix(in srgb,#2f9a5d 78%,var(--text));
}


/* ==========================================================
   V368 · criação sem whitespace invisível e leitura do Ao Vivo
   ========================================================== */
/* Título e explicação são duas linhas semânticas. O flex antigo deixava
   "Times em campo" e o subtítulo aparentando ser uma única frase. */
.live-lineups-intro > div{
  display: grid !important;
  grid-template-columns: minmax(0,1fr) !important;
  justify-content: initial !important;
  align-items: start !important;
  gap: 2px !important;
  min-width: 0;
}
.live-lineups-intro > div > :is(strong,span), .live-lineups-intro > small{
  min-width: 0;
  max-width: 100%;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}
.live-lineups-intro > div > strong{ line-height: 1.25; }
.live-lineups-intro > div > span, .live-lineups-intro > small{ line-height: 1.35; }

/* A célula central reserva o placar regulamentar e a decisão por pênaltis
   em linhas próprias. Assim o texto de pênaltis nunca disputa largura com
   os nomes dos clubes. */
.match-screen .live-score-tile > strong, .observer-screen .live-score-tile > strong{
  display: grid !important;
  place-items: center;
  align-content: center;
  gap: 2px;
  overflow: visible !important;
  line-height: 1.05 !important;
}
.live-score-tile .live-regulation-score{ display: block; white-space: nowrap; font-variant-numeric: tabular-nums; }
.live-score-tile .live-penalty-score, .observer-tile [data-observer-score] > small, .international-fixture-row > strong > small, .fixture-card.modern-scoreline > .score > small, .post-match-scoreline.modern-scoreline > strong > small{
  display: block;
  max-width: 100%;
  white-space: nowrap !important;
  overflow: visible !important;
  text-overflow: clip !important;
  font-variant-numeric: tabular-nums;
}
.live-score-tile .live-penalty-score{
  color: var(--muted);
  font-size: .51rem;
  font-weight: 600;
  line-height: 1.05;
  text-transform: uppercase;
}

/* Os ícones de eventos têm significado próprio (gol, amarelo, vermelho,
   lesão e troca). Eles nunca herdam o fundo/contraste do número da camisa. */
.live-lineups-pane .live-player-event-icon, .live-lineups-pane .live-player-event-icon > :is(.fa-solid,.fa-regular,svg){
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: currentColor !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
.live-lineups-pane .live-player-event-icon{
  width: 14px !important;
  min-width: 14px !important;
  height: 16px !important;
  display: inline-grid !important;
  place-items: center;
}
.live-lineups-pane .live-player-event-icon > :is(.fa-solid,.fa-regular){ font-size: .62rem !important; }

/* Cabeçalhos equivalentes podem quebrar quando a tradução ou o conteúdo é
   maior, em vez de concatenar título e explicação visualmente. */
:is(.other-live-heading,.live-standings-head,.setup-secondary-heading,.live-score-menu-title) > div{
  min-width: 0;
}
:is(.other-live-heading,.live-standings-head,.setup-secondary-heading,.live-score-menu-title) > div > :is(strong,span,small){
  max-width: 100%;
  overflow-wrap: anywhere;
}

/* Status da fase pode ocupar duas linhas sem invadir nomes/placar. */
.match-screen .live-score-tile > em, .observer-screen .live-score-tile > em{
  max-width: 64px;
  white-space: normal !important;
  overflow-wrap: anywhere;
  line-height: 1.1;
}

/* O cabeçalho das colunas de substituição também usa relação título +
   explicação; em telas estreitas eles ficam empilhados em vez de formar
   uma frase corrida ou competir por largura. */
.substitution-column-head{
  display: grid !important;
  grid-template-columns: minmax(0,1fr) !important;
  justify-content: initial !important;
  align-items: start !important;
  gap: 2px !important;
  min-width: 0;
}
.substitution-column-head > :is(strong,span){
  min-width: 0;
  max-width: 100%;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* ==========================================================
   V369 · auditoria de hierarquia, conteúdo longo e formulários
   ========================================================== */
/* Cabeçalhos com ação/badge à direita podem cair para a linha seguinte quando
   o título cresce. O conteúdo textual nunca deve ser espremido para preservar
   uma geometria horizontal que só funciona com rótulos curtos. */
.settings-section-heading, .section-heading-row, .market-filter-heading, .market-section-heading, .share-type-heading{
  align-items: flex-start;
  flex-wrap: wrap;
  column-gap: 12px;
  row-gap: 6px;
}
.settings-section-heading > :first-child, .market-filter-heading > :first-child, .market-section-heading > :first-child{
  flex: 1 1 190px;
  min-width: 0;
}
.settings-section-heading > :last-child:not(:first-child), .market-filter-heading > :last-child:not(:first-child), .market-section-heading > :last-child:not(:first-child){
  flex: 0 1 auto;
  max-width: 100%;
}
.settings-section-heading :is(h2,h3,p,.badge), .section-heading-row :is(h2,h3,strong,span), .market-filter-heading :is(h2,h3,strong,span), .market-section-heading :is(h2,h3,strong,span), .share-type-heading :is(strong,small){
  min-width: 0;
  overflow-wrap: anywhere;
}
.settings-section-heading .badge, .section-heading-row > span, .share-type-heading small{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
}
.section-heading-row .section-title{ flex: 1 1 180px; min-width: 0; }
.section-heading-row > span{ flex: 0 1 auto; max-width: 100%; text-align: right; }
.share-type-heading strong{ flex: 1 1 120px; }
.share-type-heading small{ flex: 0 1 auto; max-width: 100% !important; }

/* No Ao Vivo, nomes de competição e subtítulos são conteúdo útil, não apenas
   decoração. Permitir duas/mais linhas evita que traduções e competições longas
   pareçam texto quebrado ou desapareçam por reticências. */
.live-competition-group > header{ align-items: flex-start; }
.live-competition-group > header > strong{
  min-width: 0;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  line-height: 1.25;
}
.live-competition-group > header > span{ flex: 0 0 auto; }
.live-standings-head div > span{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  line-height: 1.25;
}

/* Status e leituras dinâmicas crescem verticalmente quando necessário. Isso
   elimina micro-overflow de palavras como "Prorrogação" em células estreitas. */
.live-score-row > div{ min-width: 0; }
.live-score-row > div em{
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.15;
}
.live-score-outcome{
  flex-wrap: wrap;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}
.live-score-outcome b, .live-score-outcome span{
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}

/* ===== V370 · auditoria de interação mobile =====
   Modais usam grid real no cabeçalho para preservar os dois controles de 38px
   mesmo com títulos dinâmicos longos. A lista moderna de elenco reduz para as
   três colunas realmente visíveis no mobile (camisa, jogador e estado), pois
   função e chevron ficam ocultos nesse contexto. */
.app-modal > header{
  display: grid;
  grid-template-columns: 38px minmax(0,1fr) 38px;
  align-items: center;
}
.app-modal > header > :is(div,h1,h2,h3){ min-width: 0; }
.app-modal > header :is(.modal-back,.modal-close){
  width: 38px;
  min-width: 38px;
  max-width: 38px;
  height: 38px;
  flex: none;
}
.app-modal > header h2{
  max-width: 100%;
  overflow-wrap: anywhere;
}
.team-squad-modal-row.modern{
  min-width: 0;
}
.team-squad-modal-row.modern .team-player-copy, .team-squad-modal-row.modern .team-player-meta{ min-width: 0; }

/* No layout mobile a função e o chevron já são ocultados; a grade acompanha
   exatamente os três itens restantes para não entregar toda a largura ao nome. */
.team-squad-modal-row.modern{
  grid-template-columns: auto minmax(0,1fr) auto;
}
.app-modal.is-locked > header{
  grid-template-columns: minmax(0,1fr) auto;
}
.app-modal.is-locked > header .modal-required-badge{
  min-width: 0;
  max-width: min(42vw, 180px);
  white-space: normal;
  overflow-wrap: anywhere;
  text-align: right;
}

/* Toast continua compacto, mas o alvo de fechar não pode cair abaixo de uma
   área de toque razoável no mobile. O ganho é só de interação; texto e posição
   do aviso permanecem os mesmos. */
.toast{
  grid-template-columns: 24px minmax(0,1fr) auto 32px !important;
}
.toast-close, .toast-stack.is-live-context .toast-close{
  width: 32px !important;
  height: 32px !important;
  min-width: 32px !important;
  min-height: 32px !important;
  border-radius: 9px !important;
}
/* ==========================================================
   V370 · interação mobile e colunas somente quando há largura útil
   ========================================================== */
/* Papéis durante o jogo carregam nome + atributo + seleção. Em duas colunas
   o conteúdo dependia de reticências até em nomes normais; no mobile cada
   jogador recebe a largura inteira. */
.role-player-grid{
  grid-template-columns: minmax(0,1fr) !important;
}

/* Os comandos do Ao Vivo não podem virar seis botões estreitos em uma única
   fileira. Três por linha preservam leitura e alvo de toque sem transformar
   o painel em uma lista longa. */
.match-screen .live-management-actions, html[data-theme] .match-screen .live-management-actions{
  display: grid !important;
  grid-template-columns: repeat(3,minmax(0,1fr)) !important;
  grid-auto-flow: row !important;
  grid-auto-rows: 44px !important;
  gap: 6px !important;
  overflow: visible !important;
}
.match-screen .live-management-actions > :is(button,.btn), html[data-theme] .match-screen .live-management-actions > :is(button,.btn){
  width: 100% !important;
  min-width: 0 !important;
  min-height: 44px !important;
  height: 44px !important;
  max-height: 44px !important;
  flex: none !important;
}

/* Filtros com valores reais (temporada/liga) ganham uma linha por campo.
   Abreviação por falta de coluna não é necessária em um jogo mobile. */
.statistics-filter-group{
  grid-template-columns: minmax(0,1fr) !important;
  width: 100% !important;
}

/* Garantias finais para componentes ricos já auditados: se o item contém
   texto variável + metadados/ações, o menor layout não força duas colunas. */
.substitution-choice-columns, .quick-menu-cluster-grid, .football-team-sheets, .football-xi-grid, .clone-search-results, .assistant-review-grid, .opponent-findings, .career-summary-columns, .heatmap-grid{
  grid-template-columns: minmax(0,1fr) !important;
}

/* ==========================================================
   V371 · auditoria de densidade e colunas mobile
   ==========================================================
   Regra de interface: coluna só permanece quando o conteúdo real continua
   confortável. Se a divisão exigir fonte minúscula, reticências ou esmagar
   nome/badge/valor/ação, o componente empilha ou reduz a quantidade de colunas.
*/

/* Blocos ricos: cada cartão precisa de largura integral para manter texto,
   contexto e valor legíveis. */
.manager-reputation-scope-grid, .stakeholder-grid, .player-identity-grid, .career-scenario-detail-grid{
  grid-template-columns: minmax(0,1fr) !important;
}
.player-identity-grid article, .career-scenario-detail-grid article{ min-width: 0; }
.career-scenario-detail-grid strong{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}
.manager-reputation-scope-grid em{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* Navegação curta pode continuar em grade, mas duas colunas dão largura real
   para “Estatísticas”, “Outros jogos”, “Atualizações” e “Privacidade”. */
.live-score-tab-grid, .landing-public-pages{
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
}
.live-score-tab-grid > button span, .landing-public-pages button > span{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  line-height: 1.15;
}

/* O resumo do topo não pode depender de rótulos de 0,4rem para caber em quatro
   colunas. Em 2x2 o contexto e os números permanecem legíveis sem esconder texto. */
.topbar-glance, .topbar-glance:has(.topbar-fans-chip){
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
  gap: 5px !important;
}
.topbar-page-context{
  justify-content: flex-start !important;
  padding-inline: 7px !important;
}
.topbar-page-context span{ display: block !important; }
.topbar-glance-chip, .topbar-page-context{ min-height: 34px !important; }
.topbar-glance-chip small{ font-size: .5rem !important; }
.topbar-glance-chip strong{ font-size: .64rem !important; }

/* Formulários têm rótulos, opções e valores variáveis. No layout mobile eles
   usam a largura completa em vez de dividir selects/inputs em duas colunas. */
:is(.form-grid,.editor-form,.market-modal-form,.manager-profile-form,.national-squad-filters,
    .market-filter-grid,.scout-form-grid,.fc-form,.save-plan-form,.direct-offer-form){
  grid-template-columns: minmax(0,1fr) !important;
}
:is(.form-grid,.editor-form,.market-modal-form,.manager-profile-form,.national-squad-filters,
    .market-filter-grid,.scout-form-grid,.fc-form,.save-plan-form,.direct-offer-form) > *{
  grid-column: 1 !important;
  min-width: 0;
}

/* Pedido de conversa: o prazo não disputa a linha principal com nome + assunto.
   Ícone e chevron ficam nas bordas; o prazo usa uma linha própria dentro da
   coluna textual. */
.player-request-row{
  grid-template-columns: 40px minmax(0,1fr) 24px !important;
  grid-template-rows: auto auto;
  align-items: start !important;
}
.player-request-row > span:first-child{
  grid-column: 1;
  grid-row: 1 / 3;
  align-self: center;
}
.player-request-row > div{
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
}
.player-request-row > b{
  grid-column: 2;
  grid-row: 2;
  justify-self: start;
  white-space: normal !important;
}
.player-request-row > :is(.fa-solid,.fa-regular):last-child{
  grid-column: 3;
  grid-row: 1 / 3;
  align-self: center;
  justify-self: center;
}

/* Metas da temporada têm título, badge obrigatório/complementar e estado final.
   O estado não fica em uma terceira coluna roubando largura da descrição. */
.season-objective-row{
  grid-template-columns: 38px minmax(0,1fr) !important;
  grid-template-rows: auto auto;
}
.season-objective-row > .season-objective-icon{
  grid-column: 1;
  grid-row: 1 / 3;
}
.season-objective-row > div{
  grid-column: 2;
  grid-row: 1;
}
.season-objective-row > b{
  grid-column: 2;
  grid-row: 2;
  justify-self: start;
  white-space: normal !important;
}
.season-objective-row header{
  flex-wrap: wrap;
}
.season-objective-row header strong{ flex: 1 1 170px; }
.season-objective-row header em{ flex: 0 1 auto; }

/* V371 · continuação da auditoria de densidade
   Scorecards com rótulo + valor + explicação são conteúdo rico: no mobile usam
   a largura inteira. Métricas realmente curtas podem continuar em grade. */
.manager-market-scorecards, .world-digest-scorecards, .country-coefficient-scorecards, .finance-model-grid, .cash-flow{
  grid-template-columns: minmax(0,1fr) !important;
}
.manager-market-scorecards > *, .world-digest-scorecards > *, .country-coefficient-scorecards > *{
  grid-column: 1 !important;
  min-width: 0;
}

/* Mercado de técnicos: a data não rouba largura da descrição. */
.manager-market-event{
  grid-template-columns: 30px minmax(0,1fr) !important;
  grid-template-rows: auto auto;
  align-items: start !important;
}
.manager-market-event > span{
  grid-column: 1;
  grid-row: 1 / 3;
  align-self: center;
}
.manager-market-event > div{
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
}
.manager-market-event > em{
  grid-column: 2;
  grid-row: 2;
  justify-self: start;
  white-space: normal !important;
}

/* Ranking continental: nome do país ganha a largura textual inteira. Coeficiente
   e tendência, que são curtos, dividem apenas a linha de métricas; contexto e
   campanha ficam abaixo. */
.country-coefficient-row{
  grid-template-columns: 28px minmax(0,1fr) auto !important;
  grid-template-rows: auto auto auto auto !important;
}
.country-coefficient-rank{
  grid-column: 1;
  grid-row: 1 / 5 !important;
}
.country-coefficient-country{
  grid-column: 2 / 4;
  grid-row: 1;
}
.country-coefficient-country strong, .country-coefficient-country small{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}
.country-coefficient-number{
  grid-column: 2;
  grid-row: 2;
  text-align: left !important;
}
.country-coefficient-trend{
  grid-column: 3;
  grid-row: 2;
}
.country-coefficient-slot{
  grid-column: 2 / 4 !important;
  grid-row: 3;
}
.country-coefficient-form{
  grid-column: 2 / 4 !important;
  grid-row: 4 !important;
}
.country-coefficient-slot strong, .country-coefficient-form strong{
  white-space: normal !important;
  overflow-wrap: anywhere;
}

/* Passaporte: cinco colunas exigiam fonte minúscula/reticências. Duas colunas
   são o limite para essas métricas; a quinta ocupa a largura completa. */
.manager-passport-summary, .manager-passport-stats{
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
}
.manager-passport-summary > :last-child, .manager-passport-stats > :last-child{
  grid-column: 1 / -1;
}
.manager-passport-summary small{
  font-size: .6rem !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
}
.manager-passport-stats small{ font-size: .58rem !important; }
.manager-passport-stats b{ font-size: .78rem !important; }

/* KPIs com ícone + rótulo + valor usam no máximo duas colunas. */
.manager-profile-kpis, .team-profile-kpis{
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
}

/* Resumo de estilo tem rótulos variáveis e barra de progresso; empilhar evita
   que “Negociação”, “Pragmatismo” etc. dependam de reticências. */
.manager-style-grid{
  grid-template-columns: minmax(0,1fr) !important;
}
.manager-style-grid article > span{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* Histórico de reputação: escopo/temporada vira metadado abaixo do motivo em
   vez de uma terceira coluna que comprime a descrição. */
.manager-reputation-history > div > span{
  grid-template-columns: auto minmax(0,1fr) !important;
  grid-template-rows: auto auto;
  align-items: start !important;
}
.manager-reputation-history b{
  grid-column: 1;
  grid-row: 1 / 3;
  align-self: center;
}
.manager-reputation-history em{
  grid-column: 2;
  grid-row: 1;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}
.manager-reputation-history small{
  grid-column: 2;
  grid-row: 2;
  white-space: normal !important;
}

/* Nome do clube/seleção no passaporte é informação principal e não deve ser
   sacrificado para manter o cabeçalho em uma única linha. */
.manager-passport-stint-head strong{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* ==========================================================
   V372 · auditoria dirigida: Médico, Estádio, História e finais
   ==========================================================
   Regra permanente: em um jogo mobile, uma grade só permanece quando o
   conteúdo real continua confortável. Se a coluna depender de fonte minúscula,
   rótulo oculto, elipse obrigatória ou disputa entre texto e valor, empilhar.
*/

/* Centro médico: os resumos carregam explicação, não são KPIs secos. Uma coluna
   preserva título, número e orientação sem reduzir a leitura para ~0,5rem. */
.medical-overview-grid, .medical-legend{
  grid-template-columns: minmax(0,1fr) !important;
}
.medical-overview-grid article{
  min-width: 0;
  align-items: flex-start;
}
.medical-overview-grid small{ font-size: .58rem !important; }
.medical-overview-grid strong{ font-size: .92rem !important; }
.medical-overview-grid p{ font-size: .58rem !important; line-height: 1.4 !important; }
.medical-legend strong{ font-size: .64rem !important; }
.medical-legend span{ font-size: .57rem !important; line-height: 1.4 !important; }

/* Nome do atleta e risco não disputam a mesma linha. O risco é metadado e fica
   abaixo da identificação, preservando inclusive nomes compostos. */
.medical-care-card header{
  display: grid !important;
  grid-template-columns: minmax(0,1fr) !important;
  align-items: start !important;
}
.medical-care-card header > button{
  width: 100%;
  min-width: 0;
}
.medical-care-card header > .risk-badge{
  justify-self: start;
  max-width: 100%;
  margin-left: 47px;
  white-space: normal;
  overflow-wrap: anywhere;
}
.medical-care-card header strong{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* Três números curtos e previsíveis podem continuar lado a lado. O antigo 2+1
   deixava a carga sozinha na segunda linha sem ganhar legibilidade. */
.medical-metric-row{
  grid-template-columns: repeat(3,minmax(0,1fr)) !important;
}
.medical-metric-row small{ font-size: .54rem !important; }
.medical-metric-row strong{ font-size: .66rem !important; }

/* Estádio: preço sugerido/público, custo de obra e detalhes do projeto são
   valores variáveis. Não disputam meia linha com texto explicativo. */
.ticket-hint{
  display: grid !important;
  grid-template-columns: minmax(0,1fr) !important;
  justify-content: stretch !important;
  gap: 4px !important;
}
.ticket-hint > span{
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
}
.upgrade-card{
  grid-template-columns: minmax(0,1fr) !important;
  align-items: start !important;
}
.upgrade-card > strong{
  justify-self: start;
  white-space: normal;
  overflow-wrap: anywhere;
}
.stadium-construction-investment{
  display: grid !important;
  grid-template-columns: minmax(0,1fr) !important;
  justify-items: start !important;
  gap: 4px !important;
}
.stadium-construction-investment strong{
  text-align: left !important;
  white-space: normal;
  overflow-wrap: anywhere;
}

/* As quatro faixas são rótulos curtos e previsíveis, portanto podem continuar
   alinhadas ao medidor; não precisam, porém, de tipografia microscópica. */
.stadium-health-scale span{
  font-size: .54rem !important;
  line-height: 1.2;
}
.stadium-visual-specs > span{
  min-width: 0;
  flex-wrap: wrap;
  overflow-wrap: anywhere;
  line-height: 1.25;
}

/* História: um troféu contém nome variável de competição + temporada. Em 430px
   o auto-fit antigo podia criar duas colunas de ~190px e forçar leitura ruim. */
.trophy-cabinet{
  grid-template-columns: minmax(0,1fr) !important;
}
.trophy-cabinet article, .trophy-cabinet article div{ min-width: 0; }
.trophy-cabinet :is(strong,small){
  white-space: normal;
  overflow-wrap: anywhere;
}

/* Fim de competição é registro histórico: nomes de premiados não são conteúdo
   descartável e não devem terminar em reticências apenas para manter uma linha. */
.competition-end-awards article strong{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* Modo espectador: a lista de jogos permanece em uma coluna no menor layout.
   Isso evita que duas partidas com clubes de nomes longos voltem a competir por
   meia tela por causa de regras antigas mais específicas. */
.observer-live-mode .observer-grid{
  grid-template-columns: minmax(0,1fr) !important;
}

/* Histórico de temporada: a tabela antiga espremia oito colunas dentro de
   320px. Mantemos todos os dados, mas em duas faixas por linha: contexto
   (posição + clube + pontos) em cima e J/V/E/D/SG embaixo. */
.season-history-table-head, .season-history-table-row{
  grid-template-columns: 30px repeat(5,minmax(0,1fr)) 38px !important;
  grid-template-rows: auto auto;
  column-gap: 4px !important;
  row-gap: 2px !important;
  min-height: 46px !important;
  padding: 5px 7px !important;
  font-size: .62rem !important;
}
.season-history-table-head > :nth-child(1), .season-history-table-row > :nth-child(1){
  grid-column: 1;
  grid-row: 1 / 3;
  align-self: center;
}
.season-history-table-head > :nth-child(2), .season-history-table-row > :nth-child(2){
  grid-column: 2 / 7;
  grid-row: 1;
  min-width: 0;
  text-align: left;
}
.season-history-table-head > :nth-child(3), .season-history-table-row > :nth-child(3){ grid-column: 2; grid-row: 2; }
.season-history-table-head > :nth-child(4), .season-history-table-row > :nth-child(4){ grid-column: 3; grid-row: 2; }
.season-history-table-head > :nth-child(5), .season-history-table-row > :nth-child(5){ grid-column: 4; grid-row: 2; }
.season-history-table-head > :nth-child(6), .season-history-table-row > :nth-child(6){ grid-column: 5; grid-row: 2; }
.season-history-table-head > :nth-child(7), .season-history-table-row > :nth-child(7){ grid-column: 6; grid-row: 2; }
.season-history-table-head > :nth-child(8), .season-history-table-row > :nth-child(8){
  grid-column: 7;
  grid-row: 1 / 3;
  align-self: center;
}
.season-history-table-head > :nth-child(n/**/+3):nth-child(-n/**/+7){
  color: var(--muted);
  font-size: .56rem;
}
.season-history-club strong{
  font-size: .64rem !important;
}

/* Base: investimento é monetário e pode crescer; prazo é curto. Eles não
   precisam disputar meia largura apenas para conservar duas colunas. */
.academy-upgrade-details{
  grid-template-columns: minmax(0,1fr) !important;
}
.academy-upgrade-details strong{
  white-space: normal;
  overflow-wrap: anywhere;
}

/* ==========================================================
   V373 · identidade profissional e contraste adaptativo real
   ==========================================================
   A cor do clube é imprevisível. Estes banners nunca presumem branco: usam
   --team-gradient-text calculado pelo JavaScript e superfícies locais que
   reforçam a leitura sem descaracterizar a paleta oficial.
*/

/* Base visual compartilhada para perfis e heróis que recebem teamStyle. */
.manager-profile-hero-modern, .team-profile-hero-modern, .app-modal.has-team-context > header, .app-modal.has-team-context .player-profile-head.modern-player-hero, .legacy-museum-hero, .celebration-card, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero{
  position: relative;
  isolation: isolate;
  color: var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color: currentColor !important;
  border-color: var(--team-hero-border,color-mix(in srgb,currentColor 22%,transparent)) !important;
  background:
    radial-gradient(circle at 88% 12%,var(--team-hero-decor,rgba(255,255,255,.10)),transparent 34%),
    linear-gradient(135deg,var(--team-gradient-primary,#27364f),var(--team-gradient-secondary,#101827)) !important;
  text-shadow: none !important;
}
.manager-profile-hero-modern::before, .team-profile-hero-modern::before, .app-modal.has-team-context .player-profile-head.modern-player-hero::before, .legacy-museum-hero::before, .celebration-card::before, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero::before{
  content:"";
  position:absolute;
  z-index:-1;
  width:150px;
  height:150px;
  right:-58px;
  bottom:-88px;
  border:22px solid var(--team-hero-decor,rgba(255,255,255,.10));
  border-radius:50%;
  pointer-events:none;
}
:is(.manager-profile-hero-modern,.team-profile-hero-modern,.app-modal.has-team-context > header,.app-modal.has-team-context .player-profile-head.modern-player-hero,.legacy-museum-hero,.celebration-card,.competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero)
:is(h1,h2,h3,h4,p,strong,b,span,small,em,.kicker,.fa-solid,.fa-regular,button){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
  text-shadow: none !important;
}

/* O conteúdo secundário usa hierarquia por peso/espaço, não por opacidade que
   poderia derrubar contraste abaixo do mínimo em cores limítrofes. */
.manager-profile-hero-modern .manager-profile-identity p, .team-profile-hero-modern .team-profile-title p, .manager-profile-hero-modern .manager-profile-score :is(small,span), .team-profile-hero-modern .team-profile-rating :is(small,span), .team-profile-hero-modern .team-profile-crest-stage > span, .app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-summary, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero p{
  color: inherit !important;
  opacity: 1 !important;
}

/* Superfícies internas adaptam-se à cor de texto calculada: fundo escuro para
   texto claro e fundo claro para texto escuro. */
.manager-profile-hero-modern .manager-profile-identity > div, .team-profile-hero-modern .team-profile-title, .manager-profile-hero-modern .manager-profile-badges > span, .manager-profile-hero-modern .manager-profile-score, .team-profile-hero-modern .team-profile-tags > span, .team-profile-hero-modern .team-profile-rating, .app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-overall, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-position, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-placement-callout{
  color: inherit !important;
  background: var(--team-hero-panel,rgba(7,17,31,.38)) !important;
  border-color: var(--team-hero-border,rgba(255,255,255,.24)) !important;
  box-shadow: inset 0 1px 0 var(--team-hero-decor,rgba(255,255,255,.10)) !important;
}
.manager-profile-hero-modern .kicker, .team-profile-hero-modern .kicker, .app-modal.has-team-context .player-profile-head.modern-player-hero .badge, .competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero .kicker{
  color: inherit !important;
  background: var(--team-hero-panel-strong,rgba(7,17,31,.50)) !important;
  border-color: var(--team-hero-border,rgba(255,255,255,.24)) !important;
}

/* Perfil do técnico: foto + identidade têm largura útil real; a nota não fica
   absoluta roubando espaço do nome. A faixa inferior funciona como assinatura
   profissional do banner. */
.manager-profile-hero-modern{
  grid-template-columns: minmax(0,1fr) !important;
  gap: 12px !important;
  padding: 17px !important;
  border-radius: 22px !important;
  overflow: hidden;
  box-shadow: 0 12px 28px color-mix(in srgb,var(--team-gradient-secondary,#101827) 20%,transparent);
}
.manager-profile-identity{
  grid-template-columns: 64px minmax(0,1fr) !important;
  gap: 11px !important;
  padding-right: 0 !important;
}
.manager-profile-photo-modern{
  width:64px !important;
  height:64px !important;
  border:2px solid var(--team-hero-border,rgba(255,255,255,.24)) !important;
  border-radius:18px !important;
  box-shadow:none !important;
  filter:none !important;
}
.manager-profile-identity > div{
  min-width:0;
  padding:10px 11px !important;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.24));
  border-radius:15px;
}
.manager-profile-identity h2{
  margin:4px 0 !important;
  font-size:clamp(1.08rem,5vw,1.4rem) !important;
  line-height:1.08;
  overflow-wrap:anywhere;
}
.manager-profile-badges{ margin-top:8px !important; gap:5px !important; }
.manager-profile-badges > span{ padding:5px 7px !important; font-size:.58rem !important; }
.manager-profile-score{
  position:static !important;
  width:100% !important;
  min-width:0 !important;
  display:grid !important;
  grid-template-columns:minmax(0,1fr) auto auto !important;
  align-items:center !important;
  justify-items:start !important;
  gap:8px !important;
  padding:9px 11px !important;
  border-radius:14px !important;
}
.manager-profile-score strong{ font-size:1.35rem !important; line-height:1 !important; }
.manager-profile-score span{ justify-self:end; font-size:.58rem !important; }

/* Perfil de clube/seleção: brasão em moldura discreta, nome com quebra natural,
   todos os chips disponíveis e nota em faixa própria em vez de terceira coluna. */
.team-profile-hero-modern{
  grid-template-columns:68px minmax(0,1fr) !important;
  gap:11px !important;
  padding:15px !important;
  border-radius:22px !important;
  overflow:hidden;
  box-shadow:0 12px 28px color-mix(in srgb,var(--team-gradient-secondary,#101827) 20%,transparent);
}
.team-profile-crest-stage{
  width:68px;
  min-width:68px !important;
  padding:7px 5px;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.24));
  border-radius:17px;
  background:var(--team-hero-panel,rgba(7,17,31,.38));
  filter:none !important;
}
.team-profile-crest-stage .crest{ width:52px !important; height:58px !important; }
.team-profile-title{
  min-width:0;
  padding:10px 11px !important;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.24));
  border-radius:15px;
}
.team-profile-title h3{
  margin:4px 0 !important;
  font-size:clamp(1.02rem,5vw,1.32rem) !important;
  line-height:1.08;
  white-space:normal !important;
  overflow:visible !important;
  text-overflow:clip !important;
  overflow-wrap:anywhere;
}
.team-profile-title p{ font-size:.64rem !important; line-height:1.4 !important; overflow-wrap:anywhere; }
.team-profile-tags{ margin-top:8px !important; gap:5px !important; }
.team-profile-tags > span{
  display:inline-flex !important;
  max-width:100%;
  white-space:normal !important;
  overflow-wrap:anywhere;
  padding:5px 7px !important;
  font-size:.56rem !important;
}
.team-profile-rating{
  grid-column:1 / -1 !important;
  width:100% !important;
  min-width:0 !important;
  grid-template-columns:minmax(0,1fr) auto !important;
  grid-template-rows:auto auto;
  align-items:center !important;
  justify-items:start !important;
  gap:2px 8px !important;
  padding:9px 11px !important;
  border-radius:14px !important;
}
.team-profile-rating small{ grid-column:1; grid-row:1; }
.team-profile-rating strong{ grid-column:2; grid-row:1 / 3; align-self:center; font-size:1.45rem !important; }
.team-profile-rating span{ grid-column:1; grid-row:2; font-size:.57rem !important; }

/* Perfil do jogador dentro de contexto de clube também vira um banner de
   identidade coerente. Overall desce para faixa inteira e não aperta o resumo. */
.app-modal.has-team-context .player-profile-head.modern-player-hero{
  grid-template-columns:40px minmax(0,1fr) !important;
  gap:10px !important;
  padding:13px !important;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.24)) !important;
  border-radius:18px !important;
  overflow:hidden;
}
.app-modal.has-team-context .player-profile-head.modern-player-hero > .crest{
  grid-column:1;
  grid-row:1;
  align-self:start;
  width:36px !important;
  height:42px !important;
}
.app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-identity{
  grid-column:2;
  grid-row:1;
  min-width:0;
}
.app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-summary{
  white-space:normal !important;
  overflow:visible !important;
  text-overflow:clip !important;
  overflow-wrap:anywhere;
}
.app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-overall{
  grid-column:1 / -1 !important;
  grid-row:2 !important;
  width:100%;
  min-width:0 !important;
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
  gap:8px;
  padding:8px 10px;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.24));
  border-radius:12px;
  font-size:1.15rem !important;
}
.app-modal.has-team-context .player-profile-head.modern-player-hero .player-profile-overall small{
  margin:0 !important;
  text-align:right;
}

/* Museu e celebrações seguem o mesmo contraste adaptativo, sem texto branco
   herdado quando a paleta calculada pede texto escuro. */
.legacy-museum-hero, .celebration-card{
  color:var(--team-gradient-text,#fff) !important;
}
.legacy-museum-hero :is(.legacy-museum-tags > span,.legacy-hero-stats > span,.legacy-museum-callout), .celebration-card :is(.placement-rank,.celebration-prize){
  color:inherit !important;
  background:var(--team-hero-panel,rgba(7,17,31,.38)) !important;
  border-color:var(--team-hero-border,rgba(255,255,255,.24)) !important;
}
.celebration-card > .kicker, .celebration-card .celebration-prize small, .celebration-card .celebration-manager-name, .celebration-card > small{
  color:inherit !important;
  opacity:1 !important;
}
.celebration-card .placement-rank.is-title, .celebration-card .celebration-prize strong{
  color:inherit !important;
}
.celebration-trophy{
  color:inherit !important;
  background:var(--team-hero-panel-strong,rgba(7,17,31,.50)) !important;
  border-color:var(--team-hero-border,rgba(255,255,255,.24)) !important;
}

/* Encerramento de competição: a campanha usa no máximo duas colunas no mobile;
   seis métricas em 3/4/6 colunas não trazem ganho de leitura em 320px. */
.competition-end-campaign{
  grid-template-columns:repeat(2,minmax(0,1fr)) !important;
}
.competition-end-campaign > div{ min-width:0; padding:10px 8px !important; }

/* Ações de fim de competição continuam empilhadas quando o texto real puder
   crescer; não criar meia tela para pódio/prêmios com nomes variáveis. */
.competition-end-columns{ grid-template-columns:minmax(0,1fr) !important; }

/* Heróis com teamStyle fora dos perfis também respeitam a cor calculada. */
:is(.career-summary-hero,.header-detail-hero,.market-command-hero,.national-duty-entry-identity,.opponent-hero)[style*="--team-gradient-primary"]{
  color:var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color:currentColor !important;
  background:
    radial-gradient(circle at 86% 12%,var(--team-hero-decor,rgba(255,255,255,.10)),transparent 35%),
    linear-gradient(135deg,var(--team-gradient-primary,#27364f),var(--team-gradient-secondary,#101827)) !important;
  border-color:var(--team-hero-border,rgba(255,255,255,.24)) !important;
}
:is(.career-summary-hero,.header-detail-hero,.market-command-hero,.national-duty-entry-identity,.opponent-hero)[style*="--team-gradient-primary"]
:is(h1,h2,h3,h4,p,strong,b,span,small,em,.kicker,.fa-solid,.fa-regular){
  color:inherit !important;
  -webkit-text-fill-color:currentColor !important;
  text-shadow:none !important;
}

/* Cards de carreira também recebem teamStyle. Não reaplicar uma camada escura
   fixa depois que a paleta já foi corrigida para texto claro OU escuro. */
.landing-continue-career.team-tone, .landing-save-card .save-slot-team-card.team-tone, html[data-theme="light"] .landing-continue-career.team-tone, html[data-theme="light"] .landing-save-card .save-slot-team-card.team-tone, html[data-theme="dark"] .landing-continue-career.team-tone, html[data-theme="dark"] .landing-save-card .save-slot-team-card.team-tone{
  color:var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color:currentColor !important;
  background:
    radial-gradient(circle at 88% 12%,var(--team-hero-decor,rgba(255,255,255,.10)),transparent 36%),
    var(--team-palette-gradient,linear-gradient(135deg,var(--team-gradient-primary),var(--team-gradient-secondary))) !important;
  border-color:var(--team-hero-border,rgba(255,255,255,.24)) !important;
}
:is(.landing-continue-career.team-tone,.landing-save-card .save-slot-team-card.team-tone)
:is(strong,span,small,em,.fa-solid,.fa-regular,.btn){
  color:inherit !important;
  -webkit-text-fill-color:currentColor !important;
  text-shadow:none !important;
}
.landing-continue-career.team-tone :is(.landing-continue-icon,.landing-continue-action), .landing-save-card .save-slot-team-card.team-tone > .btn{
  color:inherit !important;
  background:var(--team-hero-panel,rgba(7,17,31,.38)) !important;
  border-color:var(--team-hero-border,rgba(255,255,255,.24)) !important;
}

/* =========================================================
   V373 · retrospectivas sem informação escondida no mobile
   Se o conteúdo só cabe escondendo badges ou cortando nomes,
   ele deixa de disputar a mesma linha.
   ========================================================= */
.season-retrospective-card > summary{
  grid-template-columns: 42px minmax(0,1fr) auto !important;
  align-items: start;
}

.season-retro-summary-copy strong, .season-retro-summary-copy small, .season-current-card strong, .season-retro-leader small, .season-retro-leader strong, .season-retro-leader em, .season-retro-awards b, .season-retro-awards small{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

.season-retro-summary-badges{
  display: flex !important;
  grid-column: 2 / -1;
  grid-row: 2;
  justify-self: stretch;
  align-items: center;
  justify-content: flex-start;
  gap: 6px 10px;
  flex-wrap: wrap;
  text-align: left;
  min-width: 0;
}

.season-retro-summary-badges b, .season-retro-summary-badges small{
  display: inline-flex;
  min-width: 0;
}

.season-retro-awards{
  grid-template-columns: 1fr !important;
}

/* ==========================================================
   V373 · auditoria de densidade complementar
   ==========================================================
   “Caber” não é suficiente: controles e descrições não devem depender de
   células estreitas, reticências ou tipografia microscópica para funcionar.
*/

/* Menu do Ao Vivo: cinco velocidades em cinco colunas deixavam “Muito rápida”
   com ~56px em 320px. Duas colunas preservam o rótulo; a quinta usa a largura
   total e funciona como opção de destaque sem virar botão minúsculo. */
.live-score-speed-grid{
  grid-template-columns: repeat(2,minmax(0,1fr)) !important;
  gap: 7px !important;
}
.live-score-speed-grid > .live-score-speed:last-child:nth-child(odd){
  grid-column: 1 / -1;
}
.live-score-speed{
  min-height: 46px !important;
  padding: 7px 8px !important;
}
.live-score-speed span{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  font-size: .6rem !important;
  line-height: 1.15;
}
.live-score-speed b{ font-size: .62rem !important; }

/* Os atalhos carregam título + explicação + ícone. Em duas colunas o texto
   descritivo virava 3–4 linhas desiguais; uma coluna mantém leitura e toque. */
.live-score-toggle-grid{
  grid-template-columns: minmax(0,1fr) !important;
}
.live-score-toggle-grid > button{ min-height: 48px; }
.live-score-toggle-grid strong{ font-size: .67rem !important; }
.live-score-toggle-grid small{ font-size: .56rem !important; }

/* O placar exibido dentro do menu é contexto importante. Nomes longos podem
   quebrar linha; nunca esconder um dos clubes com reticências. */
.live-score-quick-status strong{
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  line-height: 1.25;
}

/* Retrospectiva: duas métricas são texto narrativo (“Formação mais usada” e
   “Identidade”). Elas deixavam uma linha duas vezes mais alta que a vizinha.
   Uma coluna torna o arquivo histórico previsível e preserva a informação. */
.season-retro-metrics{
  grid-template-columns: minmax(0,1fr) !important;
}
.season-retro-metrics > span{ min-width: 0; }
.season-retro-metrics :is(small,strong){
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* Estádio: quatro descrições de estrutura não são KPIs de duas letras. A lista
   usa largura integral e tipografia confortável em vez de 2 colunas a ~9px. */
.stadium-visual-specs{
  grid-template-columns: minmax(0,1fr) !important;
}
.stadium-visual-specs span{
  justify-content: flex-start !important;
  padding: 8px 10px !important;
  font-size: .63rem !important;
  line-height: 1.3;
  text-align: left !important;
}

/* As três métricas médicas são curtas e previsíveis, portanto podem continuar
   lado a lado; aumentamos a tipografia para não pagar a compactação com leitura. */
.medical-metric-row small{ font-size: .59rem !important; }
.medical-metric-row strong{ font-size: .72rem !important; }

/* Cards de jogador favorito já usam uma única coluna no mobile. O nome não
   precisa ser cortado só para conservar uma linha ao lado do overall. */
.favorite-player-name, .favorite-player-team{
  width: 100% !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
  line-height: 1.25;
}

/* Refinamento dos banners: chips continuam compactos, mas não microscópicos. */
.manager-profile-badges > span{ font-size: .62rem !important; line-height: 1.25; }
.team-profile-tags > span{ font-size: .6rem !important; line-height: 1.25; }
.manager-profile-score :is(small,span), .team-profile-rating :is(small,span){ font-size: .61rem !important; }
.manager-profile-score strong, .team-profile-rating strong, .player-profile-overall{ font-variant-numeric: tabular-nums; }

/* ==========================================================
   V374 · círculos percentuais e polimento de interação
   ==========================================================
   Somente indicadores que já eram circulares/percentuais entram neste sistema.
   Barras e métricas comuns permanecem no formato que melhor comunica o dado.
*/
.percentage-ring{
  --percentage-ring-track: color-mix(in srgb,var(--line) 72%,transparent);
  font-variant-numeric: tabular-nums;
  isolation:isolate;
}
.percentage-ring::before, .percentage-ring::after{ pointer-events:none; }
.percentage-ring strong{
  display:inline-flex;
  align-items:flex-start;
  justify-content:center;
  gap:1px;
  line-height:.88;
  letter-spacing:-.045em;
  font-variant-numeric:tabular-nums;
}
.percentage-ring strong > b{
  font:inherit;
  font-weight:700;
}
.percentage-ring strong > small{
  margin-top:.08em;
  font-size:.47em;
  line-height:1;
  letter-spacing:0;
  font-weight:700;
  color:inherit;
  opacity:.86;
}
.percentage-ring > span, .percentage-ring > span > small{
  letter-spacing:.055em;
}

/* Tática: o card recebe teamStyle, portanto anel, miolo e texto usam a mesma
   paleta acessível em vez de voltar a presumir branco. */
.tactic-identity-card{
  color:var(--team-gradient-text,#fff) !important;
  text-shadow:none !important;
  background:
    radial-gradient(circle at 90% 14%,var(--team-hero-decor,rgba(255,255,255,.10)),transparent 35%),
    linear-gradient(135deg,var(--team-gradient-primary,var(--club-primary)),var(--team-gradient-secondary,var(--club-secondary))) !important;
  border-color:var(--team-hero-border,color-mix(in srgb,currentColor 22%,transparent)) !important;
}
.tactic-identity-card :is(h3,p,span,strong,small,.kicker,.fa-solid,.fa-regular){
  color:inherit !important;
  text-shadow:none !important;
}
.tactic-score-ring{
  width:74px !important;
  height:74px !important;
  background:conic-gradient(
    var(--team-gradient-text,#fff) var(--score),
    color-mix(in srgb,var(--team-gradient-text,#fff) 20%,transparent) 0
  ) !important;
  box-shadow:0 8px 22px color-mix(in srgb,var(--team-gradient-secondary,#101827) 26%,transparent);
}
.tactic-score-ring::after{
  inset:6px !important;
  background:var(--team-hero-panel-strong,rgba(7,17,31,.56)) !important;
  border:1px solid var(--team-hero-border,rgba(255,255,255,.22));
}
.tactic-score-ring strong{
  font-size:1.22rem !important;
  transform:translateY(-5px) !important;
}
.tactic-score-ring > span{
  font-size:.55rem !important;
  transform:translateY(13px) !important;
  opacity:1 !important;
  text-transform:uppercase;
  font-weight:700;
}

/* Vestiário: o anel continua neutro, mas o progresso ganha contraste suficiente
   contra o painel mesmo quando a cor principal do clube é muito escura. */
.locker-score{
  width:96px !important;
  height:96px !important;
  flex-basis:96px !important;
  background:conic-gradient(
    color-mix(in srgb,var(--club-primary) 66%,var(--text) 34%) calc(var(--locker-score,68)*1%),
    var(--percentage-ring-track) 0
  ) !important;
  box-shadow:0 10px 25px color-mix(in srgb,var(--club-primary) 14%,transparent);
}
.locker-score::before{
  inset:7px !important;
  border:1px solid color-mix(in srgb,var(--line) 84%,transparent);
}
.locker-score strong{
  font-size:1.48rem !important;
  transform:translateY(-7px);
}
.locker-score > span{
  margin-top:0 !important;
  transform:translateY(17px);
  font-size:.58rem !important;
  text-transform:uppercase;
  font-weight:700;
}

/* Legado: o anel sempre representou percentual. Agora o centro mostra o mesmo
   conceito visual; os pontos continuam disponíveis como informação secundária. */
.manager-legacy-score{
  width:clamp(118px,30vw,148px) !important;
  background:conic-gradient(
    #f2c85b var(--legacy-score),
    color-mix(in srgb,var(--line) 78%,transparent) 0
  ) !important;
  box-shadow:0 14px 36px rgba(0,0,0,.18), inset 0 0 0 1px color-mix(in srgb,#f2c85b 24%,transparent);
}
.manager-legacy-score:before{
  inset:9px !important;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,#f2c85b 15%,var(--line));
}
.manager-legacy-score > span{ gap:7px; }
.manager-legacy-score strong{ font-size:clamp(30px,8vw,42px) !important; }
.manager-legacy-score > span > small{
  margin-top:0 !important;
  font-size:.59rem !important;
  line-height:1.2;
  color:var(--muted);
  font-weight:700;
  text-transform:uppercase;
}

/* O X de uma substituição em lote era 28×28px: visualmente pequeno e ruim para
   toque. A área cresce sem aumentar o desenho do ícone. */
.batch-substitution-list > article button{
  width:36px !important;
  height:36px !important;
  min-width:36px;
  min-height:36px;
  touch-action:manipulation;
}
.batch-substitution-list > article button :is(svg,.fa-solid,.fa-regular){
  font-size:.78rem;
}

/* Substituição em lote: nomes são conteúdo variável e não devem disputar duas
   meias colunas. Cada troca usa duas linhas legíveis dentro de um único bloco. */
.batch-substitution-list > article{
  grid-template-columns:30px minmax(0,1fr) 36px !important;
  gap:9px !important;
  align-items:center;
}
.batch-substitution-list > article > span{
  width:28px !important;
  height:28px !important;
}
.batch-substitution-pair{
  display:grid !important;
  gap:5px;
  min-width:0;
}
.batch-substitution-pair > div{
  display:grid;
  grid-template-columns:38px minmax(0,1fr);
  gap:7px;
  align-items:baseline;
  min-width:0;
}
.batch-substitution-pair small{
  color:var(--muted);
  font-size:.57rem !important;
  text-transform:uppercase;
  letter-spacing:.05em;
}
.batch-substitution-pair strong{
  min-width:0;
  white-space:normal !important;
  overflow:visible !important;
  text-overflow:clip !important;
  overflow-wrap:anywhere;
  font-size:.72rem;
}

/* Os dois heróis circulares têm texto explicativo variável. No menor layout o
   anel não disputa largura com título/descrição: ganha uma linha própria. */
.tactic-identity-card, .locker-hero{
  display:grid !important;
  grid-template-columns:minmax(0,1fr) !important;
  align-items:start !important;
  justify-items:stretch;
}
.tactic-score-ring, .locker-score{
  justify-self:center;
}
.tactic-identity-main{ width:100%; }
.locker-hero > div:first-child{ min-width:0; }
.locker-hero > div:first-child :is(h3,p){
  white-space:normal;
  overflow-wrap:anywhere;
}

/* ==========================================================
   V375 · leitura imediata de estados percentuais
   ==========================================================
   Não cria novos donuts. Percentuais que já representam um estado decisório
   ganham uma barra fina e uma cor semântica consistente. Valores financeiros,
   estatísticas e métricas descritivas continuam sendo números simples.
*/
.state-percent-meter{
  --state-meter-color: var(--primary);
  display: block;
  width: 100%;
  height: 5px;
  margin-top: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--progress-track-bg);
  box-shadow: inset 0 0 0 1px var(--progress-track-border);
  font-style: normal;
}
.state-percent-meter > b{
  display: block;
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background: var(--state-meter-color);
}
.state-percent-meter.is-success, :is(.confidence-pill,.stakeholder-grid article,.player-state-metric,.player-identity-grid article,.favorite-state-metric,.season-objective-score).is-success{
  --state-meter-color: var(--success);
  --state-text-color: var(--success);
}
.state-percent-meter.is-good, :is(.confidence-pill,.stakeholder-grid article,.player-state-metric,.player-identity-grid article,.favorite-state-metric,.season-objective-score).is-good{
  --state-meter-color: var(--primary);
  --state-text-color: var(--primary);
}
.state-percent-meter.is-warning, :is(.confidence-pill,.stakeholder-grid article,.player-state-metric,.player-identity-grid article,.favorite-state-metric,.season-objective-score).is-warning{
  --state-meter-color: var(--warning);
  --state-text-color: var(--warning);
}
.state-percent-meter.is-danger, :is(.confidence-pill,.stakeholder-grid article,.player-state-metric,.player-identity-grid article,.favorite-state-metric,.season-objective-score).is-danger{
  --state-meter-color: var(--danger);
  --state-text-color: var(--danger);
}
.state-percent-value, .season-objective-score, .confidence-pill > strong, .player-state-metric > strong, .player-identity-grid article > strong, .favorite-state-metric > strong{
  color: var(--state-text-color, var(--text));
  font-variant-numeric: tabular-nums;
}

/* A confiança no cabeçalho continua compacta, mas deixa de ser um número sem
   contexto visual. O medidor fica abaixo sem aumentar artificialmente o card. */
.confidence-pill{ min-width: 78px; padding-inline: 9px; }
.confidence-pill .state-percent-meter{ width: 100%; margin-top: 5px; }

/* Diretoria, torcida e elenco já possuíam barras; agora cada barra comunica o
   estado real em vez de herdar a mesma aparência independentemente do valor. */
.stakeholder-grid article{ --state-meter-color: var(--primary); }
.stakeholder-grid article > div > b{ color: var(--state-text-color, var(--text)); font-variant-numeric: tabular-nums; }
.stakeholder-grid article.is-success{ border-color: color-mix(in srgb,var(--success) 28%,var(--line)); }
.stakeholder-grid article.is-warning{ border-color: color-mix(in srgb,var(--warning) 34%,var(--line)); }
.stakeholder-grid article.is-danger{ border-color: color-mix(in srgb,var(--danger) 38%,var(--line)); }
.stakeholder-grid article:is(.is-success,.is-good,.is-warning,.is-danger) .stakeholder-icon{
  color: var(--state-text-color, var(--primary));
  background: color-mix(in srgb,var(--state-meter-color) 11%,var(--panel));
}
.stakeholder-grid .state-percent-meter{ margin-top: 5px; }

/* Objetivos continuam usando barras horizontais — o componente apropriado para
   progresso de meta. Apenas a cor final passa a refletir o estado da própria meta. */
.season-objective-row.is-complete .progress-track > span{ background: var(--success) !important; }
.season-objective-row.is-risk .progress-track > span{ background: var(--danger) !important; }
.season-objective-row.is-progress .progress-track > span{ background: var(--primary) !important; }
.season-objective-score{ font-variant-numeric: tabular-nums; }

/* Energia e moral são estados, não estatísticas históricas. Mantêm o mesmo card
   do perfil, mas com medidor fino; salário, valor, jogos e contrato não recebem gráfico. */
.player-state-metric{ --state-meter-color: var(--primary); }
.player-state-metric > .state-percent-meter{ grid-column: 1 / -1; }
.player-state-metric.is-warning{ border-color: color-mix(in srgb,var(--warning) 32%,var(--line)); }
.player-state-metric.is-danger{ border-color: color-mix(in srgb,var(--danger) 38%,var(--line)); }

/* Vínculo, confiança, satisfação e pressão por saída são percentuais cujo valor
   é o próprio conteúdo principal. A barra melhora leitura sem criar novo círculo. */
.player-identity-grid article{ --state-meter-color: var(--primary); }
.player-identity-grid article .state-percent-meter{ margin: 5px 0 7px; }
.player-identity-grid article.is-warning{ border-color: color-mix(in srgb,var(--warning) 32%,var(--line)); }
.player-identity-grid article.is-danger{ border-color: color-mix(in srgb,var(--danger) 38%,var(--line)); }

/* Favoritos é uma visão compacta: apenas o valor recebe tom semântico. Não há
   barra adicional para evitar poluir o card. */
.favorite-state-metric{ --state-text-color: var(--text); }
.favorite-state-metric.is-warning{ background: color-mix(in srgb,var(--warning) 7%,var(--panel-2)); }
.favorite-state-metric.is-danger{ background: color-mix(in srgb,var(--danger) 7%,var(--panel-2)); }

/* V375 · o risco médio já era um círculo percentual ativo. Ele recebe o mesmo
   acabamento dos outros anéis existentes, sem criar um novo tipo de gráfico. */
.medical-command-score.percentage-ring{
  --medical-risk-color: var(--success);
  position: relative;
  isolation: isolate;
  display: grid !important;
  grid-template-columns: 1fr !important;
  grid-template-rows: 1fr !important;
  place-items: center !important;
  width: 78px;
  height: 78px;
  min-width: 78px;
  min-height: 78px;
  border: 0;
  border-radius: 50%;
  background: conic-gradient(var(--medical-risk-color) var(--medical-risk), var(--percentage-ring-track) 0) !important;
  box-shadow: 0 10px 24px color-mix(in srgb,var(--medical-risk-color) 16%,transparent);
}
.medical-command-score.percentage-ring::before{
  content: "";
  position: absolute;
  inset: 7px;
  z-index: -1;
  border: 1px solid color-mix(in srgb,var(--medical-risk-color) 16%,var(--line));
  border-radius: 50%;
  background: var(--panel-2);
}
.medical-command-score.percentage-ring.success{ --medical-risk-color: var(--success); }
.medical-command-score.percentage-ring.warning{ --medical-risk-color: var(--warning); }
.medical-command-score.percentage-ring.danger{ --medical-risk-color: var(--danger); }
.medical-command-score.percentage-ring strong, .medical-command-score.percentage-ring > span{
  position: relative;
  z-index: 1;
  grid-column: 1;
  grid-row: 1;
}
.medical-command-score.percentage-ring strong{
  color: var(--medical-risk-color);
  font-size: 1.3rem;
  transform: translateY(-6px);
}
.medical-command-score.percentage-ring > span{
  align-self: center;
  margin-top: 25px;
  color: var(--muted);
  font-size: .52rem;
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: .055em;
  font-weight: 700;
}

/* O seletor legado não é mais usado pelo Centro médico atual, mas deixa de
   esconder rótulos caso esse componente seja reutilizado no futuro. */
.medical-plan-row{ grid-template-columns: 1fr !important; }
.medical-plan-row button span{
  display: inline !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}

/* V375 · alvos de toque antigos abaixo do conforto mobile. O ícone continua
   visualmente compacto; cresce apenas a caixa interativa quando há espaço. */
.history-controls button, .favorite-event-list article > button, .friendly-selected > button{
  min-width: 36px !important;
  width: 36px !important;
  min-height: 36px !important;
  height: 36px !important;
  touch-action: manipulation;
}
.topbar-menu-button{
  position: relative;
  overflow: visible !important;
  touch-action: manipulation;
}
.topbar-menu-button::after{
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 12px;
}



/* =========================================================
   V376 · transições estáveis e mídia resiliente
   ========================================================= */
/* Botões que viram spinner preservam a largura que já ocupavam. Isso evita
   que grupos de ações "respirem" ou troquem de coluna durante tarefas reais. */
.btn.is-busy-stable{
  min-inline-size: var(--busy-button-width, auto) !important;
}
.btn.is-busy-stable > .fa-spinner, button[aria-busy="true"] > .fa-spinner{
  flex: 0 0 auto;
}

/* Busca: vazio, loading e erro compartilham a mesma área mínima. A lista pode
   crescer normalmente quando existem resultados; apenas a transição deixa de
   provocar um salto brusco no modal. */
.universal-search-empty{
  min-height: 154px;
  align-content: center;
}
.universal-search-empty.is-loading > .fa-spinner{
  animation: share-spin .85s linear infinite;
}

/* Prévia de premiação: loading, erro e imagem pronta usam o mesmo slot 4:5.
   O card de compartilhamento já usa essa proporção; unificamos a celebração. */
.celebration-share-preview .share-preview-canvas{
  aspect-ratio: 4 / 5;
  display: grid;
  place-items: center;
}
.celebration-share-preview .share-preview-loading{
  min-height: 0 !important;
  width: 100%;
  height: 100%;
  align-content: center;
  text-align: center;
  padding: 16px;
}
.celebration-share-preview .share-preview-canvas img{
  width: 100%;
  height: 100%;
  object-fit: contain;
}

/* Foto do técnico e fallback usam a mesma caixa, evitando deslocamento caso
   a imagem do save esteja ausente ou corrompida. */
.manager-avatar, .manager-profile-photo, .manager-profile-photo-modern{
  overflow: hidden;
}
img[data-manager-photo]{
  object-fit: cover;
  object-position: center;
}


/* ==========================================================
   V378 · consistência final de ritmo visual e tipografia
   ==========================================================
   Microtexto não é uma solução de layout. Se um componente só continua
   compacto reduzindo informação útil a 5–8 px, a geometria deve ceder espaço
   antes da legibilidade. Esta seção corrige apenas componentes ativos medidos
   na auditoria, sem criar uma escala global que poderia inflar áreas densas. */

/* Ao Vivo: a V370 já eliminou seis comandos na mesma fileira; a tipografia
   antiga continuava presa à geometria anterior. Três por linha comportam
   rótulos reais, portanto não há motivo para mantê-los em ~7 px. */
.match-screen .live-management-actions, html[data-theme] .match-screen .live-management-actions{
  grid-auto-rows: 48px !important;
}
.match-screen .live-management-actions > :is(button,.btn), html[data-theme] .match-screen .live-management-actions > :is(button,.btn){
  min-height: 48px !important;
  height: 48px !important;
  max-height: 48px !important;
}
.match-screen .live-management-actions > :is(button,.btn) > .live-action-label, html[data-theme] .match-screen .live-management-actions > :is(button,.btn) > .live-action-label{
  min-height: 0 !important;
  font-size: .56rem !important;
  line-height: 1.12 !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  overflow-wrap: anywhere;
}
.match-screen .live-management-actions > :is(button,.btn) > small{
  font-size: .52rem !important;
  line-height: 1.05 !important;
}

/* As abas já usam overflow horizontal. Em vez de comprimir seis rótulos a
   ~6 px, cada opção ganha largura mínima confortável e o usuário pode rolar. */
.match-screen .live-information-panel > .live-info-tabs > button{
  flex-basis: 68px !important;
  min-width: 68px !important;
}
.match-screen .live-information-panel > .live-info-tabs > button .live-tab-label{
  font-size: .56rem !important;
  line-height: 1.12 !important;
  letter-spacing: 0 !important;
  overflow: visible !important;
  text-overflow: clip !important;
}

/* O gatilho do placar tinha o rótulo "opções" em ~5,4 px. É ação interativa,
   não decoração; a hierarquia continua pequena, mas legível. */
.pitch-score .live-score-menu-trigger > small{
  margin-top: 2px;
  gap: 3px;
  font-size: .56rem !important;
  line-height: 1.1 !important;
  letter-spacing: .02em;
}

/* Configurações rápidas do Ao Vivo: badges auxiliares podem ser compactos,
   mas não microscópicos. */
.live-score-setting-toggle em{
  font-size: .56rem !important;
  line-height: 1.15;
}
.live-score-settings-note, .live-score-setting-field > small, .live-score-setting-toggle small{
  font-size: .59rem !important;
  line-height: 1.35;
}

/* Metas: badge e estado pertencem à leitura da cobrança da diretoria. Como o
   layout já empilha o status, não há justificativa para tipografia sub-8 px. */
.season-objective-row header{ row-gap: 5px; }
.season-objective-row header em{
  padding: 4px 7px;
  font-size: .56rem !important;
  line-height: 1.15;
}
.season-objective-row > b, .season-objective-summary{ font-size: .61rem !important; line-height: 1.4; }
.season-objective-history article span{ font-size: .59rem !important; line-height: 1.35; }
.season-objective-history article small{ font-size: .57rem !important; line-height: 1.4; }

/* Histórico de retorno: categoria, cena e tempo não disputam mais uma única
   linha. A categoria ocupa a primeira faixa; cena e tempo formam a segunda. */
.return-timeline-meta{
  flex-wrap: wrap;
  column-gap: 7px;
  row-gap: 4px;
}
.return-timeline-meta > small{
  flex: 1 1 100%;
  width: 100%;
  overflow: visible !important;
  text-overflow: clip !important;
  white-space: normal !important;
  font-size: .57rem !important;
  line-height: 1.25;
}
.return-timeline-meta time{
  margin-left: auto;
  font-size: .57rem !important;
  line-height: 1.25;
}
.return-event-scene, .notification-scene-label{
  font-size: .56rem !important;
  line-height: 1.15;
}
.return-timeline-event strong{ font-size: .72rem; line-height: 1.35; }
.return-timeline-event p{ font-size: .61rem; line-height: 1.45; }
.return-timeline-event em, .notification-scene-evidence{ font-size: .58rem; line-height: 1.4; }

/* Estádio: o status do desenho usava descrição de ~6,9 px. O card ganha alguns
   pixels de altura para preservar a hierarquia sem sacrificar informação. */
.stadium-canvas-status{
  grid-template-columns: 28px minmax(0,1fr) auto !important;
  min-height: 38px !important;
  padding: 5px 8px !important;
  gap: 7px !important;
}
.stadium-canvas-status > span{
  width: 28px !important;
  height: 28px !important;
  font-size: .72rem !important;
}
.stadium-canvas-status strong{
  font-size: .69rem !important;
  line-height: 1.15 !important;
}
.stadium-canvas-status small{
  font-size: .56rem !important;
  line-height: 1.2 !important;
}
.stadium-canvas-status > b{ font-size: .7rem !important; }

/* Feedback médico e busca universal usam a mesma escala curta do restante dos
   cards compactos; o conteúdo principal não muda de geometria. */
.medical-plan-feedback span{ gap: 3px; }
.medical-plan-feedback strong{ font-size: .65rem; line-height: 1.25; }
.medical-plan-feedback small{ font-size: .59rem; line-height: 1.4; }
.universal-search-result small{ font-size: .58rem; line-height: 1.2; }
.universal-search-result strong{ font-size: .8rem; line-height: 1.25; }
.universal-search-result em{ font-size: .65rem; line-height: 1.3; }

/* ===== V380 · cabeçalho de modal sem coluna fantasma =====
   `.is-hidden` é uma regra global com `display:none !important`. Quando o modal
   não possui Voltar, portanto, o primeiro item realmente sai da grade. O header
   declara agora o estado estrutural e usa duas colunas nesse caso; com modal
   empilhado mantém três colunas. Isso preserva o X em 38px e entrega todo o
   espaço restante ao título, sem margens artificiais ou larguras fixas. */
.app-modal > header.has-no-modal-back{
  grid-template-columns: minmax(0,1fr) 38px;
}
.app-modal > header.has-modal-back{
  grid-template-columns: 38px minmax(0,1fr) 38px;
}
.app-modal.is-locked > header.has-no-modal-back{
  grid-template-columns: minmax(0,1fr) auto;
}
.app-modal > header.has-no-modal-back > :is(div,h1,h2,h3), .app-modal > header.has-modal-back > :is(div,h1,h2,h3){
  min-width: 0;
}

/* ===== V381 · modais encadeados, medidores e topo compacto =====
   Correções pontuais baseadas em bugs observados em uso real. Não altera motor,
   RNG, calendário, finanças, mercado, save ou qualquer valor esportivo. */

/* O percentual textual dos stakeholders usava um seletor amplo para <b>, que
   também atingia o <b> interno do medidor. A margem vertical era recortada pela
   barra de 5px e deixava visível apenas uma linha. O preenchimento do medidor
   nunca herda margem ou tipografia de texto. */
.state-percent-meter > b{
  margin: 0 !important;
  padding: 0 !important;
  height: 100% !important;
  line-height: 0 !important;
  font-size: 0 !important;
}
.stakeholder-grid article > div > b{
  margin: 4px 0 5px;
  font-size: .86rem;
}

/* O resumo inferior do topo mantém os quatro elementos visíveis na mesma
   fileira. A célula de contexto continua compacta (somente ícone) e os três
   indicadores restantes dividem o espaço útil sem criar uma segunda linha. */
.topbar-glance, .topbar-glance:has(.topbar-fans-chip){
  grid-template-columns: 31px repeat(3,minmax(0,1fr)) !important;
  grid-auto-flow: row !important;
  gap: 4px !important;
}
.topbar-page-context{
  display: flex !important;
  justify-content: center !important;
  padding: 0 !important;
}

.topbar-glance-chip{
  min-height: 27px !important;
  padding: 3px 4px !important;
}
.topbar{
  gap: 5px 8px !important;
  padding-bottom: 7px !important;
}

/* Sem partida definida não existe identidade de adversário para calcular
   contraste. O estado neutro usa superfície clara própria e texto/ícone preto,
   portanto permanece legível independentemente da cor do clube no topo. */
.topbar-glance-chip.is-rival.is-no-next-match{
  color: #050505 !important;
  background: #f4f6f8 !important;
  border-color: rgba(0,0,0,.18) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.8) !important;
}
.topbar-glance-chip.is-rival.is-no-next-match :is(
  .topbar-next-copy,
  .topbar-next-copy small,
  .topbar-next-copy strong,
  .topbar-next-crest,
  .fa-solid,
  .fa-regular,
  span
){
  color: #050505 !important;
  text-shadow: none !important;
}



/* ===== V382 · auditoria de contraste em superfícies de identidade =====
   A regra final é deliberadamente estreita: só protege conteúdo que vive sobre
   um herói com --team-gradient-text calculado. Cards neutros continuam usando
   --text/--muted e acentos de tema normalmente. */
html[data-theme="light"] :is(.manager-profile-hero-modern,.team-profile-hero-modern,.app-modal.has-team-context .player-profile-head.modern-player-hero,.legacy-museum-hero,.celebration-card,.competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero), html[data-theme="dark"] :is(.manager-profile-hero-modern,.team-profile-hero-modern,.app-modal.has-team-context .player-profile-head.modern-player-hero,.legacy-museum-hero,.celebration-card,.competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero){
  color: var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color: currentColor !important;
}
html[data-theme="light"] :is(.manager-profile-hero-modern,.team-profile-hero-modern,.app-modal.has-team-context .player-profile-head.modern-player-hero,.legacy-museum-hero,.celebration-card,.competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero)
:is(h1,h2,h3,h4,p,strong,b,span,small,em,.kicker,.fa-solid,.fa-regular), html[data-theme="dark"] :is(.manager-profile-hero-modern,.team-profile-hero-modern,.app-modal.has-team-context .player-profile-head.modern-player-hero,.legacy-museum-hero,.celebration-card,.competition-end-summary[style*="--team-gradient-primary"] .competition-end-hero)
:is(h1,h2,h3,h4,p,strong,b,span,small,em,.kicker,.fa-solid,.fa-regular){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}
html[data-theme="light"] :is(.legacy-museum-copy > .kicker,.manager-profile-identity > div > .kicker,.team-profile-title > .kicker), html[data-theme="dark"] :is(.legacy-museum-copy > .kicker,.manager-profile-identity > div > .kicker,.team-profile-title > .kicker){
  color: var(--team-gradient-text,#fff) !important;
  background: var(--team-hero-panel-strong,rgba(7,17,31,.50)) !important;
  border-color: var(--team-hero-border,rgba(255,255,255,.24)) !important;
}

/* ==========================================================
   V384 · contraste definitivo do Ao Vivo no tema claro
   ----------------------------------------------------------
   O Ao Vivo acumulou regras históricas para botões neutros,
   estados de pausa e identidade do clube. No tema claro isso
   podia combinar preenchimento branco herdado com superfície
   clara. Esta guarda final é deliberadamente local à partida:
   comandos disponíveis usam o verde do campo com texto branco;
   o aviso do Modo Turbo usa superfície verde clara com texto
   verde escuro, sem herdar a cor branca da identidade do time.
   ========================================================== */
