/* ==========================================================
   V385 · decisões importantes, topo sem jogo e comandos Ao Vivo
   ----------------------------------------------------------
   Ações de alto impacto deixam de depender de prompts nativos curtos.
   O estado sem próximo jogo recebe par fundo/texto inseparável nos dois
   temas. Comandos do Ao Vivo jamais mudam para cinza: quando indisponíveis,
   preservam a mesma paleta verde e usam somente opacidade para comunicar o
   estado desabilitado.
   ========================================================== */

/* Modal explicativo compartilhado por decisões importantes. */
.important-decision-modal{
  display: grid;
  gap: 12px;
}
.important-decision-hero{
  display: grid;
  grid-template-columns: 52px minmax(0,1fr);
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  color: var(--text) !important;
  background: var(--panel-2) !important;
}
.important-decision-hero > :first-child:not(div){
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #ffffff !important;
  background: #176f49 !important;
}
.important-decision-hero .crest{
  width: 50px !important;
  height: 50px !important;
  max-width: 50px !important;
  max-height: 50px !important;
}
.important-decision-hero > div{
  min-width: 0;
  display: grid;
  gap: 3px;
}
.important-decision-hero :is(.kicker,h3,p){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}
.important-decision-hero h3{ margin: 0; font-size: 1rem; line-height: 1.2; }
.important-decision-hero p{ margin: 0; color: var(--muted) !important; line-height: 1.42; }

.important-decision-facts{
  display: grid;
  grid-template-columns: 1fr;
  gap: 7px;
}
.important-decision-facts article{
  display: grid;
  grid-template-columns: 34px minmax(0,1fr);
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--text);
  background: var(--panel);
}
.important-decision-facts article > span{
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #176f49 !important;
  background: color-mix(in srgb,#176f49 11%,var(--panel-2));
}
.important-decision-facts article > div{ min-width: 0; display: grid; gap: 1px; }
.important-decision-facts small{ color: var(--muted) !important; }
.important-decision-facts strong{
  min-width: 0;
  color: var(--text) !important;
  overflow-wrap: anywhere;
}
.important-decision-facts em{ color: var(--muted) !important; font-style: normal; }

.important-decision-columns{
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}
.important-decision-columns > section{
  display: grid;
  gap: 8px;
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel-2);
}
.important-decision-columns > section > header{
  display: flex;
  align-items: center;
  gap: 7px;
}
.important-decision-columns > section > header .fa-solid{ width: 18px; text-align: center; }
.important-decision-columns > section.is-positive{ border-color: color-mix(in srgb,#176f49 35%,var(--line)); }
.important-decision-columns > section.is-positive > header{ color: #177448; }
html[data-theme="dark"] .important-decision-columns > section.is-positive > header{ color: #6ed6a1; }
.important-decision-columns > section.is-caution{ border-color: color-mix(in srgb,#b46c00 38%,var(--line)); }
.important-decision-columns > section.is-caution > header{ color: #8a5700; }
html[data-theme="dark"] .important-decision-columns > section.is-caution > header{ color: #efbd64; }
.important-decision-columns ul{ margin: 0; padding-left: 18px; display: grid; gap: 6px; }
.important-decision-columns li{ color: var(--text); line-height: 1.4; }
.important-decision-note{
  display: grid;
  grid-template-columns: 20px minmax(0,1fr);
  gap: 7px;
  margin: 0;
  padding: 9px 10px;
  border: 1px solid color-mix(in srgb,#2d75c8 28%,var(--line));
  border-radius: 11px;
  color: var(--text);
  background: color-mix(in srgb,#2d75c8 7%,var(--panel));
  line-height: 1.4;
}
.important-decision-note .fa-solid{ color: #2d75c8 !important; margin-top: 2px; }
html[data-theme="dark"] .important-decision-note .fa-solid{ color: #80b8f2 !important; }
.important-decision-actions{
  grid-template-columns: 1fr !important;
}

