  gap: 5px !important;
  overflow: hidden !important;
  white-space: nowrap !important;
}
.observer-screen .observer-header-copy > .match-header-meta > :is(b,small,span){
  display: block !important;
  min-width: 0 !important;
  max-width: 100% !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}
.observer-screen .observer-header-copy > .match-header-meta > .match-context-label{ grid-column: 1 !important; }
