  object-fit: contain !important;
  image-rendering: auto;
}
.live-pitch-shell:not(.is-pitch-disabled){
  height: auto !important;
  min-height: 0 !important;
  align-self: start !important;
}

/* Loaders representam trabalho em andamento, não animação cosmética. Por
   decisão do produto, eles giram mesmo com qualquer opção de animação/movimento
   reduzido ativa. Estados concluído/erro continuam estáticos. */
@keyframes goooool-loader-spin { to { transform: rotate(360deg); } }
:is(
  .app-task-spinner,
  .post-match-background-status:not(.is-complete) .post-match-save-spinner,
  .live-finalization-overlay:not(.is-complete):not(.is-error) .live-finalization-spinner,
  .live-preparation-spinner,
  .share-preview-loading:not([hidden]) .fa-spinner,
  #observerSkipBtn.observer-processing-button .fa-spinner,
  #liveFinishTab.is-finalizing > .fa-spinner,
  button[aria-busy="true"] > .fa-spinner,
  .btn.is-busy-stable > .fa-spinner,
  .universal-search-empty.is-loading > .fa-spinner,
  .statistics-awards-loading:not(.is-error) .statistics-awards-loading-card .post-match-save-spinner,
  .live-info-tabs > button.is-waiting .fa-solid
){
  animation: goooool-loader-spin .78s linear infinite !important;
  animation-play-state: running !important;
}
.app-task-overlay.is-indeterminate .app-task-progress > span{
  width: 34% !important;
  animation: app-task-progress 1.15s ease-in-out infinite alternate !important;
  animation-play-state: running !important;
