  flex-wrap: wrap;
}
.dashboard-country-mark{
  flex: 0 0 auto;
  font-size: .72rem;
  line-height: 1;
}
#customizeDashboardBtn.dashboard-customize-action{
  width: 34px;
  min-width: 34px;
  max-width: 34px;
  min-height: 34px;
  padding: 0 !important;
  display: inline-grid;
  place-items: center;
  border-radius: 10px;
}
#customizeDashboardBtn.dashboard-customize-action .fa-solid, #customizeDashboardBtn.dashboard-customize-action .fa-regular{
  display: inline-block !important;
  margin: 0 !important;
  font-size: .75rem;
}

.landing-v99 .landing-recent-careers{
  margin: 0;
  border-radius: 20px !important;
  overflow: hidden;
}
.landing-v99 .landing-recent-careers .save-slot-visual-list{
  display: grid;
  gap: 8px !important;
}
.landing-v99 .landing-recent-careers .save-slot-team-card{
