}
.landing-v99 .landing-recent-careers .landing-save-open, .landing-v99 .landing-recent-careers .save-slot-team-card.team-tone > .btn.compact.landing-save-open{
  color: var(--team-action-text, var(--action-text)) !important;
  -webkit-text-fill-color: currentColor !important;
  background-color: transparent !important;
  background-image: linear-gradient(180deg, var(--team-action-primary, var(--action-primary)), var(--team-action-secondary, var(--action-secondary))) !important;
  border-color: color-mix(in srgb, var(--team-action-text, var(--action-text)) 32%, transparent) !important;
}
.landing-v99 .landing-recent-careers .landing-save-open :is(i, span, .fa-solid, .fa-regular){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}

/* Superfícies independentes encontradas quadradas durante a auditoria V443. */
.award-season-card{ border-radius: 14px; }
.loan-option, .loan-active{ border-radius: 13px; }
.custom-sound-grid > label{ border-radius: 13px; overflow: hidden; }
.clone-candidate{ border-radius: 11px; }
.clone-selected-player{ border-radius: 11px; }
.clone-option-chip span{ border-radius: 999px; }
.confidence-split > div{ border-radius: 12px; }
.mode-log-list article{ border-radius: 11px; }
.post-match-loading, .post-match-summary-fallback{ border-radius: 14px; }
.free-agent-profile-hero{ border-radius: 18px; }
.player-profile-metrics > div{ border-radius: 11px; }
.post-match-background-status{ border-radius: 13px; }

/* ==========================================================
   V444 · correções do coletor de problemas
   ========================================================== */

/* Mercado: o motivo é um cartão interno real e precisa respirar dentro do
   cartão da proposta, sem encostar na borda externa. */
.market-negotiation-card > .market-fit-reason{
  margin: 0 10px 10px !important;
}

/* Papéis: check é semântico (selecionado), não deve herdar uma cor de clube
   que pode ser preta sobre superfície escura. */
.role-selected-player > i.fa-circle-check{
  color: var(--success-text, var(--success)) !important;
  filter: none !important;
}

/* Perfil do técnico sem foto: usa a superfície do próprio herói e seu
   foreground calculado, evitando sigla preta sobre clube preto. */
html[data-theme] .manager-profile-hero-modern .manager-profile-photo-modern:not(img){
  color: var(--team-gradient-text, #fff) !important;
  -webkit-text-fill-color: currentColor !important;
  background: var(--team-gradient-primary, #27364f) !important;
  border-color: var(--team-hero-border, rgba(255,255,255,.24)) !important;
  text-shadow: none !important;
}

/* Museu: o pequeno selo sobre o escudo é propositalmente invertido em relação
   ao herói, e esta regra vem depois das proteções globais de contraste. */
html[data-theme] .legacy-museum-hero .legacy-museum-emblem-mark, html[data-theme] .legacy-museum-hero .legacy-museum-emblem-mark :is(.fa-solid,.fa-regular){
  color: var(--team-gradient-primary, #27364f) !important;
  -webkit-text-fill-color: currentColor !important;
}
html[data-theme] .legacy-museum-hero .legacy-museum-emblem-mark{
  background: var(--team-gradient-text, #fff) !important;
  border-color: color-mix(in srgb, var(--team-gradient-primary, #27364f) 72%, transparent) !important;
}

/* Wiki: cartões com radius não podem tocar o limite físico da viewport. A
   V432 havia zerado este gutter; restaura-se um respiro mobile único. */
.wiki-page-book{
  padding-inline: max(10px, env(safe-area-inset-left)) max(10px, env(safe-area-inset-right)) !important;
}

/* Sliders com texto auxiliar usam duas linhas reais; descrição não fica
   colada ao rótulo nem compete com a trilha do range. */
.range-field > span{
  min-width: 0;
  font-weight: 600;
  line-height: 1.25;
}
.range-field:has(> small){
  padding-block: 8px !important;
  row-gap: 6px !important;
}
.range-field > small{
  grid-column: 1 / -1;
  display: block;
  margin: 0;
  color: var(--muted);
  font-size: .62rem;
  line-height: 1.4;
}

/* Verificação da carreira: o próprio grupo de Ajustes já é a superfície pai;
   o cabeçalho interno deixa de repetir borda/fundo de outro .panel. */
.career-audit-settings-panel .audit-hero{
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

/* Amistoso: botão de limpar é um controle icon-only completo, não o botão
   cinza padrão do navegador. */
.friendly-selected > .friendly-clear-button{
  display: grid;
  place-items: center;
  min-width: 36px !important;
  width: 36px !important;
  min-height: 36px !important;
  height: 36px !important;
  padding: 0 !important;
  border: 1px solid color-mix(in srgb, var(--danger) 36%, var(--line)) !important;
  border-radius: 11px !important;
  color: var(--danger) !important;
  background: color-mix(in srgb, var(--danger) 9%, var(--panel-2)) !important;
  box-shadow: none !important;
  cursor: pointer;
}
.friendly-selected > .friendly-clear-button :is(.fa-solid,.fa-regular){ color: inherit !important; }
.friendly-selected > .friendly-clear-button:focus-visible{
  outline: 2px solid color-mix(in srgb, var(--danger) 55%, transparent);
  outline-offset: 2px;
}

/* Encerramento de competição: o resumo inteiro ganha uma superfície discreta
   e padding; os cards internos continuam separados e legíveis. */
.competition-end-summary{
  padding: 12px !important;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 94%, var(--primary) 6%);
}

/* ==========================================================
   V478 · atualização única e varredura dos componentes móveis
   ========================================================== */

/* Central de Retorno: título e motivos agora formam uma superfície funcional,
   com os mesmos respiros, hierarquia e acabamento dos demais blocos do modal. */
.return-story-hooks{
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb,#d6ad55 34%,var(--line));
  border-radius: 16px;
  background: linear-gradient(145deg,color-mix(in srgb,#d6ad55 7%,var(--panel-2)),var(--panel-2));
}
.return-story-hooks > header{ display: grid; gap: 4px; min-width: 0; }
.return-story-hooks > header .kicker{
  width: max-content;
  max-width: 100%;
  display: inline-flex;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb,#d6ad55 42%,var(--line));
  border-radius: 999px;
  color: #d6ad55;
  background: color-mix(in srgb,#d6ad55 10%,var(--panel));
}
.return-story-hooks > header > strong{ color: var(--text); font-size: .7rem; line-height: 1.3; }
.return-story-hooks > div{ display: grid; gap: 7px; min-width: 0; }
.return-story-hooks article{
  display: grid;
  grid-template-columns: 34px minmax(0,1fr);
  align-items: start;
  gap: 9px;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--panel);
}
.return-story-hooks article > span{
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #d6ad55;
  background: color-mix(in srgb,#d6ad55 11%,var(--panel-2));
}
.return-story-hooks article > div{ min-width: 0; }
.return-story-hooks article :is(strong,small){ display: block; overflow-wrap: anywhere; }
.return-story-hooks article strong{ color: var(--text); font-size: .62rem; line-height: 1.35; }
.return-story-hooks article small{ margin-top: 2px; color: var(--muted); font-size: .54rem; line-height: 1.4; }

/* Rótulos sobre heróis temáticos nunca ficam como uma faixa retangular solta.
   A regra abrange o encerramento e os heróis equivalentes que usam teamStyle. */
:is(.competition-end-hero,.manager-profile-hero-modern,.team-profile-hero-modern,.legacy-museum-hero,.celebration-card) .kicker{
  width: max-content;
  max-width: 100%;
  display: inline-flex !important;
  align-items: center;
  padding: 4px 8px !important;
  border: 1px solid var(--team-hero-border,rgba(255,255,255,.24)) !important;
  border-radius: 999px !important;
}

/* O resumo do clube/seleção no topo recebe um par local calculado em conjunto.
   Isso evita texto claro sobre seleção clara ou texto escuro sobre seleção escura. */
.topbar-club-summary[style*="--team-gradient-text"]{
  color: var(--team-gradient-text) !important;
  background: var(--team-hero-panel) !important;
  border: 1px solid var(--team-hero-border) !important;
  box-shadow: inset 0 1px 0 var(--team-hero-decor) !important;
}
.topbar-club-summary[style*="--team-gradient-text"] :is(strong,span,small,.fa-solid,.fa-regular){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}

/* Título e explicação do guard ocupam linhas próprias. O ícone abrange as duas
   linhas e nenhum tamanho de fonte pode fazer os textos se encavalarem. */
.session-guard-summary{
  display: grid !important;
  grid-template-columns: 34px minmax(0,1fr);
  grid-template-rows: auto auto;
  align-items: start;
  column-gap: 11px;
  row-gap: 3px;
}
.session-guard-summary::before{ grid-column: 1; grid-row: 1 / 3; }
.session-guard-summary > strong{ grid-column: 2; grid-row: 1; min-width: 0; line-height: 1.3; overflow-wrap: anywhere; }
.session-guard-summary > small{ grid-column: 2; grid-row: 2; min-width: 0; margin-top: 0; overflow-wrap: anywhere; }

/* A prévia reproduz o botão real: preserva somente o anel da superfície e não
   inventa a sombra verde que não existe na barra inferior em uso. */
.nav-preview-navbar .nav-play.is-preview, html[data-theme="light"] .nav-preview-navbar .nav-play.is-preview{
  box-shadow: 0 0 0 5px var(--panel) !important;
}
html[data-theme="light"] .nav-preview-navbar .nav-play.is-preview{ box-shadow: 0 0 0 5px #fff !important; }

/* Retrospectivas usam a mesma estratégia das classificações atuais: a largura
   das colunas é preservada e o próprio bloco oferece rolagem horizontal. */
.season-history-table{
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-inline: contain;
  scrollbar-width: thin;
  -webkit-overflow-scrolling: touch;
}
.season-history-table-head, .season-history-table-row{
  min-width: 500px;
  grid-template-columns: 38px minmax(165px,1fr) repeat(4,36px) 44px 46px !important;
  grid-template-rows: auto !important;
  min-height: 36px !important;
  gap: 5px !important;
  padding: 5px 9px !important;
}
.season-history-table-head > :nth-child(n), .season-history-table-row > :nth-child(n){
  grid-column: auto !important;
  grid-row: auto !important;
  align-self: center;
}
.season-history-table-head{ font-size: .58rem; }
.season-history-table-row{ font-size: .61rem; }
/* V444 · reforço de especificidade: as regras globais do herói incluem
   <span> em :is(), por isso o selo precisa vencer explicitamente essa cascata. */
html[data-theme="light"] .legacy-museum-hero .legacy-museum-emblem > .legacy-museum-emblem-mark, html[data-theme="dark"] .legacy-museum-hero .legacy-museum-emblem > .legacy-museum-emblem-mark, html[data-theme="light"] .legacy-museum-hero .legacy-museum-emblem > .legacy-museum-emblem-mark > :is(.fa-solid,.fa-regular), html[data-theme="dark"] .legacy-museum-hero .legacy-museum-emblem > .legacy-museum-emblem-mark > :is(.fa-solid,.fa-regular){
  color: var(--team-gradient-primary, #27364f) !important;
  -webkit-text-fill-color: currentColor !important;
  text-shadow: none !important;
}
/* V444 · a proteção global de heróis tem alta especificidade por causa de
   :is(); usa as classes reais deste herói para preservar a inversão do selo. */
html[data-theme="light"] .panel.legacy-museum-hero.team-tone .legacy-museum-emblem > .legacy-museum-emblem-mark, html[data-theme="dark"] .panel.legacy-museum-hero.team-tone .legacy-museum-emblem > .legacy-museum-emblem-mark, html[data-theme="light"] .panel.legacy-museum-hero.team-tone .legacy-museum-emblem > .legacy-museum-emblem-mark > :is(.fa-solid,.fa-regular), html[data-theme="dark"] .panel.legacy-museum-hero.team-tone .legacy-museum-emblem > .legacy-museum-emblem-mark > :is(.fa-solid,.fa-regular){
  color: var(--team-gradient-primary, #27364f) !important;
  -webkit-text-fill-color: currentColor !important;
}

/* ==========================================================
   V445 · Inspetor móvel: alvo exato e toque longo sem UI nativa
   ----------------------------------------------------------
   A classe existe somente enquanto o dedo está pressionado. Assim o Chrome/
   Android não cria seleção, alças, menu contextual ou prévia de busca antes
   de o inspetor abrir; ao soltar, a seleção normal do app volta imediatamente.
   ========================================================== */
/* V447 · a proteção contra seleção fica restrita ao nó realmente tocado.
   Evita invalidar `body *` em cada toque quando o Modo Desenvolvedor está ativo. */
.dev-inspector-gesture-target{
  -webkit-user-select: none !important;
  user-select: none !important;
  -webkit-touch-callout: none !important;
}

/* ==========================================================
   V445 · ajustes do lote do Modo Desenvolvedor
   ========================================================== */

/* V514 · seleções e países não usam emojis de bandeira. */


/* O cabeçalho textual do Ao Vivo repousa sobre o fundo da própria tela. Não
   precisa de um segundo retângulo branco/cinza em nenhum tema. */
.match-screen > .match-header, .observer-screen > .match-header{
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

/* No pós-jogo, escudos, nomes e placar formam uma única composição neutra.
   As cores das equipes permanecem nos próprios escudos, não em fundos atrás
   do nome nem no miolo do placar. */
.match-screen .live-finish-pane .post-match-scoreline, .match-screen .live-finish-pane .post-match-scoreline > strong, .match-screen .live-finish-pane .post-match-scoreline .fixture-team.team-tone{
  background: transparent !important;
  box-shadow: none !important;
}
.match-screen .live-finish-pane .post-match-scoreline, .match-screen .live-finish-pane .post-match-scoreline .fixture-team.team-tone{
  border-color: transparent !important;
}
.match-screen .live-finish-pane .post-match-scoreline .fixture-team.team-tone::after{
  display: none !important;
}

/* Somente a grade larga da classificação rola horizontalmente. O título
   “Grupo / Classificação provisória” permanece fixo e alinhado ao card. */
.current-table-card .post-match-card-content{
  overflow-x: hidden !important;
}
.international-standings-scroll{
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: visible;
  overscroll-behavior-inline: contain;
  touch-action: pan-x pan-y;
  -webkit-overflow-scrolling: touch;
  border-radius: 10px;
}
.international-standings-scroll > :is(.live-table-columns,.live-table-row){
  grid-template-columns: 46px minmax(150px,1fr) 42px 42px 42px 38px 42px 42px 42px 42px 118px !important;
  min-width: 704px !important;
}
.international-standings-scroll .live-table-columns{
  position: sticky;
  top: 0;
  z-index: 2;
}


/* ==========================================================
   V446 · submenu secundário padronizado + grupos sem placa
   ----------------------------------------------------------
   A navegação da seleção é um segundo nível real de `.subtabs`:
   usa os mesmos botões `.subtab` do restante do app e participa da pilha
   sticky logo abaixo do primeiro nível. Grupos cuja única função é alinhar
   botões não desenham uma superfície extra por trás dos próprios botões.
   ========================================================== */
.national-squad-tabs{
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 4px 2px 7px !important;
  border: 1px solid var(--line) !important;
  border-radius: 14px !important;
  color: var(--text) !important;
  background: var(--panel) !important;
  box-shadow: none !important;
}
html[data-theme="light"] .national-squad-tabs{ background: #fff !important; }
.national-squad-tabs > .subtab{
  min-height: 40px;
  color: var(--muted);
}
.national-squad-tabs > .subtab.is-active{ color: var(--text); }
/* Quando o segundo nível flutua, preserve o empilhamento calculado pelo JS;
   ele recebe --sticky-menu-top igual à soma dos níveis anteriores. */
.content .national-squad-tabs.is-sticky-submenu{
  top: var(--sticky-menu-top, 0px) !important;
  z-index: var(--sticky-menu-z, 601) !important;
}

/* Um agrupador de botões não precisa de outro retângulo colorido por trás.
   Os botões continuam com suas próprias superfícies/estados. */
.quick-control-strip{
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
html[data-theme="dark"] .quick-control-strip, html[data-theme="light"] .quick-control-strip{
  background: transparent !important;
  border-color: transparent !important;
}
/* O estado registrado pelo gerenciador sticky não deve transformar o segundo
   nível em uma barra sem superfície antes de ele realmente estar preso. */
html[data-theme] .content .national-squad-tabs.is-sticky-submenu:not(.is-stuck){
  border-radius: 14px !important;
  border: 1px solid var(--line) !important;
  color: var(--text) !important;
  background: var(--panel) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
html[data-theme="light"] .content .national-squad-tabs.is-sticky-submenu:not(.is-stuck){
  background: #fff !important;
}


/* ==========================================================
   V449 · consistência de grupos, contraste e estados escolhidos
   ========================================================== */
/* Navegações que apenas agrupam botões não ganham outra superfície atrás. */
.internal-page-route-nav{
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
html[data-theme="dark"] .internal-page-route-nav, html[data-theme="light"] .internal-page-route-nav{
  background: transparent !important;
  border-color: transparent !important;
}

/* O kicker do herói tático precisa obedecer ao contraste da superfície real,
   não ao acento genérico da página que pode ficar cinza sobre cinza. */
html[data-theme="dark"] .tactic-identity-card .kicker{
  color: var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color: currentColor !important;
  opacity: 1 !important;
}
html[data-theme="light"] .tactic-identity-card .kicker{
  color: var(--text) !important;
  -webkit-text-fill-color: currentColor !important;
  opacity: 1 !important;
}

/* Padrão único para escolhas táticas: selecionado = superfície realçada + check. */
:is(.tactic-selection-action,.tactic-preset-choice,.saved-plan-apply).is-selected{
  color: var(--text) !important;
  background: color-mix(in srgb,var(--club-primary) 16%,var(--surface)) !important;
  border-color: color-mix(in srgb,var(--club-primary) 58%,var(--line)) !important;
  box-shadow: 0 6px 16px color-mix(in srgb,var(--club-primary) 13%,transparent) !important;
}
:is(.tactic-selection-action,.tactic-preset-choice,.saved-plan-apply).is-selected :is(.fa-solid,.fa-regular){
  color: var(--club-accent-text,var(--primary)) !important;
}
.tactical-abc-card.is-selected, .saved-plan-grid article.is-selected{
  border-color: color-mix(in srgb,var(--club-primary) 46%,var(--line));
}
.tactic-preset-grid .tactic-preset-choice{ position: relative; }
.tactic-selection-check{
  margin-inline-start: auto;
  display: grid !important;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  color: var(--club-accent-text,var(--primary));
  background: color-mix(in srgb,var(--club-primary) 14%,var(--surface));
  flex: 0 0 auto;
}

/* Texto introdutório de promessa não encosta na primeira opção. */
.promise-picker > p{
  margin: 0 0 12px !important;
  line-height: 1.45;
}

/* Explicação do preço do ingresso acompanha o mesmo ritmo dos controles. */
.ticket-price-explainer{
  margin: 0;
  color: var(--muted);
  font-size: .68rem;
  line-height: 1.45;
}

/* ===== V453 · cabeçalho do inspetor e contraste do Mercado =====
   O Modo Desenvolvedor adiciona um botão de minimizar ao cabeçalho padrão.
   O modal normal reserva apenas título + fechar (ou voltar + título + fechar),
   então o terceiro controle podia cair para uma segunda linha. O inspetor passa
   a declarar explicitamente as duas ações à direita sem alterar outros modais. */
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header.has-no-modal-back{
  grid-template-columns:minmax(0,1fr) 38px 38px !important;
  column-gap:8px !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header.has-modal-back{
  grid-template-columns:38px minmax(0,1fr) 38px 38px !important;
  column-gap:8px !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header :is(.modal-minimize,.modal-close,.modal-back){
  grid-row:1;
  align-self:center;
}

/* O kicker do herói do Mercado vive sobre a paleta do clube. No tema escuro,
   a regra genérica de acento de .team-tone podia vencer o texto calculado do
   gradiente e produzir cinza sobre fundo semelhante. Aqui prevalece o par de
   contraste da própria superfície temática. */
html[data-theme="light"] .market-command-hero.team-tone[style*="--team-gradient-primary"] .kicker, html[data-theme="dark"] .market-command-hero.team-tone[style*="--team-gradient-primary"] .kicker{
  color:var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color:currentColor !important;
  opacity:1 !important;
  text-shadow:none !important;
}

/* ===== V454 · inspetor compacto, header estável e reporte público mínimo =====
   O cabeçalho do inspetor deixa de adicionar uma terceira coluna à grade do
   modal. Minimizar e fechar formam um único grupo de ações, preservando a
   estrutura título + ações (ou voltar + título + ações) até 320px. */
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header.has-no-modal-back{
  grid-template-columns:minmax(0,1fr) auto !important;
  column-gap:8px !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header.has-modal-back{
  grid-template-columns:38px minmax(0,1fr) auto !important;
  column-gap:8px !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal > header{
  padding:10px 12px !important;
}
.dev-inspector-header-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:6px;
  min-width:max-content !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .dev-inspector-header-actions :is(.modal-minimize,.modal-close){
  width:36px !important;
  min-width:36px !important;
  max-width:36px !important;
  height:36px !important;
  min-height:36px !important;
  grid-row:auto !important;
}
.app-modal-overlay[data-dev-inspector-overlay="true"] .app-modal-body{
  padding:10px 12px 12px;
}

/* O acesso sem recursos avançados é propositalmente mínimo: apenas o alvo
   selecionado e a ação de reportar. Nenhum chrome técnico é renderizado. */
.dev-inspector-shell.is-report-only{
  gap:9px;
}
.dev-inspector-public-selection{
  display:grid;
  grid-template-columns:34px minmax(0,1fr);
  align-items:center;
  gap:9px;
  padding:9px 10px;
  border:1px solid var(--line);
  border-radius:12px;
  background:var(--panel-2);
  min-width:0;
}
.dev-inspector-public-selection-icon{
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:color-mix(in srgb,var(--primary) 12%,var(--panel));
  color:var(--primary);
}
.dev-inspector-public-selection > div{ display:grid; gap:2px; min-width:0; }
.dev-inspector-public-selection small{
  color:var(--muted);
  font-size:.56rem;
  font-weight:700;
  letter-spacing:.06em;
  text-transform:uppercase;
}
.dev-inspector-public-selection strong{
  color:var(--text);
  font-size:.76rem;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.dev-inspector-public-selection p{
  margin:1px 0 0;
  color:var(--muted);
  font-size:.62rem;
  line-height:1.35;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.dev-inspector-report-only{ width:100%; min-height:40px; }

/* No acesso completo o modal usa menos chrome e entrega a maior área útil à
   fila de problemas, que é a primeira aba e mantém os itens salvos visíveis. */
.dev-inspector-shell.is-full-access{ gap:8px; }
.dev-inspector-hero.is-compact{
  grid-template-columns:32px minmax(0,1fr);
  gap:8px;
  padding:7px 9px;
  border-radius:11px;
}
.dev-inspector-hero.is-compact > span{
  width:32px;
  height:32px;
  border-radius:9px;
}
.dev-inspector-hero.is-compact small{ font-size:.54rem; }
.dev-inspector-hero.is-compact strong{ font-size:.72rem; }
.dev-inspector-tabs.has-five-tabs{ gap:5px; }
.dev-inspector-tabs.has-five-tabs button{
  min-width:56px;
  min-height:34px;
  padding:6px 8px;
  font-size:.62rem;
}
.dev-inspector-tabs.has-five-tabs button[data-dev-pane="queue"]{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:4px;
}
.dev-inspector-tabs.has-five-tabs button[data-dev-pane="queue"] .badge{
  min-width:18px;
  height:18px;
  padding:0 5px;
  display:inline-grid;
  place-items:center;
  font-size:.52rem;
}
.dev-inspector-collector{
  gap:8px;
  padding:0;
  border:0;
  border-radius:0;
  background:transparent;
}
.dev-inspector-collector > header{
  padding:0 1px;
}
.dev-inspector-saved-priority{
  display:grid;
  gap:7px;
  padding:8px;
  border:1px solid var(--line);
  border-radius:11px;
  background:var(--panel-2);
  min-width:0;
}
.dev-inspector-saved-priority > header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
}
.dev-inspector-saved-priority > header > div{ display:grid; gap:1px; min-width:0; }
.dev-inspector-saved-priority > header small{
  color:var(--muted);
  font-size:.54rem;
  text-transform:uppercase;
  letter-spacing:.05em;
}
.dev-inspector-saved-priority > header strong{ color:var(--text); font-size:.66rem; }
.dev-inspector-saved-list{
  max-height:min(42vh,360px);
  overflow:auto;
  margin:0;
  padding-right:1px;
}
.dev-inspector-problem-field textarea{
  min-height:54px;
  max-height:116px;
}
.dev-inspector-collector-actions .btn{ min-height:36px; }
.dev-inspector-shell.is-full-access:not(.is-queue-pane) .dev-inspector-nav, .dev-inspector-shell.is-full-access:not(.is-queue-pane) .dev-inspector-actions{
  gap:6px;
}
.dev-inspector-shell.is-full-access:not(.is-queue-pane) .dev-inspector-nav .btn, .dev-inspector-shell.is-full-access:not(.is-queue-pane) .dev-inspector-actions .btn{
  min-height:36px;
}

/* ===== V455 · contraste, hierarquia e respiro visual ===== */
/* Próximo adversário: o kicker vive sobre o gradiente temático do próprio
   herói e deve usar o foreground já calculado para a superfície, nunca o
   acento genérico do clube que pode convergir com o fundo. */
html[data-theme="light"] .opponent-hero.team-tone[style*="--team-gradient-primary"] > div > .kicker, html[data-theme="dark"] .opponent-hero.team-tone[style*="--team-gradient-primary"] > div > .kicker{
  color:var(--team-gradient-text,#fff) !important;
  -webkit-text-fill-color:currentColor !important;
  opacity:1 !important;
  text-shadow:none !important;
}

/* Estatísticas de partidas: o contexto da competição acompanha o placar
   centralizado e não fica pendurado à esquerda da linha. */
#statisticsBody .record-match-row > small{
  width:100%;
  text-align:center;
  justify-self:stretch;
}

/* Departamento de Futebol: o divisor do toggle não pode encostar no CTA. */
.fc-community-rules > .btn[data-open-community-panel]{
  width:100%;
  margin-top:12px;
}

/* Cards de bancos: metadado, nome e descrição têm hierarquias diferentes e
   ocupam linhas próprias, mesmo quando há largura disponível. */
.fc-pack-card > div > :is(small,strong,p){
  display:block;
  width:100%;
  min-width:0;
}
.fc-pack-card > div > small{ margin-bottom:3px; }
.fc-pack-card > div > strong{
  overflow-wrap:anywhere;
  line-height:1.3;
}

/* Verificação da carreira: o grupo externo é a superfície. O layout interno
   recebe o respiro que evita conteúdo/ações encostados diretamente na borda. */
.career-audit-settings-panel .career-audit-layout{
  padding:10px !important;
}


/* ===== V456 · histórico diário das atualizações ===== */
.internal-page-body .release-daily-intro{
  margin-bottom: 10px;
}
.internal-page-body .release-day-groups{
  display: grid;
  gap: 8px;
}
.internal-page-body details.release-day{
  max-width: 100%;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel-2);
}
.internal-page-body details.release-day[open]{
  border-color: var(--page-accent-line);
}
.internal-page-body details.release-day > summary{
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0,1fr) 16px;
  align-items: center;
  gap: 8px;
  padding: 10px 11px;
  color: var(--text);
  cursor: pointer;
  list-style: none;
}
.internal-page-body details.release-day > summary::-webkit-details-marker{
  display: none;
}
.internal-page-body details.release-day > summary > div{
  min-width: 0;
  display: grid;
  gap: 2px;
}
.internal-page-body details.release-day > summary strong{
  color: var(--text);
  font-size: .66rem;
  line-height: 1.3;
}
.internal-page-body details.release-day > summary small{
  color: var(--muted);
  font-size: .53rem;
  line-height: 1.3;
}
.internal-page-body details.release-day > summary > .fa-chevron-down{
  color: var(--muted);
  transition: transform .18s ease;
}
.internal-page-body details.release-day[open] > summary > .fa-chevron-down{
  color: var(--page-accent);
  transform: rotate(180deg);
}
.internal-page-body details.release-day > .release-day-list{
  display: grid;
  gap: 7px;
  margin: 0;
  padding: 0 9px 9px;
}
.internal-page-body .release-day-version{
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.internal-page-body .release-day-version > header{
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0,1fr);
  align-items: start;
  gap: 8px;
}
.internal-page-body .release-day-version > header > span{
  min-width: 42px;
  padding: 5px 6px;
  border-radius: 8px;
  background: var(--page-accent-soft);
  color: var(--page-accent);
  font-size: .56rem;
  font-weight: 700;
  text-align: center;
}
.internal-page-body .release-day-version > header > div{
  min-width: 0;
  display: grid;
  gap: 2px;
}
.internal-page-body .release-day-version > header strong{
  color: var(--text);
  font-size: .62rem;
  line-height: 1.35;
}
.internal-page-body .release-day-version > header small{
  color: var(--muted);
  font-size: .5rem;
  line-height: 1.3;
}
.internal-page-body .release-day-version-body{
  margin-top: 7px;
  color: var(--muted);
}
.internal-page-body .release-day-version-body > :first-child{ margin-top: 0; }
.internal-page-body .release-day-version-body > :last-child{ margin-bottom: 0; }

/* V461 · Modo autônomo: extensão visual reversível do Técnico automático e controle global compacto. */
.autonomous-career-settings-panel{
  position: relative;
  overflow: hidden;
}
.autonomous-career-extension{
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.autonomous-career-extension-heading{
  display: grid;
  gap: 3px;
  margin-bottom: 9px;
}
.autonomous-career-extension-heading strong{ font-size: .76rem; color: var(--text); }
.autonomous-career-extension-heading small{ font-size: .56rem; line-height: 1.35; color: var(--muted); }
.autonomous-career-settings-panel .autonomous-career-master{
  border: 1px solid rgba(99, 198, 148, .32);
  background: rgba(42, 139, 92, .10);
  border-radius: 14px;
  padding: 12px;
}
.autonomous-career-settings-panel .autonomous-career-master:has(input:disabled){
  opacity: 1;
  background: rgba(127,127,127,.045);
  border-color: var(--line);
}
.autonomous-career-settings-panel .autonomous-career-master input:disabled{ opacity: .48; }
.autonomous-career-options{ margin-top: 10px; opacity: 1; }
.autonomous-career-options[data-automation-state="suspended"], .autonomous-career-options[data-automation-state="off"]{ opacity: .78; }
.autonomous-career-options select:disabled{ opacity: .72; cursor: not-allowed; }
.autonomous-career-options.is-enabled{ opacity: 1; }
.autonomous-career-rule{ margin-top: 10px; }
.autonomous-career-stop{ margin-top: 10px; width: 100%; }
.autonomous-career-floating{
  position: fixed;
  right: 10px;
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  z-index: 2450;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  max-width: min(72vw, 230px);
  padding: 6px 10px;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 999px;
  background: linear-gradient(135deg,#172235,#243650);
  color: #fff;
  box-shadow: 0 10px 24px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.12);
}
.autonomous-career-floating > .fa-solid{
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  flex: 0 0 27px;
  border-radius: 50%;
  background: rgba(255,255,255,.12);
}
.autonomous-career-floating span{ display: grid; min-width: 0; text-align: left; line-height: 1.05; }
.autonomous-career-floating strong{ font-size: .64rem; color: inherit; white-space: nowrap; }
.autonomous-career-floating small{ font-size: .48rem; opacity: .76; color: inherit; }

/* V464 · hierarquia única de camadas de interface.
   O inspetor de desenvolvimento precisa permanecer acima de qualquer processamento
   cooperativo; avisos/toasts ficam acima de ambos para nunca perder o feedback de
   uma ação executada dentro de um modal. */
:root{
  --ui-layer-modal: 3000;
  --ui-layer-task: 12000;
  --ui-layer-community-share: 12500;
  --ui-layer-developer: 13000;
  --ui-layer-toast: 14000;
}
.app-modal-overlay{ z-index: var(--ui-layer-modal); }
.app-task-overlay{ z-index: var(--ui-layer-task); }
.app-modal-overlay.is-community-share-modal{ z-index: var(--ui-layer-community-share) !important; }
.app-modal-overlay[data-dev-inspector-overlay="true"]{ z-index: var(--ui-layer-developer) !important; }
.toast-stack{ z-index: var(--ui-layer-toast) !important; }

/* V464 · o histórico do técnico usa o mesmo escudo real das demais telas. */
.manager-legacy-route article > span .manager-legacy-route-crest, .manager-legacy-route article > span :is(img,svg).manager-legacy-route-crest{
  width: 34px !important;
  height: 34px !important;
  max-width: 34px;
  max-height: 34px;
  object-fit: contain;
}

/* V464 · controles automáticos compactos legíveis nos dois temas. */
html[data-theme="light"] .autonomous-career-floating, html[data-theme="light"] .auto-manager-floating{
  border-color: color-mix(in srgb, var(--text) 18%, var(--line)) !important;
  background: linear-gradient(135deg, color-mix(in srgb, var(--panel) 96%, var(--primary) 4%), color-mix(in srgb, var(--panel-2) 92%, var(--primary) 8%)) !important;
  color: var(--text) !important;
  box-shadow: 0 10px 24px rgba(23, 43, 65, .15), inset 0 1px 0 rgba(255,255,255,.8) !important;
}
html[data-theme="light"] .autonomous-career-floating > .fa-solid, html[data-theme="light"] .auto-manager-floating-icon{
  background: color-mix(in srgb, var(--primary) 12%, var(--panel)) !important;
  color: var(--text) !important;
}
html[data-theme="light"] .autonomous-career-floating small, html[data-theme="light"] .auto-manager-floating-copy small{ opacity: .72; }

/* V465 · refinamentos de leitura e contraste reportados pelo Modo Desenvolvedor. */
.dashboard-leader-gap-equivalent{
  display: block;
  margin-top: 1px;
  font-size: .56rem;
  line-height: 1.15;
  font-style: normal;
  font-weight: 500;
  opacity: .72;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Ações textuais com ícone compartilham o mesmo eixo visual em toda a UI. */
.text-action{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  line-height: 1.2;
}
.text-action :is(.fa-solid,.fa-regular,.fa-brands){
  flex: 0 0 auto;
  line-height: 1;
}

/* Título e acontecimentos do Mundo do futebol não disputam a mesma linha. */
.world-pulse-strip{
  display: grid;
  align-items: stretch;
  gap: 7px;
}
.world-pulse-title{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  color: var(--text);
  font-weight: 600;
  line-height: 1.2;
}
.world-pulse-title :is(.fa-solid,.fa-regular,.fa-brands){ line-height: 1; }
.world-pulse-items{
  display: grid;
  gap: 5px;
  min-width: 0;
}
.world-pulse-items small{
  position: relative;
  display: block;
  min-width: 0;
  padding-left: 11px;
  color: var(--muted);
  font-size: .64rem;
  line-height: 1.35;
}
.world-pulse-items small::before{
  content: "";
  position: absolute;
  left: 1px;
  top: .48em;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--primary) 72%, var(--text) 28%);
}
.world-pulse-strip small + small::before{ margin-right: 0; }

/* A moldura permanece visível mesmo quando a cor do clube é branca ou preta. */
.football-stat-row i{
  height: 6px;
  box-sizing: border-box;
  border: 1px solid color-mix(in srgb, var(--text) 28%, var(--line));
  background: var(--panel-2);
}
.football-stat-row i b:first-child{ border-radius: 999px 0 0 999px; }
.football-stat-row i b:last-child{ border-radius: 0 999px 999px 0; }

/* Cards que já possuem um escudo principal podem manter o nome clicável sem duplicá-lo. */
.team-label.is-crestless{ gap: 0; }
.world-pulse-strip .world-pulse-items small::before{
  content: "";
  margin-right: 0;
}

/* V470 · convite comunitário discreto, acessível e coerente com temas/cores do clube. */
.community-share-prompt{display:grid;gap:14px}.community-share-prompt>header{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;align-items:start}.community-share-prompt>header h3{margin:2px 0 5px;font-size:clamp(20px,5vw,28px)}.community-share-prompt>header p{margin:0;color:var(--muted)}.community-share-heart{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:color-mix(in srgb,var(--club-primary,var(--accent)) 14%,var(--panel));color:var(--club-primary,var(--accent));font-size:20px}.community-share-career{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:10px 12px;border:1px solid var(--border);border-radius:13px;background:var(--surface-muted)}.community-share-career strong{font-size:14px}.community-share-career span{font-size:11px;color:var(--muted)}.community-share-copy{padding:11px 12px;border-radius:13px;background:color-mix(in srgb,var(--club-primary,var(--accent)) 7%,var(--panel));border:1px solid color-mix(in srgb,var(--club-primary,var(--accent)) 22%,var(--border))}.community-share-copy p{margin:0;white-space:pre-line;font-size:12px;color:var(--text)}.community-share-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(108px,100%),1fr));gap:8px}.community-share-grid .btn{min-width:0}.community-share-video{padding:11px 12px;border:1px solid var(--border);border-radius:13px;background:var(--surface-muted)}.community-share-video strong{display:flex;align-items:center;gap:7px}.community-share-video p{margin:4px 0 0;color:var(--muted);font-size:12px}.community-share-prompt .sticky-modal-actions{flex-wrap:wrap}.community-share-prompt .btn.ghost{background:transparent;border-color:transparent;color:var(--muted)}
.community-share-grid-compact{grid-template-columns:repeat(2,minmax(0,1fr));max-width:440px;margin-inline:auto;width:100%}

/* ==========================================================
   V480 · placar ao vivo e toast sem ação de fechar
   ========================================================== */
#liveScore.score{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0;
}
#liveScore .live-score-value, #liveScore .live-score-separator{
  display: inline-block;
  line-height: 1;
}
#liveScore .live-score-value{
  min-width: .72em;
  text-align: center;
  transform-origin: center bottom;
}
#liveScore .live-score-value.is-goal-pop{
  animation: live-score-goal-pop .22s cubic-bezier(.2,.9,.3,1.25);
}
@keyframes live-score-goal-pop {
  0% { transform: translateY(0) scale(1); }
  45% { transform: translateY(-4px) scale(1.2); }
  100% { transform: translateY(0) scale(1); }
}
/* V483 · a grade do toast acompanha apenas os elementos realmente visíveis.
   Sem contador, o X ocupa a última coluna e não deixa uma coluna fantasma à direita.
   Quando não há fechamento manual, nenhuma faixa de 32 px é reservada. */
.toast.has-manual-close{
  grid-template-columns: 24px minmax(0,1fr) 32px !important;
}
.toast.has-manual-close.has-count{
  grid-template-columns: 24px minmax(0,1fr) auto 32px !important;
}
.toast:not(.has-manual-close){
  grid-template-columns: 24px minmax(0,1fr) !important;
}
.toast:not(.has-manual-close).has-count{
  grid-template-columns: 24px minmax(0,1fr) auto !important;
}
.toast.has-manual-close .toast-close{
  grid-column: -2 / -1;
}
.toast-count{
  grid-column: 3;
}
@media (prefers-reduced-motion: reduce) {
  #liveScore .live-score-value.is-goal-pop{ animation: none !important; }
}
html[data-reduced-motion="true"] #liveScore .live-score-value.is-goal-pop{ animation: none !important; }

/* =========================================================
   V481 · respiro contextual do campo ao vivo
   =========================================================
   No Turbo com o campo desligado, a faixa do aviso mantém 36 px, mas seu
   margin-top de 12 px precisa fazer parte da linha do grid. Reservar 48 px
   evita que o aviso avance sobre a barra de comandos. */
.match-screen.is-turbo-live.is-live-pitch-disabled:not(.is-post-match-view) > .pitch-score{
  grid-template-rows: 54px 48px auto !important;
}


/* =========================================================
   V482 · Turbo compacto e destaque robusto do inspetor
   ========================================================= */
/* V483 · Turbo sem campo não precisa de respiro adicional: a faixa de 36 px
   já é uma linha própria abaixo do placar. Campo visível continua herdando os
   12 px contextuais; sem campo e sem Turbo permanece em 0 px. */
.match-screen.is-turbo-live.is-live-pitch-disabled .live-pitch-shell{
  margin-top: 0;
}
.match-screen.is-turbo-live.is-live-pitch-disabled:not(.is-post-match-view) > .pitch-score{
  grid-template-rows: 54px 36px auto !important;
}

/* Destaque fora da árvore visual do alvo: não é recortado por overflow:hidden. */
.dev-inspector-target-outline{
  position: fixed;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  box-sizing: border-box;
  pointer-events: none;
  z-index: calc(var(--ui-layer-developer, 13000) - 1);
  border: 3px solid var(--dev-inspector-accent, #7bdcff);
  border-radius: 8px;
  box-shadow: 0 0 0 2px rgba(0,0,0,.42), 0 0 14px rgba(123,220,255,.42);
}
.dev-inspector-target-outline.is-minimized{
  border-style: dashed;
}
@media (prefers-reduced-motion: no-preference) {
  .dev-inspector-target-outline:not(.is-minimized){ animation: dev-inspector-overlay-pulse .72s ease-in-out 2; }
}
@keyframes dev-inspector-overlay-pulse {
  0%,100% { opacity: 1; }
  50% { opacity: .58; }
}

/* =========================================================
   V488 · aviso único dos modos automáticos
   O mesmo componente compacto identifica Modo autônomo e Técnico automático
   sem variar de altura durante a contagem 3–2–1.
   ========================================================= */
.automation-mini-notice{
  min-height: 40px !important;
  max-width: min(82vw, 244px) !important;
  padding: 0 !important;
  gap: 0 !important;
  border-radius: 999px !important;
  align-items: center !important;
}
.auto-manager-floating.automation-mini-notice{
  display: grid !important;
  grid-template-columns: 27px minmax(0,1fr) auto;
}
.auto-manager-floating.automation-mini-notice .auto-manager-floating-copy{
  min-width: 0;
}
.auto-manager-floating.automation-mini-notice .auto-manager-floating-copy strong{
  font-size: .62rem;
}
.auto-manager-floating.automation-mini-notice .auto-manager-floating-copy small{
  font-size: .47rem;
  line-height: 1.15;
}
.auto-manager-floating.automation-mini-notice .auto-manager-floating-countdown{
  width: 27px;
  height: 27px;
  min-width: 27px;
  display: grid;
  place-items: center;
  font-size: .7rem;
}
.auto-manager-floating.automation-mini-notice .auto-manager-floating-countdown[hidden]{
  display: grid !important;
  visibility: hidden;
  opacity: 0;
}
.autonomous-career-floating.automation-mini-notice{
  display: grid;
  grid-template-columns: 27px minmax(0,1fr);
}
@media (prefers-reduced-motion: reduce) {
  .automation-mini-notice{ transition: none !important; animation: none !important; }
}

/* ==========================================================
   V491 · correções do Modo Desenvolvedor (11/09/2026)
   ========================================================== */

/* 1 · Seleção no topo: o par de cores calculado pelo teamStyle é aplicado
   também ao fundo visível do botão. A bandeira ganha uma coluna própria. */
html.national-duty-active .topbar-club-summary[style*="--team-gradient-text"]{
  grid-template-columns: 31px minmax(0,1fr) !important;
  column-gap: 11px !important;
  padding-inline: 5px 8px !important;
  color: var(--team-gradient-text) !important;
  background: var(--team-palette-gradient,linear-gradient(135deg,var(--team-gradient-primary),var(--team-gradient-secondary))) !important;
  border-color: color-mix(in srgb,var(--team-gradient-text) 28%,transparent) !important;
}
html.national-duty-active .topbar-club-summary[style*="--team-gradient-text"] :is(strong,span,small,.topbar-compact-meta){
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}
html.national-duty-active .topbar-club-summary .topbar-club-visual{ margin-right: 1px !important; }

/* 3 · Atalhos dentro de textos explicativos continuam parecendo parte da frase,
   mas comunicam claramente que são acionáveis por toque/teclado. */
.inline-navigation-link{
  display: inline;
  margin: 0;
  padding: 0;
  border: 0;
  color: var(--primary);
  background: transparent;
  font: inherit;
  font-weight: 700;
  line-height: inherit;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
  cursor: pointer;
}
.inline-navigation-link:is(:hover,:focus-visible){ color: var(--text); }
.inline-navigation-link:focus-visible{ outline: 2px solid var(--primary); outline-offset: 3px; border-radius: 3px; }

/* 6 · O Giro pelo Mundo é um resumo composto: cada acontecimento ocupa uma
   linha própria em vez de formar um bloco contínuo de leitura difícil. */
.news-item.is-world-digest{ align-items: start; }
.news-item.is-world-digest p{ display: grid; gap: 5px; margin-top: 6px; }
.news-item.is-world-digest p > span{ display: block; min-width: 0; line-height: 1.45; overflow-wrap: anywhere; }
.news-item.is-world-digest p > span + span{ padding-top: 5px; border-top: 1px solid color-mix(in srgb,var(--line) 72%,transparent); }
.news-item.is-world-digest time{ white-space: nowrap; }

/* 7/12/13/15 · Quando a superfície tem largura para leitura, o rótulo de
   posição usa o nome em vez de expor apenas a sigla interna. */
.position-abbr.is-expanded{
  min-width: 0;
  max-width: 100%;
  padding-inline: 7px;
  text-transform: none;
  letter-spacing: 0;
  cursor: help;
}

/* 9 · Ícone de busca alinhado pelo centro real do input, independente da
   altura/font-size. O SVG é coberto também para componentes equivalentes. */
.national-squad-search > :is(i,svg){
  top: 50% !important;
  bottom: auto !important;
  transform: translateY(-50%);
  line-height: 1;
}

/* 17 · Summary específico que ainda parecia texto simples. Help-details e
   demais disclosure reutilizáveis já possuem affordance equivalente. */
.manager-reputation-history{ border-top: 0; padding-top: 0; }
.manager-reputation-history > summary{
  list-style: none;
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--text);
  background: var(--panel-2);
  font-size: .62rem;
  font-weight: 700;
  cursor: pointer;
}
.manager-reputation-history > summary::-webkit-details-marker{ display: none; }
.manager-reputation-history > summary::after{
  content: "+";
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  flex: 0 0 22px;
  border-radius: 999px;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 11%,transparent);
  font-size: .9rem;
}
.manager-reputation-history[open] > summary::after{ content: "−"; }
.manager-reputation-history > summary:is(:hover,:focus-visible){ border-color: color-mix(in srgb,var(--primary) 42%,var(--line)); }

/* 18 · A prévia da barra deve espelhar a geometria atualmente usada pela barra
   real. Regras históricas que elevavam o botão Jogar não vazam para previews. */
.nav-preview-navbar .nav-btn.is-preview{
  align-self: end !important;
  margin: 0 !important;
  inset: auto !important;
  transform: none !important;
}
.nav-preview-navbar .nav-play.is-preview{
  width: 58px !important;
  min-width: 58px !important;
  height: 58px !important;
  min-height: 58px !important;
  margin: 0 auto !important;
  inset: auto !important;
  transform: none !important;
  align-self: end !important;
  justify-self: center !important;
  grid-template-rows: 31px auto !important;
  border: 3px solid var(--panel) !important;
  border-radius: 50% !important;
  color: var(--play-cta-text,#fff) !important;
  background: radial-gradient(circle at 34% 24%,#48dc7d 0 8%,var(--play-cta-start,#22c55e) 34%,var(--play-cta-end,#15803d) 100%) !important;
  box-shadow: 0 8px 18px var(--play-cta-shadow,rgba(21,128,61,.28)),inset 0 1px 0 rgba(255,255,255,.32) !important;
}
html[data-theme="light"] .nav-preview-navbar .nav-play.is-preview{ border-color: #fff !important; }

/* 19 · As páginas públicas internas mantêm o mesmo gutter das demais telas do
   jogo; box-sizing impede o padding de aumentar a largura do viewport. */
.internal-public-page{
  box-sizing: border-box;
  width: 100%;
  padding-inline: 12px !important;
  padding-bottom: max(20px,env(safe-area-inset-bottom)) !important;
}
@media (max-width: 420px) {
  .internal-public-page{ padding-inline: 10px !important; }
}

