/* ==========================================================
   V493 · Central de notícias reconstruída e confrontos com vs
   ========================================================== */

/* A Central de notícias tem rolagem própria: a regra mobile que abre
   .bounded-scroll não transforma novamente o painel em uma coluna de milhares
   de pixels. Os cards seguem as superfícies, bordas e tipografia do tema atual. */
.news-center{
  min-width: 0;
  overflow: hidden;
}
.news-center-header{
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.news-center-title{
  display: grid;
  grid-template-columns: 38px minmax(0,1fr);
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.news-center-icon{
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb,var(--primary) 28%,var(--line));
  border-radius: 12px;
  color: var(--primary);
  background: color-mix(in srgb,var(--primary) 10%,var(--panel-2));
  font-size: .95rem;
}
.news-center-title .kicker{ margin-bottom: 1px; }
.news-center-title .panel-title{ margin: 0; line-height: 1.12; }
.news-center-title p{
  margin: 3px 0 0;
  color: var(--muted);
  font-size: .62rem;
  line-height: 1.35;
}
.news-center-count{
  min-width: 48px;
  display: grid;
  place-items: center;
  padding: 6px 7px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: color-mix(in srgb,var(--panel-2) 92%,transparent);
}
.news-center-count strong{ font-size: .82rem; line-height: 1; }
.news-center-count small{ margin-top: 3px; color: var(--muted); font-size: .48rem; line-height: 1; }

.news-center-feed{
  display: grid;
  gap: 7px;
  min-height: 0;
  max-height: min(58dvh, 480px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 1px 3px 3px 1px;
  scroll-padding-block: 4px;
}
.news-card{
  --news-accent: var(--info);
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0,1fr);
  align-items: start;
  gap: 9px;
  padding: 9px 10px 9px 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb,var(--panel-2) 94%,transparent);
  box-shadow: inset 3px 0 0 color-mix(in srgb,var(--news-accent) 76%,transparent);
}
.news-card.is-transfers{ --news-accent: var(--primary); }
.news-card.is-managers{ --news-accent: var(--info); }
.news-card.is-injuries{ --news-accent: var(--danger); }
.news-card.is-youth{ --news-accent: var(--success); }
.news-card.is-competitions{ --news-accent: var(--warning); }
.news-card.is-world{ --news-accent: var(--primary); }
.news-card-icon{
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: var(--news-accent);
  background: color-mix(in srgb,var(--news-accent) 11%,var(--panel));
  font-size: .72rem;
}
.news-card-copy{ min-width: 0; }
.news-card-meta{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  margin-bottom: 4px;
}
.news-card .news-category{
  min-width: 0;
  margin: 0;
  color: var(--news-accent);
  font-size: .5rem;
  line-height: 1.15;
  letter-spacing: .065em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.news-card time{
  flex: 0 0 auto;
  color: var(--muted);
  font-size: .52rem;
  line-height: 1.15;
  white-space: nowrap;
}
.news-card-title{
  display: block;
  min-width: 0;
  color: var(--text);
  font-size: .75rem;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.news-card p{
  margin: 3px 0 0;
  color: var(--muted);
  font-size: .64rem;
  line-height: 1.43;
  overflow-wrap: anywhere;
}
.news-card.is-world-digest p{
  display: grid;
  gap: 5px;
  margin-top: 4px;
}
.news-card.is-world-digest p > span{
  display: block;
  min-width: 0;
  line-height: 1.43;
  overflow-wrap: anywhere;
}
.news-card.is-world-digest p > span + span{
  padding-top: 5px;
