.news-center-footer > span > :is(i,svg){ flex: 0 0 auto; color: var(--primary); }
.news-center-footer small{ font-size: .56rem; line-height: 1.3; }
.news-center-footer .text-action{ flex: 0 0 auto; }

@media (max-width: 350px) {
  .news-center-title{ grid-template-columns: 34px minmax(0,1fr); gap: 7px; }
  .news-center-icon{ width: 34px; height: 34px; border-radius: 10px; }
  .news-center-title p{ display: none; }
  .news-center-count{ min-width: 43px; padding-inline: 5px; }
  .news-card{ grid-template-columns: 29px minmax(0,1fr); gap: 7px; padding-inline: 7px; }
  .news-card-icon{ width: 28px; height: 28px; }
  .news-center-footer small{ display: none; }
}

/* V494 · A aba Tabela da partida mostra o adversário da rodada sem alterar as demais classificações. */
.match-screen .live-standings-table > .live-match-table-columns, .match-screen .live-standings-table > .live-match-table-row{
