/* =========================================================
   V507 · instalação guiada + diagnóstico de sincronização
   ========================================================= */
.install-game-modal{ display:grid; gap:14px; }
.install-game-hero{ display:grid; grid-template-columns:58px minmax(0,1fr); gap:14px; align-items:center; padding:16px; border:1px solid var(--line); border-radius:18px; background:linear-gradient(135deg,color-mix(in srgb,var(--play-cta-bg,#167a4d) 12%,var(--panel)),var(--panel)); }
.install-game-mark{ display:grid; place-items:center; width:58px; height:58px; border-radius:18px; background:var(--play-cta-bg,#167a4d); color:var(--play-cta-text,#fff); font-size:1.45rem; overflow:hidden; }
.install-game-mark svg{ width:34px; height:34px; }
.install-game-hero small{ color:var(--muted); font-weight:700; text-transform:uppercase; letter-spacing:.08em; }
.install-game-hero h3{ margin:2px 0 4px; font-size:1.08rem; }
.install-game-hero p{ margin:0; color:var(--muted); line-height:1.5; font-size:.78rem; }
.install-game-benefits{ display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
.install-game-benefits > span{ display:grid; grid-template-columns:auto minmax(0,1fr); gap:3px 9px; align-items:center; padding:12px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); }
.install-game-benefits > span > i, .install-game-benefits > span > svg{ grid-row:1 / span 2; color:var(--play-cta-bg,#167a4d); }
.install-game-benefits strong{ font-size:.78rem; }
.install-game-benefits small{ color:var(--muted); line-height:1.35; font-size:.66rem; }
.install-ios-steps{ padding:13px 14px; border:1px solid color-mix(in srgb,var(--play-cta-bg,#167a4d) 30%,var(--line)); border-radius:14px; background:color-mix(in srgb,var(--play-cta-bg,#167a4d) 7%,var(--panel)); }
.install-ios-steps ol{ margin:8px 0 0 20px; padding:0; display:grid; gap:6px; color:var(--muted); font-size:.76rem; line-height:1.45; }
.install-game-modal .install-app-cta{ background:var(--play-cta-bg,#167a4d) !important; color:var(--play-cta-text,#fff) !important; border-color:var(--play-cta-border,var(--play-cta-bg,#167a4d)) !important; }
.telemetry-diagnostic-card{ display:grid; gap:10px; padding:13px; border:1px solid var(--line); border-radius:14px; background:var(--panel-2); }
.telemetry-diagnostic-card > div{ display:grid; grid-template-columns:38px minmax(0,1fr); gap:10px; align-items:start; }
.telemetry-diagnostic-card > div > span{ display:grid; place-items:center; width:38px; height:38px; border-radius:11px; background:color-mix(in srgb,var(--primary) 12%,var(--panel)); color:var(--primary); }
.telemetry-diagnostic-card small, .telemetry-diagnostic-card p{ color:var(--muted); }
.telemetry-diagnostic-card p{ margin:3px 0 0; font-size:.68rem; line-height:1.45; }
@media (max-width:560px){ .install-game-benefits{grid-template-columns:1fr}.install-game-hero{grid-template-columns:48px minmax(0,1fr);padding:13px}.install-game-mark{width:48px;height:48px;border-radius:15px} }

/* V508 · taças personalizadas de ligas/copas. */
