/* ===== V509 · competições claras e descoberta antes da carreira ===== */
.competition-club-status {
  display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:10px;
  margin:12px 0; padding:12px 13px; border:1px solid var(--line); border-radius:14px;
  background:color-mix(in srgb,var(--panel-2) 88%,transparent);
}
.competition-club-status-icon {
  display:grid; place-items:center; width:36px; height:36px; border-radius:50%;
  background:color-mix(in srgb,currentColor 14%,transparent); font-size:1rem;
}
.competition-club-status > div { min-width:0; }
.competition-club-status strong { display:block; font-size:.76rem; letter-spacing:.035em; line-height:1.2; }
.competition-club-status p { margin-top:3px; font-size:.67rem; line-height:1.35; color:inherit; opacity:.9; }
/* V510 · estados semânticos nunca herdam a cor do clube. */
.competition-club-status.is-active {
  color:var(--success,#32d17d); border-color:color-mix(in srgb,var(--success,#32d17d) 58%,var(--line));
  background:color-mix(in srgb,var(--success,#32d17d) 11%,var(--panel-2));
  box-shadow:inset 4px 0 0 var(--success,#32d17d);
}
.competition-club-status.is-out {
  color:var(--danger,#ff5c70); border-color:color-mix(in srgb,var(--danger,#ff5c70) 58%,var(--line));
  background:color-mix(in srgb,var(--danger,#ff5c70) 10%,var(--panel-2));
  box-shadow:inset 4px 0 0 var(--danger,#ff5c70);
}
.competition-club-status.is-eliminated {
  color:var(--warning,#ffbf47); border-color:color-mix(in srgb,var(--warning,#ffbf47) 58%,var(--line));
  background:color-mix(in srgb,var(--warning,#ffbf47) 10%,var(--panel-2));
  box-shadow:inset 4px 0 0 var(--warning,#ffbf47);
}
.competition-club-status.is-champion {
  color:#f2c85b; border-color:color-mix(in srgb,#f2c85b 62%,var(--line));
  background:linear-gradient(135deg,color-mix(in srgb,#f2c85b 13%,var(--panel-2)),color-mix(in srgb,#f2c85b 5%,var(--panel-2)));
  box-shadow:inset 4px 0 0 #f2c85b;
}
.competition-club-status.is-runner-up {
  color:var(--info,#62a8ff); border-color:color-mix(in srgb,var(--info,#62a8ff) 54%,var(--line));
  background:color-mix(in srgb,var(--info,#62a8ff) 9%,var(--panel-2));
  box-shadow:inset 4px 0 0 var(--info,#62a8ff);
}
.cup-champion-note { color:var(--muted); font-size:.68rem; line-height:1.4; }

.setup-team-competitions {
  display:grid; gap:8px; margin-top:10px; padding:10px; border:1px solid var(--line); border-radius:15px;
  background:color-mix(in srgb,var(--panel-2) 70%,transparent);
}
.setup-team-competitions > header { display:flex; align-items:end; justify-content:space-between; gap:10px; }
.setup-team-competitions > header > div { display:grid; gap:1px; min-width:0; }
.setup-team-competitions > header small { color:var(--primary); font-size:.56rem; font-weight:700; letter-spacing:.1em; }
.setup-team-competitions > header strong { font-size:.78rem; }
.setup-team-competitions > header > span { color:var(--muted); font-size:.58rem; white-space:nowrap; }
.setup-team-competition-list { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:7px; }
.setup-competition-chip {
  display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:8px; min-width:0;
  padding:8px; border:1px solid var(--line); border-radius:12px; background:var(--panel);
}
.setup-competition-chip > span:last-child { display:grid; min-width:0; gap:1px; }
.setup-competition-chip small { font-size:.49rem; font-weight:700; letter-spacing:.055em; }
.setup-competition-chip strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:.67rem; }
.setup-competition-chip em { color:var(--muted); font-size:.56rem; font-style:normal; line-height:1.25; }
.setup-competition-chip.is-confirmed { border-color:color-mix(in srgb,var(--success,#32d17d) 48%,var(--line)); background:color-mix(in srgb,var(--success,#32d17d) 8%,var(--panel)); }
.setup-competition-chip.is-confirmed small { color:var(--success,#32d17d); }
.setup-competition-chip.is-possible { border-style:dashed; border-color:color-mix(in srgb,var(--warning) 45%,var(--line)); }
.setup-competition-chip.is-possible small { color:var(--warning); }
.setup-competition-trophy { display:grid; place-items:center; width:34px; height:38px; flex:0 0 34px; min-width:0; min-height:0; overflow:hidden; contain:paint; color:var(--warning); }
.setup-competition-trophy img { display:block; width:auto; height:auto; max-width:100%; max-height:100%; min-width:0; min-height:0; object-fit:contain; object-position:center; overflow:hidden; }
.setup-competition-trophy.is-fallback { font-size:1rem; }
.setup-team-competition-future { border-top:1px solid var(--line); padding-top:7px; }
.setup-team-competition-future summary { cursor:pointer; color:var(--muted); font-size:.61rem; font-weight:700; }
.setup-team-competition-future[open] summary { margin-bottom:7px; }
@media (max-width:430px) {
  .setup-team-competition-list { grid-template-columns:1fr; }
  .competition-club-status { padding:10px; }
}

