  min-width:0 !important;
  min-height:0 !important;
  max-width:100% !important;
  max-height:100% !important;
  object-fit:contain !important;
  object-position:center !important;
  aspect-ratio:auto !important;
  border:0 !important;
  border-radius:0 !important;
  background:transparent !important;
  box-shadow:none !important;
}
.match-header-trophy{overflow:visible !important;}
.match-header-trophy > img{filter:drop-shadow(0 2px 3px rgba(0,0,0,.24));}

/* Encerramento de competição: escudo e taça são identidades independentes.
   A taça deixa de ser um selo sobreposto ao escudo e ganha destaque próprio. */
