.competition-champion-showcase :is(.competition-end-trophy,.celebration-competition-trophy),.celebration-champion-showcase :is(.competition-end-trophy,.celebration-competition-trophy){border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;overflow:visible!important}
.competition-champion-showcase :is(.competition-end-trophy,.celebration-competition-trophy)>img,.celebration-champion-showcase :is(.competition-end-trophy,.celebration-competition-trophy)>img{display:block!important;width:100%!important;height:100%!important;object-fit:contain!important;object-position:center!important;filter:drop-shadow(0 10px 14px rgba(0,0,0,.30))}
.competition-champion-club-stage .crest,.celebration-club-stage .crest{width:76px!important;height:76px!important;max-width:76px!important;max-height:76px!important}
.competition-end-summary.is-champion .competition-end-hero{padding-top:16px}.celebration-card:not(.is-placement) .placement-rank.is-title{margin-top:1px}
@media(max-width:430px){.competition-champion-showcase,.celebration-champion-showcase{gap:12px}.competition-champion-trophy-stage,.celebration-trophy-stage{flex-basis:106px;min-height:116px}.competition-champion-club-stage,.celebration-club-stage{flex-basis:98px;min-height:104px}.competition-champion-trophy-stage .competition-end-trophy{width:min(94px,27vw)!important;height:min(116px,33vw)!important}.celebration-trophy-stage .celebration-competition-trophy{width:min(100px,28vw)!important;height:min(120px,34vw)!important}.competition-champion-club-stage .crest,.celebration-club-stage .crest{width:66px!important;height:66px!important;max-width:66px!important;max-height:66px!important}}

/* V546 · automação global e carregamento cooperativo compacto. */
.app-task-overlay.is-compact{
  align-items:flex-end;
  justify-content:center;
  padding:0 12px calc(76px + env(safe-area-inset-bottom));
  background:linear-gradient(180deg,transparent 0%,transparent 62%,rgba(3,9,6,.16) 100%);
  pointer-events:auto;
}
.app-task-overlay.is-compact .app-task-card{
  width:min(520px,calc(100vw - 24px));
  padding:10px 12px;
  border-radius:14px;
  box-shadow:0 12px 34px rgba(0,0,0,.24);
}
.app-task-overlay.is-compact .app-task-card > header{gap:9px}
.app-task-overlay.is-compact .app-task-spinner{width:20px;height:20px}
.app-task-overlay.is-compact .app-task-tip{display:none}
.app-task-overlay.is-compact .app-task-progress{margin-top:8px}

.automation-global-control{
  position:fixed;
  z-index:var(--ui-layer-floating,78);
  right:max(0px,env(safe-area-inset-right));
  top:48%;
  display:flex;
  align-items:center;
  flex-direction:row-reverse;
  color:#fff;
  pointer-events:none;
}
.automation-global-tab,
.automation-global-panel{pointer-events:auto}
.automation-global-tab{
  position:relative;
  width:38px;
  min-width:38px;
  height:54px;
  display:grid;
  place-items:center;
  padding:0;
  border:1px solid color-mix(in srgb,var(--primary) 58%,rgba(255,255,255,.2));
  border-right:0;
  border-radius:14px 0 0 14px;
  background:linear-gradient(160deg,color-mix(in srgb,var(--primary) 82%,#13221a),#15251d);
  color:#fff;
  box-shadow:0 12px 28px rgba(0,0,0,.25);
  cursor:pointer;
  font:inherit;
}
.automation-global-tab .fa-solid{font-size:.95rem}
.automation-global-panel{
  width:min(238px,calc(100vw - 54px));
  min-height:72px;
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
  padding:10px 10px 10px 12px;
  border:1px solid color-mix(in srgb,var(--primary) 42%,var(--line));
  border-right:0;
  border-radius:14px 0 0 14px;
  background:color-mix(in srgb,var(--panel) 94%,#07120d);
  color:var(--text);
  box-shadow:0 14px 34px rgba(0,0,0,.28);
}
.automation-global-panel[hidden]{display:none!important}
.automation-global-copy{min-width:0;display:grid;gap:2px}
.automation-global-copy strong{font-size:.68rem;line-height:1.15}
.automation-global-copy small{color:var(--muted);font-size:.54rem;line-height:1.3;overflow-wrap:anywhere}
.automation-global-disable{
  min-height:34px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  padding:7px 9px;
  border:1px solid color-mix(in srgb,#ef5e6e 55%,var(--line));
  border-radius:9px;
  background:color-mix(in srgb,#a9283a 86%,var(--panel));
  color:#fff;
  font:600 .58rem/1 system-ui,sans-serif;
  cursor:pointer;
}
.automation-global-control.is-open .automation-global-tab{border-radius:0;border-left-color:transparent}
.automation-global-control.is-counting .automation-global-tab{background:linear-gradient(160deg,#a9283a,#6f1b2a)}
.automation-global-control .auto-manager-floating-countdown{
  position:absolute;
  top:-6px;
  left:-6px;
  min-width:20px;
  height:20px;
  display:grid;
  place-items:center;
  padding:0 4px;
  border-radius:999px;
  background:#fff;
  color:#8f1f2f;
  box-shadow:0 4px 12px rgba(0,0,0,.25);
  font-size:.58rem;
  font-weight:700;
}
.automation-global-control .auto-manager-floating-countdown[hidden]{display:none!important}

/* V548 · o controle global encosta na borda e abre como uma peça única.
   Neutraliza apenas o padding/gap herdados do aviso legado e mantém aba e painel
   com exatamente a mesma altura visual. */
.automation-global-control.automation-mini-notice{
  --automation-control-height:54px;
  min-height:0!important;
  max-width:none!important;
  padding:0!important;
  gap:0!important;
  border-radius:0!important;
}
.automation-global-control .automation-global-tab,
.automation-global-control .automation-global-panel{
  --automation-control-border:color-mix(in srgb,var(--primary) 46%,var(--line));
  height:var(--automation-control-height)!important;
  min-height:var(--automation-control-height)!important;
  box-sizing:border-box;
  border-color:var(--automation-control-border);
}
.automation-global-control .automation-global-panel{
  padding:6px 8px 6px 10px;
  gap:8px;
}
.automation-global-control.is-open .automation-global-tab{
  border-left-color:transparent;
  box-shadow:none;
}
@media(max-width:520px){
  .automation-global-control.automation-mini-notice{--automation-control-height:50px}
  .automation-global-tab{width:36px;min-width:36px}
  .automation-global-panel{width:min(220px,calc(100vw - 48px));padding:5px 7px 5px 9px}
}

/* V546 · em telas pequenas, taça e clube não disputam a mesma linha. */
@media(max-width:600px){
  .competition-champion-showcase,
  .celebration-champion-showcase{
    display:grid!important;
    grid-template-columns:1fr!important;
    justify-items:center;
    gap:8px!important;
    margin:0 auto 10px!important;
  }
  .competition-champion-trophy-stage,
  .celebration-trophy-stage,
  .competition-champion-club-stage,
  .celebration-club-stage{
    width:100%;
    min-height:0!important;
    flex:none!important;
  }
  .competition-champion-trophy-stage,
  .celebration-trophy-stage{order:0;gap:3px!important}
  .competition-champion-club-stage,
  .celebration-club-stage{order:1;gap:4px!important}
  .competition-champion-trophy-stage .competition-end-trophy,
  .celebration-trophy-stage .celebration-competition-trophy{
    width:min(104px,30vw)!important;
    height:min(112px,32vw)!important;
  }
  .competition-champion-club-stage .crest,
  .celebration-club-stage .crest{
    width:62px!important;
    height:62px!important;
    max-width:62px!important;
    max-height:62px!important;
  }
  .competition-champion-club-stage>strong,
  .celebration-club-stage>strong{max-width:260px;font-size:.7rem}
}

/* ==========================================================
   V547 · Criar clube com IA
   Fluxo local e sem API: o jogo gera o prompt, valida o JSON e somente depois
   cria entidades personalizadas dentro do save. Nenhum card desta área depende
   de largura desktop para funcionar.
   ========================================================== */
.ai-club-builder{
  display:grid;
  gap:14px;
  text-align:left;
}
.ai-club-intro{
  margin:0;
  color:var(--muted);
  line-height:1.55;
}
.ai-club-step{
  display:grid;
  gap:11px;
  min-width:0;
  padding:14px;
  border:1px solid var(--line);
  border-radius:16px;
  background:color-mix(in srgb,var(--panel-2) 84%,transparent);
}
.ai-club-step > header{
  display:flex;
  align-items:center;
  gap:10px;
}
.ai-club-step > header > span{
  width:30px;
  height:30px;
  flex:0 0 30px;
  display:grid;
  place-items:center;
  border-radius:999px;
  background:var(--primary);
  color:var(--on-primary);
  font-size:.76rem;
  font-weight:700;
}
.ai-club-step > header > div{min-width:0;display:grid;gap:1px;}
.ai-club-step > header small{
  color:var(--muted);
  font-size:.62rem;
  font-weight:700;
  letter-spacing:.06em;
}
.ai-club-step > header strong{font-size:.93rem;line-height:1.25;}
.ai-club-step label{display:grid;gap:7px;color:var(--muted);font-size:.72rem;font-weight:650;}
.ai-club-step textarea,
.ai-club-step input{
  width:100%;
  min-width:0;
  border:1px solid var(--line);
  border-radius:12px;
  background:var(--input-bg,var(--panel));
  color:var(--text);
  font:inherit;
  font-weight:500;
}
.ai-club-step textarea{resize:vertical;min-height:104px;line-height:1.45;}
#aiClubPrompt,#aiClubJson{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.72rem;}
.ai-club-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px;}
.ai-club-actions > small{flex:1 1 170px;color:var(--muted);line-height:1.4;}
.ai-club-actions.final{justify-content:space-between;}
.ai-club-status:empty{display:none;}
.ai-club-status{
  padding:9px 11px;
  border-radius:11px;
  background:var(--panel);
  color:var(--muted);
  font-size:.72rem;
  line-height:1.4;
}
.ai-club-status.is-success{background:color-mix(in srgb,var(--success,#22a06b) 12%,var(--panel));color:var(--text);}
.ai-club-status.is-warning{background:color-mix(in srgb,#d69e2e 14%,var(--panel));color:var(--text);}
.ai-club-status.is-error{background:color-mix(in srgb,var(--danger,#dc3545) 12%,var(--panel));color:var(--text);}
.ai-club-preview-card{
  display:grid;
  gap:12px;
  min-width:0;
  padding:14px;
  border:1px solid color-mix(in srgb,var(--team-primary,var(--primary)) 28%,var(--line));
  border-radius:16px;
  background:linear-gradient(145deg,color-mix(in srgb,var(--team-primary,var(--primary)) 9%,var(--panel)),var(--panel));
}
.ai-club-preview-colors{display:flex;height:7px;border-radius:999px;overflow:hidden;background:var(--panel-2);}
.ai-club-preview-colors i{flex:1;display:block;}
.ai-club-preview-copy{display:grid;gap:3px;min-width:0;}
.ai-club-preview-copy small{color:var(--muted);font-size:.62rem;font-weight:700;letter-spacing:.06em;}
.ai-club-preview-copy strong{font-size:1.16rem;line-height:1.2;overflow-wrap:anywhere;}
.ai-club-preview-copy span{color:var(--muted);font-size:.76rem;line-height:1.4;}
.ai-club-preview-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;}
.ai-club-preview-stats > span{display:grid;gap:1px;padding:9px;border-radius:11px;background:var(--panel-2);}
.ai-club-preview-stats b{font-size:1rem;}
.ai-club-preview-stats small{color:var(--muted);font-size:.64rem;}
.ai-club-preview-card > p{margin:0;color:var(--muted);font-size:.72rem;line-height:1.4;}
.ai-club-preview-warnings{display:grid;gap:6px;}
.ai-club-preview-warnings > span{display:flex;align-items:flex-start;gap:7px;padding:8px 9px;border-radius:10px;background:color-mix(in srgb,#d69e2e 12%,var(--panel));font-size:.7rem;line-height:1.4;}
@media (min-width:560px){
  .ai-club-preview-stats{grid-template-columns:repeat(4,minmax(0,1fr));}
}

/* ===== V547 · prévia de elenco antes da carreira ===== */
.landing-v99 .team-card-entry{
  position:relative;
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:stretch;
  gap:6px;
  min-width:0;
}
.landing-v99 .team-card-entry > .team-card{min-width:0;height:100%;}
.landing-v99 .team-card-roster-preview{
  width:44px;
  min-width:44px;
  display:grid;
  place-items:center;
  align-content:center;
  gap:3px;
  padding:7px 5px;
  border:1px solid var(--line);
  border-radius:14px;
  color:var(--muted);
  background:var(--panel-2);
  cursor:pointer;
}
.landing-v99 .team-card-roster-preview:hover,
.landing-v99 .team-card-roster-preview:focus-visible{
  color:var(--text);
  border-color:color-mix(in srgb,var(--team-primary,var(--primary)) 45%,var(--line));
  background:color-mix(in srgb,var(--team-primary,var(--primary)) 9%,var(--panel-2));
}
.landing-v99 .team-card-roster-preview > span{font-size:.58rem;line-height:1.05;text-align:center;}
.landing-v99 .selected-team-preview-actions{display:flex;justify-content:flex-start;margin:10px 0 2px;}

.setup-roster-preview{display:grid;gap:14px;min-width:0;}
.setup-roster-preview > header{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;align-items:center;min-width:0;}
.setup-roster-preview > header .crest{width:58px;height:58px;}
.setup-roster-preview > header h3{margin:2px 0 3px;font-size:1.2rem;overflow-wrap:anywhere;}
.setup-roster-preview > header p{margin:0;color:var(--muted);font-size:.78rem;}
.setup-roster-sectors{display:grid;gap:12px;}
.setup-roster-sector{display:grid;gap:7px;}
.setup-roster-sector > header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px;}
.setup-roster-sector > header strong{font-size:.78rem;letter-spacing:.02em;}
.setup-roster-sector > header span{min-width:28px;padding:3px 7px;border-radius:999px;text-align:center;color:var(--muted);background:var(--chip);font-size:.65rem;}
.setup-roster-sector > div{display:grid;gap:6px;}
.setup-roster-player{display:grid;grid-template-columns:34px minmax(0,1fr) 38px;gap:9px;align-items:center;padding:9px 10px;border:1px solid var(--line);border-radius:12px;background:var(--panel-2);min-width:0;}
.setup-roster-shirt{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:var(--chip);font-size:.72rem;font-weight:700;}
.setup-roster-player > div{min-width:0;}
.setup-roster-player > div strong{display:block;font-size:.78rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.setup-roster-player > div small{display:block;margin-top:2px;color:var(--muted);font-size:.67rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.setup-roster-player > b{justify-self:end;font-size:.83rem;font-weight:700;}
.setup-roster-preview > footer{padding-top:2px;color:var(--muted);font-size:.68rem;line-height:1.45;}
.setup-roster-generated-note{display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;align-items:start;padding:13px;border:1px dashed var(--line);border-radius:14px;background:var(--panel-2);}
.setup-roster-generated-note > i{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--chip);}
.setup-roster-generated-note strong{display:block;font-size:.78rem;}
.setup-roster-generated-note p{margin:4px 0 0;color:var(--muted);font-size:.71rem;line-height:1.5;}
.ai-club-preview-roster{justify-self:start;}

@media (max-width:560px){
  .landing-v99 .team-card-entry{grid-template-columns:minmax(0,1fr) 42px;gap:5px;}
  .landing-v99 .team-card-roster-preview{width:42px;min-width:42px;padding-inline:4px;}
  .setup-roster-player{grid-template-columns:32px minmax(0,1fr) 34px;padding:8px;gap:8px;}
}


/* ==========================================================
   V549 · legibilidade de formulários e componentes dinâmicos
   ========================================================== */

/* Textareas compartilham uma margem interna mínima. Regras mais específicas
   continuam livres para ajustar controles compactos quando necessário. */
textarea{
  padding:10px 12px;
  box-sizing:border-box;
}

/* Dia de jogo: competição/fase/rodada são informação, não decoração truncável.
   O chip cresce verticalmente e mantém o texto integral em telas estreitas. */
.matchday-cinematic.team-dual-tone > .kicker{
  display:flex;
  width:fit-content;
  max-width:100%;
  white-space:normal!important;
  overflow:visible!important;
  text-overflow:clip!important;
  overflow-wrap:anywhere;
  word-break:normal;
  line-height:1.35;
}

/* O tema do clube continua aparecendo na borda, mas a superfície da aba é
   neutra e escura para o robô branco manter contraste em qualquer paleta. */
.automation-global-control:not(.is-counting) .automation-global-tab{
  background:linear-gradient(160deg,#213028,#101713);
}
.automation-global-control .automation-global-tab .fa-robot{
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  filter:drop-shadow(0 1px 1px rgba(0,0,0,.48));
}

/* ==========================================================
   V550 · ação Desativar consistente em qualquer tema
   ========================================================== */
.automation-global-control .automation-global-disable{
  height:36px;
  min-height:36px;
  align-self:center;
  margin:0;
  transform:translateY(1px);
  border-color:#c84b5b!important;
  background:#8f1f2f!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  box-shadow:0 2px 8px rgba(0,0,0,.18);
}
.automation-global-control .automation-global-disable .fa-solid{
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
}
.automation-global-control .automation-global-disable:hover,
.automation-global-control .automation-global-disable:focus-visible{
  background:#a9283a!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
}
.automation-global-control .automation-global-disable:active{
  background:#7c1827!important;
  color:#fff!important;
}

/* ==========================================================
   V551 · mudança de divisão: confirmação factual e legível
   ========================================================== */
.league-movement-summary{
  display:grid;
  gap:14px;
  padding:16px;
  border:1px solid color-mix(in srgb,var(--line) 72%,transparent);
  border-radius:18px;
  background:linear-gradient(155deg,color-mix(in srgb,var(--panel) 96%,var(--primary) 4%),var(--panel));
}
.league-movement-summary.is-promotion{
  border-color:color-mix(in srgb,#45c887 52%,var(--line));
}
.league-movement-summary.is-relegation{
  border-color:color-mix(in srgb,#e05d6f 56%,var(--line));
}
.league-movement-hero{
  display:grid;
  grid-template-columns:auto minmax(0,1fr);
  align-items:center;
  gap:12px;
}
.league-movement-hero h3{margin:2px 0 4px;font-size:1.08rem;line-height:1.15}
.league-movement-hero p{margin:0;color:var(--muted);font-size:.72rem;line-height:1.45}
.league-movement-icon{
  width:52px;
  height:52px;
  display:grid;
  place-items:center;
  border-radius:16px;
  font-size:1.2rem;
  background:color-mix(in srgb,var(--primary) 20%,var(--panel));
  color:var(--text);
}
.league-movement-summary.is-promotion .league-movement-icon{background:rgba(45,154,96,.18);color:#75dfa7}
.league-movement-summary.is-relegation .league-movement-icon{background:rgba(179,48,66,.2);color:#ff9aa7}
.league-movement-route{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);
  gap:8px;
  align-items:stretch;
}
.league-movement-route article{
  min-width:0;
  display:grid;
  align-content:center;
  gap:3px;
  padding:10px;
  border:1px solid var(--line);
  border-radius:12px;
  background:color-mix(in srgb,var(--panel-2) 88%,transparent);
}
.league-movement-route article small{color:var(--muted);font-size:.54rem;text-transform:uppercase;letter-spacing:.04em}
.league-movement-route article strong{font-size:.68rem;line-height:1.25;overflow-wrap:anywhere}
.league-movement-route article span{color:var(--muted);font-size:.58rem}
.league-movement-route-arrow{align-self:center;display:grid;place-items:center;width:30px;height:30px;border-radius:999px;background:var(--panel-2);color:var(--text)}
.league-movement-note{margin:0;padding:10px 11px;border-radius:12px;background:rgba(255,255,255,.045);color:var(--muted);font-size:.64rem;line-height:1.45}
@media(max-width:480px){
  .league-movement-route{grid-template-columns:1fr}
  .league-movement-route-arrow{margin:auto;transform:rotate(90deg)}
}


/* V552 · nome futebolístico em destaque; nome civil/completo só como dado
   secundário em contextos que realmente exibem detalhes do atleta. */
.player-full-name-meta,
.player-profile-full-name,
.editor-player-full-name{
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: .56rem;
  font-weight: 500;
  line-height: 1.35;
  overflow-wrap: anywhere;
}
.player-full-name-detail{
  display: flex;
  align-items: baseline;
